INSERT INTO `locales_source` VALUES ('2095','The <em>Powered by Drupal</em> block is an optional link to the home page of the Drupal project. While there is absolutely no requirement that sites feature this link, it may be used to show support for Drupal.','','11.3.3'),('2096','Powered by Drupal','','11.3.3'),('2097','Compact mode','','none'),('2098','Image toolkit','','11.3.3'),('2099','Choose which image toolkit to use if you have installed optional toolkits.','','11.3.3'),('2100','Date and time','','11.3.3'),('2101','-1 (Unlimited)','','none'),('2102','PHP memory limit','','11.3.3'),('2103','Consider increasing your PHP memory limit to %memory_minimum_limit to help prevent errors in the installation process.','','none'),('2104','Consider increasing your PHP memory limit to %memory_minimum_limit to help prevent errors in the update process.','','none'),('2105','Depending on your configuration, Drupal can run with a %memory_limit PHP memory limit. However, a %memory_minimum_limit PHP memory limit or above is recommended, especially if your site uses additional custom or contributed modules.','','none'),('2106','Increase the memory limit by editing the memory_limit parameter in the file %configuration-file and then restart your web server (or contact your system administrator or hosting provider for assistance).','','none'),('2107','Contact your system administrator or hosting provider for assistance with increasing your PHP memory limit.','','none'),('2108','Not protected','','11.3.3'),('2109','The file %file is not protected from modifications and poses a security risk. You must change the file''s permissions to be non-writable.','','11.3.3'),('2110','Cron has not run recently.','','none'),('2111','Cron maintenance tasks','','11.3.3'),('2112','The directory %directory is not writable.','','none'),('2113','Writable (<em>public</em> download method)','','11.3.3'),('2114','Writable (<em>private</em> download method)','','none'),('2115','Database updates','','11.3.3')