INSERT INTO `locales_source` VALUES ('3675','For links corresponding to a Drupal path (external = 0), this connects the link to a {menu_router}.path for joins.','','none'),('3676','The text displayed for the link, which may be modified by a title callback stored in {menu_router}.','','none'),('3677','The name of the module that generated this link.','','none'),('3678','A flag to indicate if the link points to a full URL starting with a protocol, like http:// (1 = external, 0 = internal).','','none'),('3679','Flag indicating whether any links have this link as a parent (1 = children exist, 0 = no children).','','none'),('3680','Flag for whether this link should be rendered as expanded in menus - expanded links always have their child links displayed, instead of only when the link is in the active trail (1 = expanded, 0 = not expanded)','','none'),('3681','Link weight among links in the same menu at the same depth.','','none'),('3682','The depth relative to the top level. A link with plid == 0 will have depth == 1.','','none'),('3683','A flag to indicate that the user has manually created or edited the link (1 = customized, 0 = not customized).','','none'),('3684','The first mlid in the materialized path. If N = depth, then pN must equal the mlid. If depth > 1 then p(N-1) must equal the plid. All pX where X > depth must equal zero. The columns p1 .. p9 are also called the parents.','','none'),('3685','The second mlid in the materialized path. See p1.','','none'),('3686','The third mlid in the materialized path. See p1.','','none'),('3687','The fourth mlid in the materialized path. See p1.','','none'),('3688','The fifth mlid in the materialized path. See p1.','','none'),('3689','The sixth mlid in the materialized path. See p1.','','none'),('3690','The seventh mlid in the materialized path. See p1.','','none'),('3691','The eighth mlid in the materialized path. See p1.','','none'),('3692','The ninth mlid in the materialized path. See p1.','','none'),('3693','Flag that in