INSERT INTO `locales_source` VALUES ('4418','Preview image style: @style','','11.3.3'),('4419','Deleting a language will remove all interface translations associated with it, and content in this language will be set to be language neutral. This action cannot be undone.','','none'),('4420','No placeholders','','11.3.3'),('4421','Title placeholder: @placeholder_title','','none'),('4422','URL placeholder: @placeholder_url','','none'),('4423','Note that importing large .po files may take several minutes.','','none'),('4424','Content items can be edited using different form modes. Here, you can define which fields are shown and hidden when %type content is edited in each form mode, and define how the field form widgets are displayed in each form mode.','','11.3.3'),('4425','Edit %label content type','','11.3.3'),('4426','The content has either been modified by another user, or you have already submitted modifications. As a result, your changes cannot be saved.','','none'),('4427','Provides a row plugin to display search results.','','none'),('4428','A local file system path where public files will be stored. This directory must exist and be writable by Drupal. This directory must be relative to the Drupal installation directory and be accessible over the web. This must be changed in settings.php','','none'),('4429','%name: the telephone number may not be longer than @max characters.','','none'),('4430','%name: the text may not be longer than @max characters.','','none'),('4431','Summary rows','','11.3.3'),('4432','This form lets administrators add and edit fields for storing user data.','','none'),('4433','This form lets administrators configure how form fields should be displayed when editing a user profile.','','none'),('4434','Alter the HTTP response status code used by this view, mostly helpful for empty results.','','none'),('4435','HTTP status code','','none'),('4436','Always display the more link','','11.3.3'),('4437','Check this to display the more link even if t