INSERT INTO `locales_source` VALUES ('4489','Display the standard add comment link used on regular @entity_type, which will only display if the viewing user has access to add a comment.','','11.3.3'),('4490','Display nodes only if a user posted the @entity_type or commented on the @entity_type.','','11.3.3'),('4491','Comments of the @entity_type using field: @field_name','','none'),('4492','Relate all comments on the @entity_type. This will create 1 duplicate record for every comment. Usually if you need this it is better to create a comment view.','','none'),('4493','Edit comment %title','','none'),('4494','The ID of the entity of which this comment is a reply.','','none'),('4495','The entity type to which this comment is attached.','','none'),('4496','Comment field name','','11.3.3'),('4497','The field name through which this comment was added.','','none'),('4498','Last comment ID','','11.3.3'),('4499','Last comment timestamp','','11.3.3'),('4500','The time that the last comment was created.','','11.3.3'),('4501','Last comment name','','11.3.3'),('4502','The name of the user posting the last comment.','','11.3.3'),('4503','Last comment user ID','','11.3.3'),('4504','The number of comments.','','11.3.3'),('4505','This field manages configuration and presentation of comments on an entity.','','11.3.3'),('4506','Comment list','','11.3.3'),('4507','Show the comment link in the form used on standard entity teasers, rather than the full entity form.','','none'),('4508','Content language and translation','','none'),('4509','Configure language and translation support for content.','','none'),('4510','Select source language','','none'),('4511','Computed date','','none'),('4512','The computed DateTime object.','','none'),('4513','Log entries','','11.3.3'),('4514','Contains a list of log entries.','','none'),('4515','WID','','11.3.3'),('4516','The user on which the log entry as written.','','none'),('4517','The actual message of the log entry.','','none'),('4518','The variables of the log entry in a serialized format.','','none');
INSERT INTO `locales_source` VALUES ('4519','Operation links for the event.','','none'),('4520','URL of the previous page.','','none'),('4521','Date when the event occurred.','','none'),('4522','Replace variables','','none'),('4523','One file only.Maximum @count files.','','11.3.3'),('4524','Configure language support for content.','','11.3.3'),('4525','Managing and displaying link fields','','none'),('4526','Adding link text','','none'),('4527','In the field settings you can define additional link text to be <em>optional</em> or <em>required</em> in any link field.','','none'),('4528','Displaying link text','','none'),('4529','If link text has been submitted for a URL, then by default this link text is displayed as a link to the URL. If you want to display both the link text <em>and</em> the URL, choose the appropriate link format from the drop-down menu in the <em>Manage display</em> page. If you only want to display the URL even if link text has been submitted, choose <em>Link</em> as the format, and then change its <em>Format settings</em> to display <em>URL only</em>.','','none'),('4530','Adding attributes to links','','none'),('4531','You can add attributes to links, by changing the <em>Format settings</em> in the <em>Manage display</em> page. Adding <em>rel="nofollow"</em> notifies search engines that links should not be followed.','','none'),('4532','Validating URLs','','none'),('4533','Number (decimal)','','11.3.3'),('4534','Number (float)','','none'),('4535','Number (integer)','','11.3.3'),('4536','Alias for @id','','11.3.3'),('4537','Raw output for @id','','11.3.3'),('4538','The Serialization module provides a service for serializing and deserializing data to and from formats such as JSON and XML.','','none'),('4539','Serialization is the process of converting data structures like arrays and objects into a string. This allows the data to be represented in a way that is easy to exchange and store (for example, for transmission over the Internet or for storage in a local file system). These representations can then be deserialized to get back to the original data structures.','','none');
INSERT INTO `locales_source` VALUES ('4540','The serializer splits this process into two parts. Normalization converts an object to a normalized array structure. Encoding takes that array and converts it to a string.','','none'),('4541','The uninstall process removes all data related to a module.','','11.3.3'),('4542','The date the term was last updated.','','11.3.3'),('4543','The time that the term was last edited.','','11.3.3'),('4544','Managing and displaying telephone fields','','none'),('4545','Displaying telephone numbers as links','','none'),('4546','The user account %name cannot be canceled.','','none'),('4547','The handler for this item is broken or missing. The following details are available:','','11.3.3'),('4548','Default actions','','11.3.3'),('4549','Grouping @id','','none'),('4550','Columns for @field','','none'),('4551','Sortable for @field','','none'),('4552','Default sort order for @field','','none'),('4553','Default sort for @field','','none'),('4554','Alignment for @field','','none'),('4555','Separator for @field','','none'),('4556','Hide empty column for @field','','none'),('4557','Responsive setting for @field','','none'),('4558','No default sort','','none'),('4559','Page display settings','','11.3.3'),('4560','Block display settings','','11.3.3'),('4561','View basic information','','11.3.3'),('4562','Allow embedded displays','','none'),('4563','Embedded displays can be used in code via views_embed_view().','','none'),('4564','Show SQL query','','none'),('4565','Remove @title','','11.3.3'),('4566','Weight for @id','','11.3.3'),('4567','Group for @id','','11.3.3'),('4568','Remove @id','','11.3.3'),('4569','PHP date format','','none');
