INSERT INTO `locales_source` VALUES ('5494','Comment operation links','','none'),('5495','The target entity type can not be changed after the comment type has been created.','','none'),('5496','Enable the personal contact form by default for new users','','none'),('5497','Add contact form','','none'),('5498','Create and manage contact forms.','','none'),('5499','Edit contact form','','none'),('5500','Default form identifier','','none'),('5501','When listing forms, those with lighter (smaller) weights get listed before forms with heavier (larger) weights. Forms with equal weights are sorted alphabetically.','','none'),('5502','Make this the default form','','none'),('5503','Contact form %label has been updated.','','none'),('5504','Contact form %label has been added.','','none'),('5505','Send yourself a copy','','none'),('5506','%sender-name (@sender-from) sent an email regarding %contact_form.','','none'),('5507','The ID of the associated form.','','none'),('5508','Users may translate this field','','none'),('5509','Content translation field settings','','none'),('5510','Field properties for which to synchronize translations','','none'),('5511','Field column for which to synchronize translations','','none'),('5512','Contextual links for an area on a page are displayed using a contextual links button. There are two ways to make the contextual links button visible:','','none'),('5513','Once the contextual links button for the area of interest is visible, click the button to display the links.','','none'),('5514','The relative date value entered is invalid.','','none'),('5515','Allowed types: @extensions.','','11.3.3'),('5516','Back to content editing','','none'),('5517','\n        <p>You can align images, videos, blockquotes and so on to the left, right or center. Examples:</p>\n        <ul>\n          <li>Align an image to the left: <code>&lt;img src="" data-align="left" /&gt;</code></li>\n          <li>Align an image to the center: <code>&lt;img src="" data-align="center" /&gt;</code></li>\n          <li>Align an image to the right: <code>&lt;img src="" data-align="right" /&gt;</code></li>\n          <li>… and you can apply this to other elements as well: <code>&lt;video src="" data-align="center" /&gt;</code></li>\n        </ul>','','none');
INSERT INTO `locales_source` VALUES ('5518','Align images','','none'),('5519','Uses a <code>data-align</code> attribute on <code>&lt;img&gt;</code> tags to align images.','','none'),('5520','\n        <p>You can caption images, videos, blockquotes, and so on. Examples:</p>\n        <ul>\n            <li><code>&lt;img src="" data-caption="This is a caption" /&gt;</code></li>\n            <li><code>&lt;video src="" data-caption="The Drupal Dance" /&gt;</code></li>\n            <li><code>&lt;blockquote data-caption="Dries Buytaert"&gt;Drupal is awesome!&lt;/blockquote&gt;</code></li>\n            <li><code>&lt;code data-caption="Hello world in JavaScript."&gt;alert("Hello world!");&lt;/code&gt;</code></li>\n        </ul>','','none'),('5521','Caption images','','none'),('5522','Uses a <code>data-caption</code> attribute on <code>&lt;img&gt;</code> tags to caption images.','','none'),('5523','One translation file could not be imported. See the log for details.@count translation files could not be imported. See the log for details.','','none'),('5524','A flag for whether the link should be enabled in menus or hidden.','','11.3.3'),('5525','The time that the menu link was last edited.','','none'),('5526','The timestamp the latest revision of this node was created.','','none'),('5527','Recently created','','none'),('5528','Whether a new revision should be created by default','','none'),('5529','Display author and date information','','11.3.3'),('5530','Breakpoint ID','','none'),('5531','Unable to delete the shortcut for %title.','','none'),('5532','Drupal database update','','none'),('5533','Maximum number of levels','','none'),('5534','<strong>Back up your code</strong>. Hint: when backing up module code, do not leave that backup in the ''modules'' or ''sites/*/modules'' directories as this may confuse Drupal''s auto-discovery mechanism.','','none'),('5535','<strong>Back up your database</strong>. This process will change your database values and in case of emergency you may need to revert to a backup.','','none'),('5536','When you have performed the steps above, you may proceed.','','none');
INSERT INTO `locales_source` VALUES ('5537','This update will been skipped due to the following missing dependencies:','','none'),('5538','This update will be skipped due to an error in the module''s code.','','none'),('5539','The version of Drupal you are updating from has been automatically detected.','','none'),('5540','All errors have been logged.','','none'),('5541','The update process was aborted prematurely while running <strong>update #@version in @module.module</strong>.','','none'),('5542','You may need to check the <code>watchdog</code> database table manually.','','none'),('5543','<strong>Reminder: don''t forget to set the <code>$settings[''update_free_access'']</code> value in your <code>settings.php</code> file back to <code>FALSE</code>.</strong>','','none'),('5544','Failed:','','none'),('5545','Update #@count','','none'),('5546','The following updates returned messages:','','none'),('5547','Review updates','','none'),('5548','Starting updates','','none'),('5549','Install and set as default','','11.3.3'),('5550','Installed themeInstalled themes','','11.3.3'),('5551','Uninstalled themeUninstalled themes','','11.3.3'),('5552','%theme is the default theme and cannot be uninstalled.','','none'),('5553','The %theme theme has been uninstalled.','','none'),('5554','The %theme theme has been installed.','','11.3.3'),('5555','Empty time zone','','none'),('5556','Users may set their own time zone at registration','','none'),('5557','Menu levels','','11.3.3'),('5558','Whether or not the content related to a term is sticky.','','11.3.3'),('5559','Whether or not the content related to a term is sticky. To list sticky content first, set this to descending.','','11.3.3'),('5560','The date the content related to a term was posted.','','11.3.3'),('5561','Telephone numbers can be displayed as links with the scheme name <em>tel:</em> by choosing the <em>Telephone</em> display format on the <em>Manage display</em> page. Any spaces will be stripped out of the link text. This semantic markup improves the user experience on mobile and assistive technology devices.','','none'),('5562','Title to replace basic numeric telephone number display','','none');
