INSERT INTO `locales_source` VALUES ('5618','Tabs are buttons, displayed in a bar across the top of the screen. Some tabs execute an action (such as starting Edit mode), while other tabs toggle which tray is open.','','none'),('5619','Trays','','none'),('5620','Trays are usually lists of links, which can be hierarchical like a menu. If a tray has been toggled open, it is displayed either vertically or horizontally below the tab bar, depending on the browser width. Only one tray may be open at a time. If you click another tab, that tray will replace the tray being displayed. In wide browser widths, the user has the ability to toggle from vertical to horizontal, using a link at the bottom or right of the tray. Hierarchical menus only have open/close behavior in vertical mode; if you display a tray containing a hierarchical menu horizontally, only the top-level links will be available.','','none'),('5621','Your account will be blocked and you will no longer be able to log in. All of your content will remain attributed to your username.','','none'),('5622','Language of the translation of user information','','none'),('5623','Preferred language of the user','','none'),('5624','Preferred admin language','','none'),('5625','Cache metadata','','none'),('5626','Cache contexts','','none'),('5627','Path is empty.','','none'),('5628','No query allowed.','','none'),('5629','Invalid path. Valid characters are alphanumerics as well as "-", ".", "_" and "~".','','none'),('5630','Wrapping','','none'),('5631','Layout Builder','','none'),('5632','Select a @context value:','','none'),('5633','Number of plural indexes in this language.','','none'),('5634','Domain to use for this language.','','none'),('5635','Search result highlighting input','','11.3.3'),('5636','Configuration entity dependencies','','none'),('5637','Content entity dependencies','','none'),('5638','Enforced configuration dependencies','','none'),('5639','String (long) settings','','none'),('5640','URI settings','','none'),('5641','If more than one application will be sharing this database, a unique table name prefix – such as %prefix – will prevent collisions.','','none');
INSERT INTO `locales_source` VALUES ('5642','The author name of the comment.','','none'),('5643','contextual links button','','none'),('5644','No browser language mappings available.','','none'),('5645','The mapping for the %browser browser language code has been deleted.','','none'),('5646','The browser language detection mapping for the %browser browser language code has been deleted.','','none'),('5647','The user or author name. This filter does not check if the user exists and allows partial matching. Does not use autocomplete.','','none'),('5648','Page @items.current','','11.3.3'),('5649','The selected style or row format does not use fields.','','11.3.3'),('5650','The selected display type does not use @type plugins','','11.3.3'),('5651','The entity type','','none'),('5652','Drupal Logo','','11.3.3'),('5653','Entity Type ID','','none'),('5654','Regex','Validation','none'),('5655','Configure Image Styles','','11.3.3'),('5656','Database storage size','','none'),('5657','Text with text format','','none'),('5658','Field widgets','','none'),('5659','Field widget','','none'),('5660','Widget type machine name','','none'),('5661','Textarea display format settings','','none'),('5662','Email field display format settings','','none'),('5663','Link to the entity','','none'),('5664','Link to the @entity_label','','11.3.3'),('5665','Linked to the @entity_label','','none'),('5666','Simple page','','none'),('5667','Page with blocks','','none'),('5668','Jump to the first comment.','','none'),('5669','Jump to the first new comment.','','none'),('5670','Share your thoughts and opinions.','','11.3.3'),('5671','Content translation content settings','','none');
INSERT INTO `locales_source` VALUES ('5672','Content translation enabled','','none'),('5673','Default date type','','none'),('5674','Default date value','','none'),('5675','Persist field storage with no fields','','none'),('5676','Group by column','','none'),('5677','Group by columns','','none'),('5678','Re-use an existing field','','11.3.3'),('5679','Provides a filter plugin that is in use in the following filter formats: %formats','','11.3.3'),('5680','Providing page-specific help','','none'),('5681','Effect settings','','none'),('5682','Content Language Settings','','none'),('5683','Allow to alter the language','','none'),('5684','Influence of ''@title''','','none'),('5685','Installing supporting modules','','none'),('5686','Default indexing settings','','none'),('5687','The default search index will be rebuilt.','','none'),('5688','This will re-index content in the search indexes of all active search pages. Searching will continue to work, but new content won''t be indexed until all existing content has been re-indexed. This action cannot be undone.','','none'),('5689','All search indexes will be rebuilt.','','none'),('5690','Add shortcut link','','none'),('5691','An existing local file system path for storing private files. It should be writable by Drupal and not accessible over the web. This must be changed in settings.php','','none'),('5692','Publish status','','11.3.3'),('5693','Whether or not the content related to a term is published.','','11.3.3'),('5694','Tray "@tray" @action.','','11.3.3'),('5695','Tray @action.','','11.3.3'),('5696','User data field','','none'),('5697','Only users with the selected permission flag will be able to access this display.','','none'),('5698','Only the checked roles will be able to access this display.','','none'),('5699','The formatted text of the area','','none'),('5700','The corresponding entity field','','none'),('5701','The plugin ID','','none');
INSERT INTO `locales_source` VALUES ('5702','Row options','','none'),('5703','Display extender settings','','none'),('5704','View block','','none'),('5705','Leave blank to use the time of form submission.','','none'),('5706','Number integer display format settings','','none'),('5707','Static menu link overrides','','none'),('5708','Entities exist of type %entity_type and %bundle_label %bundle. These entities need to be deleted before importing.','','none'),('5709','Disabled','Plural','11.3.3'),('5710','The language code of the language the comment is written in.','','none'),('5711','The message language code.','','none'),('5712','The source language from which this translation was created.','','none'),('5713','Translation outdated','','none'),('5714','Translation author','','none'),('5715','The author of this translation.','','none'),('5716','A boolean indicating whether the translation is visible to non-translators.','','none'),('5717','Translation created time','','none'),('5718','The Unix timestamp when the translation was created.','','none'),('5719','Translation changed time','','none'),('5720','The Unix timestamp when the translation was most recently saved.','','none'),('5721','Entities and entity types','','none'),('5722','Entity sub-types','','none'),('5723','Some content entity types are further grouped into sub-types (for example, you could have article and page content types within the main site content entity type, and tag and category vocabularies within the taxonomy term entity type); other entity types, such as user accounts, do not have sub-types. Programmers use the term <em>bundle</em> for entity sub-types.','','none'),('5724','Fields and field types','','none'),('5725','Content entity types and sub-types store most of their text, file, and other information in <em>fields</em>. Fields are grouped by <em>field type</em>; field types define what type of data can be stored in that field, such as text, images, or taxonomy term references.','','none'),('5726','Formatters and view modes','','none'),('5727','Content entity types and sub-types can have one or more <em>view modes</em>, used for displaying the entity items. For instance, a content item could be viewed in full content mode on its own page, teaser mode in a list, or RSS mode in a feed. In each view mode, each field can be hidden or displayed, and if it is displayed, you can choose and configure the <em>formatter</em> that is used to display the field. For instance, a long text field can be displayed trimmed or full-length, and taxonomy term reference fields can be displayed in plain text or linked to the taxonomy term page.','','none');
INSERT INTO `locales_source` VALUES ('5728','Widgets and form modes','','none'),('5729','Content entity types and sub-types can have one or more <em>form modes</em>, used for editing. For instance, a content item could be edited in a compact format with only some fields editable, or a full format that allows all fields to be edited. In each form mode, each field can be hidden or displayed, and if it is displayed, you can choose and configure the <em>widget</em> that is used to edit the field. For instance, a taxonomy term reference field can be edited using a select list, radio buttons, or an autocomplete widget.','','none'),('5730','Enabling field types, widgets, and formatters','','none'),('5731','Views entity field handler','','none'),('5732','Creating a field','','none'),('5733','On the <em>Manage fields</em> page for your entity type or sub-type, you can add, configure, and delete fields for that entity type or sub-type. Each field has a <em>machine name</em>, which is used internally to identify the field and must be unique across an entity type; once a field is created, you cannot change the machine name. Most fields have two types of settings. The field-level settings depend on the field type, and affect how the data in the field is stored. Once they are set, they can no longer be changed; examples include how many data values are allowed for the field and where files are stored. The sub-type-level settings are specific to each entity sub-type the field is used on, and they can be changed later; examples include the field label, help text, default value, and whether the field is required or not. You can return to these settings by choosing the <em>Edit</em> link for the field from the <em>Manage fields</em> page.','','none'),('5734','Re-using fields','','none'),('5735','Configuring field editing','','none'),('5736','On the <em>Manage form display</em> page of your entity type or sub-type, you can configure how the field data is edited by default and in each form mode. If your entity type has multiple form modes (on most sites, most entities do not), you can toggle between the form modes at the top of the page, and you can toggle whether each form mode uses the default settings or custom settings in the <em>Custom display settings</em> section. For each field in each form mode, you can select the widget to use for editing; some widgets have additional configuration options, such as the size for a text field, and these can be edited using the Edit button (which looks like a wheel). You can also change the order of the fields on the form. You can exclude a field from a form by choosing <em>Hidden</em> from the widget drop-down list, or by dragging it into the <em>Disabled</em> section.','','none');
INSERT INTO `locales_source` VALUES ('5737','Configuring field display','','none'),('5738','On the <em>Manage display</em> page of your entity type or sub-type, you can configure how each field is displayed by default and in each view mode. If your entity type has multiple view modes, you can toggle between the view modes at the top of the page, and you can toggle whether each view mode uses the default settings or custom settings in the <em>Custom display settings</em> section. For each field in each view mode, you can choose whether and how to display the label of the field from the <em>Label</em> drop-down list. You can also select the formatter to use for display; some formatters have configuration options, which you can edit using the Edit button (which looks like a wheel). You can also change the display order of fields. You can exclude a field from a specific view mode by choosing <em>Hidden</em> from the formatter drop-down list, or by dragging it into the <em>Disabled</em> section.','','none'),('5739','Configuring view and form modes','','none'),('5740','Listing fields','','none'),('5741','Images must be exactly <strong>@size</strong> pixels.','','11.3.3'),('5742','Images must be larger than <strong>@min</strong> pixels. Images larger than <strong>@max</strong> pixels will be resized.','','11.3.3'),('5743','Images must be larger than <strong>@min</strong> pixels.','','11.3.3'),('5744','Images larger than <strong>@max</strong> pixels will be resized.','','11.3.3'),('5745','Define how text is handled by combining filters into text formats.','','11.3.3'),('5746','The menu link language code.','','11.3.3'),('5747','Node authored by (uid)','','none'),('5748','Revision authored by (uid)','','none'),('5749','Content access view grants','','none'),('5750','The location this shortcut points to.','','11.3.3'),('5751','Trusted Host Settings','','11.3.3'),('5752','The trusted_host_patterns setting is set to allow %trusted_host_patterns','','none'),('5753','Change site name, email address, slogan, default front page, and error pages.','','11.3.3'),('5754','This is only used when the site is configured to use a separate administration theme on the Appearance page.','','11.3.3');
INSERT INTO `locales_source` VALUES ('5755','Link to any page','','11.3.3'),('5756','This allows to bypass access checking when linking to internal paths.','','11.3.3'),('5757','Unable to install @extension, %config_names already exists in active configuration.Unable to install @extension, %config_names already exist in active configuration.','','none'),('5758','No access to execute %action on the @entity_type_label %entity_label.','','none'),('5759','narrow','','none'),('5760','Note: content may be kept, unpublished, deleted or transferred to the anonymous user depending on the configured user settings.','','11.3.3'),('5761','The reference view %view_name cannot be found.','','none'),('5762','Enabled','Plural','11.3.3'),('5763','Pre-content','','11.3.3'),('5764','Active menu trail','','none'),('5765','Configuration updates','','11.3.3'),('5766','The listed configuration will be updated.','','11.3.3'),('5767','An entity field containing a password value.','','none'),('5768','An autocomplete text field with tagging support.','','none'),('5769','Block Content revision is a history of changes to block content.','','none'),('5770','Responsive image style %label saved.','','none'),('5771','Field, widget, and formatter information','','none'),('5772','Provided by modules','','none'),('5773','Provided by Drupal core','','none'),('5774','As mentioned previously, some field types, widgets, and formatters are provided by Drupal core. Here are some notes on how to use some of these:','','none'),('5775','<strong>Number fields</strong>: When you add a number field you can choose from three types: <em>decimal</em>, <em>float</em>, and <em>integer</em>. The <em>decimal</em> number field type allows users to enter exact decimal values, with fixed numbers of decimal places. The <em>float</em> number field type allows users to enter approximate decimal values. The <em>integer</em> number field type allows users to enter whole numbers, such as years (for example, 2012) or values (for example, 1, 2, 5, 305). It does not allow decimals.','','none'),('5776','Defining image styles','','none');
INSERT INTO `locales_source` VALUES ('5777','Naming image styles','','none'),('5778','When you define an image style, you will need to choose a displayed name and a machine name. The displayed name is shown in administrative pages, and the machine name is used to generate the URL for accessing an image processed in that style. There are two common approaches to naming image styles: either based on the effects being applied (for example, <em>Square 85x85</em>), or based on where you plan to use it (for example, <em>Profile picture</em>).','','none'),('5779','Configuring image fields','','none'),('5780','The maximum file size that can be uploaded is limited by PHP settings of the server, but you can restrict it further by configuring a <em>Maximum upload size</em> in the field settings (this setting can be changed later). The maximum file size, either from PHP server settings or field configuration, is automatically displayed to users in the help text of the image field.','','none'),('5781','You can also configure a default image that will be used if no image is uploaded in an image field. This default can be defined for all instances of the field in the field storage settings when you create a field, and the setting can be overridden for each entity sub-type that uses the field.','','none'),('5782','Configuring displays and form displays','','none'),('5783','On the <em>Manage display</em> page, you can choose the image formatter, which determines the image style used to display the image in each display mode and whether or not to display the image as a link. On the <em>Manage form display</em> page, you can configure the image upload widget, including setting the preview image style shown on the entity edit form.','','none'),('5784','Selected language configuration','','none'),('5785','Selected default language no longer exists.','','none'),('5786','Language detection configuration saved.','','none'),('5787','Language codes or other custom text to use as a path prefix for URL language detection. For the selected fallback language, this value may be left blank. <strong>Modifying this value may break existing URLs. Use with caution in a production environment.</strong> Example: Specifying "deutsch" as the path prefix code for German results in URLs like "example.com/deutsch/contact".','','none');
INSERT INTO `locales_source` VALUES ('5788','Link URI can be accessed by the user.','Validation','none'),('5789','The path ''@uri'' is inaccessible.','','none'),('5790','The path ''@uri'' is invalid.','','none'),('5791','Indicates whether the menu link should be rediscovered','','11.3.3'),('5792','@title [%language translation]','','none'),('5793','The username of the content author.','','11.3.3'),('5794','Defining responsive image styles','','none'),('5795','Using responsive image styles in Image fields','','none'),('5796','A responsive image style associates an image style with each breakpoint defined by your theme.','','none'),('5797','Responsive image styles','','none'),('5798','Edit responsive image style','','none'),('5799','Duplicate responsive image style','','none'),('5800','Add responsive image style','','none'),('5801','Responsive image style','','none'),('5802','Image style mappings','','none'),('5803','Image style mapping','','none'),('5804','Responsive image mapping type','','none'),('5805','Sizes attribute','','none'),('5806','Image styles to be used when using the ''sizes'' attribute','','none'),('5807','<em>Duplicate responsive image style</em> @label','','none'),('5808','<em>Edit responsive image style</em> @label','','none'),('5809','Responsive image style @label saved.','','none'),('5810','Responsive image style: @responsive_image_style','','none'),('5811','Select a responsive image style.','','none'),('5812','The default drag-and-drop user interface for ordering tables in the administrative interface presents a challenge for some users, including users of screen readers and other assistive technology. The drag-and-drop interface can be disabled in a table by clicking a link labeled "Show row weights" above the table. The replacement interface allows users to order the table by choosing numerical weights instead of dragging table rows.','','none'),('5813','Using maintenance mode','','none'),('5814','Configuring the file system','','none'),('5815','Configuring the image toolkit','','none'),('5816','Are you sure you want to delete the format %name : %format?','','none');
INSERT INTO `locales_source` VALUES ('5817','Managing vocabularies','','none'),('5818','Managing terms','','none'),('5819','Classifying entity content','','none'),('5820','Adding new terms during content creation','','none'),('5821','User email required','Validation','none'),('5822','The target entity','','none'),('5823','Append a destination query string to operation links.','','none'),('5824','Provides links to perform entity operations.','','11.3.3'),('5825','Original language of content in view row','','none'),('5826','@entity_type_label ID','','none'),('5827','Rendering Language','','none'),('5828','All content that supports translations will be displayed in the selected language.','','none'),('5829','The contextual filter values are provided by the URL.','','none'),('5830','The following replacement tokens are available for this field. Note that due to rendering order, you cannot use fields that come after this field; if you need a field not listed here, rearrange your fields.','','11.3.3'),('5831','Enter permission name','','11.3.3'),('5832','Entity reference field storage settings','','none'),('5833','Entity reference field settings','','none'),('5834','Entity reference selection plugin settings','','none'),('5835','Display in native language','','none'),('5836','HTTP cookies','','none'),('5837','HTTP headers','','none'),('5838','Is super user','','none'),('5839','Query arguments','','none'),('5840','Request format','','none'),('5841','A flag indicating whether this is the default translation.','','11.3.3'),('5842','Field settings (@on_label / @off_label)','','none'),('5843','@on_label / @off_label','','none'),('5844','Displayed in native language','','none'),('5845','Hide lower priority columns','','11.3.3'),('5846','Submitted by @username on @datetime','','none');
INSERT INTO `locales_source` VALUES ('5847','With multiple languages configured, registered users can select their preferred language and authors can assign a specific language to content.','','none'),('5848','This page also provides an overview of how much of the site''s interface has been translated for each configured language.','','none'),('5849','This must be an external URL such as %url.','','none'),('5850','No dangerous external protocols','Validation','none'),('5851','No broken internal links','Validation','none'),('5852','Submitted by @author_name on @date','','11.3.3'),('5853','Search looks for exact, case-insensitive keywords; keywords shorter than a minimum length are ignored.','','none'),('5854','Use upper-case OR to get more results. Example: cat OR dog (content contains either "cat" or "dog").','','none'),('5855','You can use upper-case AND to require all words, but this is the same as the default behavior. Example: cat AND dog (same as cat dog, content must contain both "cat" and "dog").','','none'),('5856','Use quotes to search for a phrase. Example: "the cat eats mice".','','none'),('5857','You can precede keywords by - to exclude them; you must still have at least one "positive" keyword. Example: cat -dog (content must contain cat and cannot contain dog).','','none'),('5858','User is admin','','none'),('5859','Include the anonymous user in the matched entities.','','none'),('5860','Include the anonymous user.','','none'),('5861','User search looks for user names and partial user names. Example: mar would match usernames mar, delmar, and maryjane.','','none'),('5862','You can use * as a wildcard within your keyword. Example: m*r would match user names mar, delmar, and elementary.','','none'),('5863','No eligible views were found.','','none'),('5864','The view is not based on a translatable entity type or the site is not multilingual.','','none'),('5865','Display "@display" uses a "more" link but there are no displays it can link to. You need to specify a custom URL.','','none'),('5866','Disabling SQL rewriting will omit all query tags, i. e. disable node access checks as well as override hook_query_alter() implementations in other modules.','','11.3.3');
INSERT INTO `locales_source` VALUES ('5867','@count second@count seconds','','11.3.3'),('5868','Account''s permissions','','none'),('5869','The hashed password','','none'),('5870','Existing password','','none'),('5871','Display the author name.','','none'),('5872','Are you sure you want to create a new %name @type?','','none'),('5873','Using the personal contact form','','none'),('5874','Site visitors can email registered users on your site by using the personal contact form, without knowing or learning the email address of the recipient. When a site visitor is viewing a user profile, the viewer will see a <em>Contact</em> tab or link, which leads to the personal contact form. The personal contact link is not shown when you are viewing your own profile, and users must have both <em>View user information</em> (to see user profiles) and <em>Use users'' personal contact forms</em> permission to see the link. The user whose profile is being viewed must also have their personal contact form enabled (this is a user account setting); viewers with <em>Administer users</em> permission can bypass this setting.','','none'),('5875','Configuring contact forms','','none'),('5876','Linking to contact forms','','none'),('5877','Adding content to contact forms','','none'),('5878','@label (Translation is not supported).','','none'),('5879','@entity using @field_name','','none'),('5880','Relate each @entity with a @field_name set to the @label.','','none'),('5881','Configuring form displays','','none'),('5882','Reference fields have several widgets available on the <em>Manage form display</em> page:','','none'),('5883','The <em>Check boxes/radio buttons</em> widget displays the existing entities for the entity type as check boxes or radio buttons based on the <em>Allowed number of values</em> set for the field.','','none'),('5884','The <em>Select list</em> widget displays the existing entities in a drop-down list or scrolling list box based on the <em>Allowed number of values</em> setting for the field.','','none'),('5885','The <em>Autocomplete</em> widget displays text fields in which users can type entity labels based on the <em>Allowed number of values</em>. The widget can be configured to display all entities that contain the typed characters or restricted to those starting with those characters.','','none');
INSERT INTO `locales_source` VALUES ('5886','The <em>Autocomplete (Tags style)</em> widget displays a multi-text field in which users can type in a comma-separated list of entity labels.','','none'),('5887','Your server is not capable of displaying file upload progress. File upload progress requires an Apache server running PHP with mod_php or Nginx with PHP-FPM.','','none'),('5888','Your server is not capable of displaying file upload progress. File upload progress requires PHP be run with mod_php or PHP-FPM and not as FastCGI.','','none'),('5889','Display download path','','none'),('5890','Display the filemime as icon','','none'),('5891','Detect tar','','none'),('5892','Link this field to the file download URL','','none'),('5893','File link','','11.3.3'),('5894','Include tar in extension','','none'),('5895','If the part of the filename just before the extension is ''.tar'', include this in the extension output.','','none'),('5896','Display the file download URI','','none'),('5897','Display an icon','','none'),('5898','The icon is representing the file type, instead of the MIME text (such as "image/jpeg")','','none'),('5899','Using text fields with text formats','','none'),('5900','Text fields that allow text formats are those with "formatted" in the description. These are <em>Text (formatted, long, with summary)</em>, <em>Text (formatted)</em>, and <em>Text (formatted, long)</em>. You cannot change the type of field once a field has been created.','','none'),('5901','Setting the allowed link type','','none'),('5902','In the field settings you can define the allowed link type to be <em>internal links only</em>, <em>external links only</em>, or <em>both internal and external links</em>. <em>Internal links only</em> and <em>both internal and external links</em> options enable an autocomplete widget for internal links, so a user does not have to copy or remember a URL.','','none'),('5903','Revisions allow you to track differences between multiple versions of your content, and revert to older versions.','','11.3.3'),('5904','@type %title has been reverted to the revision from %revision-date.','','none');
INSERT INTO `locales_source` VALUES ('5905','Speeding up your site','','none'),('5906','Site default language code','','none'),('5907','Page caching','','none'),('5908','Allowing users to add new terms gradually builds a vocabulary as content is added and edited. Users can add new terms if either of the two <em>Autocomplete</em> widgets is chosen for the Taxonomy term reference field in the <em>Manage form display</em> page for the field. You will also need to enable the <em>Create referenced entities if they don''t already exist</em> option, and restrict the field to one vocabulary.','','none'),('5909','If you choose <em>Text (plain)</em> or <em>Text (formatted)</em> as the field type on the <em>Manage fields</em> page, then a field with a single row is displayed. You can change the maximum text length in the <em>Field settings</em> when you set up the field.','','none'),('5910','If you choose <em>Text (plain, long)</em>, <em>Text (formatted, long)</em>, or <em>Text (formatted, long, with summary)</em> on the <em>Manage fields</em> page, then users can insert text of unlimited length. On the <em>Manage form display</em> page, you can set the number of rows that are displayed to users.','','none'),('5911','As an alternative to using a trimmed version of the text, you can enter a separate summary by choosing the <em>Text (formatted, long, with summary)</em> field type on the <em>Manage fields</em> page. Even when <em>Summary input</em> is enabled, and summaries are provided, you can display <em>trimmed</em> text nonetheless by choosing the appropriate format on the <em>Manage display</em> page.','','none'),('5912','Link to the user','','none'),('5913','Display the user or author name.','','none'),('5914','Password required for protected field change','Validation','none'),('5915','Text to use for this variant, @count will be replaced with the value.','','none'),('5916','Text to use for the singular form, @count will be replaced with the value.','','none'),('5917','Contains US ASCII characters only','','none'),('5918','Checkout complete! Thank you for your purchase.','','none');
INSERT INTO `locales_source` VALUES ('5919','Resolving missing content','','none'),('5920','The following @entity-type translations will be deleted:','','none'),('5921','Delete @language translation','','none'),('5922','The @entity-type %label @language translation has been deleted.','','none'),('5923','Are you sure you want to delete the @language translation of the @entity-type %label?','','none'),('5924','The core.extension configuration does not exist.','','none'),('5925','Unable to install the %module module since it does not exist.','','none'),('5926','Unable to uninstall the %module module since the %dependent_module module is installed.','','none'),('5927','Unable to install the %theme theme since it does not exist.','','none'),('5928','Unable to install the %theme theme since it requires the %required_theme theme.','','none'),('5929','Unable to uninstall the %theme theme since the %dependent_theme theme is installed.','','none'),('5930','Configuration %name depends on the %owner module that will not be installed after import.','','none'),('5931','Configuration %name depends on the %owner theme that will not be installed after import.','','none'),('5932','Configuration %name depends on the %owner extension that will not be installed after import.','','none'),('5933','Unable to install the %module module since it requires the %required_module module.Unable to install the %module module since it requires the %required_module modules.','','none'),('5934','Configuration %name depends on the %module module that will not be installed after import.Configuration %name depends on modules (%module) that will not be installed after import.','','none'),('5935','Configuration %name depends on the %theme theme that will not be installed after import.Configuration %name depends on themes (%theme) that will not be installed after import.','','none'),('5936','Configuration %name depends on the %config configuration that will not exist after import.Configuration %name depends on configuration (%config) that will not exist after import.','','none'),('5937','Interface text','','none');
INSERT INTO `locales_source` VALUES ('5938','Order of language detection methods for interface text. If a translation of interface text is available in the detected language, it will be displayed.','','none'),('5939','Inaccessible','','11.3.3'),('5940','NotNull','Validation','none'),('5941','Null','Validation','none'),('5942','The configuration cannot be imported because it failed validation for the following reasons:','','none'),('5943','Link to translate @entity_type_label','','none'),('5944','Provide a translation link to the @entity_type_label.','','none'),('5945','Interface text language selected for page','','11.3.3'),('5946','Customize %language_name language detection to differ from Interface text language detection settings','','none'),('5947','The domain for %language may only contain the domain name, not a trailing slash, protocol and/or port.','','none'),('5948','@language translation of the @type %label has been deleted.','','none'),('5949','Xdebug settings','','none'),('5950','xdebug.max_nesting_level is set to %value.','','none'),('5951','Set <code>xdebug.max_nesting_level=@level</code> in your PHP configuration as some pages in your Drupal site will not work when this setting is too low.','','none'),('5952','Trimmed limit','','none'),('5953','If the summary is not set, the trimmed %label field will end at the last full sentence before this character limit.','','none'),('5954','Trimmed limit: @trim_length characters','','none'),('5955','Working with multilingual views','','none'),('5956','If your site has multiple languages and translated entities, each result row in a view will contain one translation of each involved entity (a view can involve multiple entities if it uses relationships). You can use a filter to restrict your view to one language: without filtering, if an entity has three translations it will add three rows to the results; if you filter by language, at most one result will appear (it could be zero if that particular entity does not have a translation matching your language filter choice). If a view uses relationships, each entity in the relationship needs to be filtered separately. You can filter a view to a fixed language choice, such as English or Spanish, or to the language selected by the page the view is displayed on (the language that is selected for the page by the language detection settings either for Content or User interface).','','none');
INSERT INTO `locales_source` VALUES ('5957','Because each result row contains a specific translation of each entity, field-level filters are also relative to these entity translations. For example, if your view has a filter that specifies that the entity title should contain a particular English word, you will presumably filter out all rows containing Chinese translations, since they will not contain the English word. If your view also has a second filter specifying that the title should contain a particular Chinese word, and if you are using "And" logic for filtering, you will presumably end up with no results in the view, because there are probably not any entity translations containing both the English and Chinese words in the title.','','none'),('5958','Independent of filtering, you can choose the display language (the language used to display the entities and their fields) via a setting on the display. Your language choices are the same as the filter language choices, with an additional choice of "Content language of view row" and "Original language of content in view row", which means to display each entity in the result row using the language that entity has or in which it was originally created. In theory, this would give you the flexibility to filter to French translations, for instance, and then display the results in Spanish. The more usual choices would be to use the same language choices for the display language and each entity filter in the view, or to use the Row language setting for the display.','','none'),('5959','Entity link','','none'),('5960','Entity delete link','','none'),('5961','Entity edit link','','none'),('5962','Link to @entity_type_label','','11.3.3'),('5963','Provide a view link to the @entity_type_label.','','11.3.3'),('5964','Link to edit @entity_type_label','','11.3.3'),('5965','Provide an edit link to the @entity_type_label.','','11.3.3'),('5966','Link to delete @entity_type_label','','11.3.3'),('5967','Provide a delete link to the @entity_type_label.','','11.3.3'),('5968','View','View entity type','11.3.3');
INSERT INTO `locales_source` VALUES ('5969','Options such as paging, table sorting, and exposed filters will not initiate a page refresh.','','11.3.3'),('5970','Select pager','','11.3.3'),('5971','This can be an internal Drupal path such as node/add or an external URL such as "https://www.drupal.org". You may use the "Replacement patterns" above.','','11.3.3'),('5972','Per default the table is hidden for an empty view. With this option it is possible to show an empty table with the text in it.','','none'),('5973','Cache tags','','none'),('5974','Timestamp display format settings','','none'),('5975','Future format','','none'),('5976','Past format','','none'),('5977','@requirements_message (Currently using @item version @version)','','none'),('5978','The MyISAM storage engine is not supported.','','none'),('5979','0 seconds','','none'),('5980','The validation failed because the value conflicts with the value in %field_name, which you cannot access.','','none'),('5981','The @module module is required','','none'),('5982','Use <em>@interval</em> where you want the formatted interval text to appear.','','none'),('5983','How many time interval units should be shown in the formatted output.','','none'),('5984','Future date: %display','','none'),('5985','Past date: %display','','none'),('5986','- Default site/user time zone -','','none'),('5987','Date format: @date_format','','none'),('5988','Time zone: @timezone','','none'),('5989','Revision translation affected','','11.3.3'),('5990','Indicates if the last edit of a translation belongs to current revision.','','11.3.3'),('5991','Configuration archive','','none'),('5992','Your configuration files were successfully uploaded and are ready for import.','','none'),('5993','Translate any configuration including those shipped with modules and themes.','','none'),('5994','Time zone override','','none'),('5995','Datetime custom display format settings','','none'),('5996','Datetime time ago display format settings','','none'),('5997','The time zone selected here will always be used','','none'),('5998','File URI','Validation','none');
INSERT INTO `locales_source` VALUES ('5999','Translate interface text','','11.3.3'),('6000','Translate any interface text including configuration shipped with modules and themes.','','11.3.3'),('6001','Pages requested by anonymous users are stored the first time they are requested and then are reused. Depending on your site configuration and the amount of your web traffic tied to anonymous visitors, the caching system may significantly increase the speed of your site.','','none'),('6002','Configuring the internal page cache','','none'),('6003','Internal Page Cache','','none'),('6004','Configuring for performance','','none'),('6005','Last run: %time ago.','','none'),('6006','The path ''%path'' has to start with a slash.','','none'),('6007','Allow user to control selected display options for this view.','','11.3.3'),('6008','Allow user to control the number of items displayed in this view','','11.3.3'),('6009','Allow user to specify number of items skipped from beginning of this view.','','11.3.3'),('6010','Media library','','none'),('6011','Plural variants','','none'),('6012','Place block <span class="visually-hidden">in the %region region</span>','','11.3.3'),('6013','No blocks available.','','none'),('6014','Exporting the full configuration','','none'),('6015','Importing a full configuration','','none'),('6016','Exporting a single configuration item','','11.3.3'),('6017','Importing a single configuration item','','11.3.3'),('6018','Configuration synchronization','','11.3.3'),('6019','Import and export your configuration.','','11.3.3'),('6020','@date by @username','','11.3.3'),('6021','You must include at least one keyword to match in the content, and punctuation is ignored.You must include at least one keyword to match in the content. Keywords must be at least @count characters, and punctuation is ignored.','','none'),('6022','Manage responsive image styles.','','none'),('6023','This theme is missing a ''content'' region.','','none'),('6024','Apache version','','none'),('6025','Filter by name or description','','11.3.3'),('6026','Enter a part of the module name or description','','11.3.3');
