INSERT INTO `locales_source` VALUES ('6831','Content moderation state','','none'),('6832','content moderation state','','none'),('6833','content moderation states','','none'),('6834','Invalid state transition from %from to %to','','none'),('6835','An automated attempt to create the directory %directory failed, possibly due to a permissions problem. To proceed with the installation, either create the directory and modify its permissions manually or ensure that the installer has the permissions to create it automatically. For more information, see INSTALL.txt or the <a href=":handbook_url">online handbook</a>.','','none'),('6836','The Datetime Range module provides a Date field that stores start dates and times, as well as end dates and times. See the <a href=":field">Field module help</a> and the <a href=":field_ui">Field UI module help</a> pages for general information on fields and how to create and manage them. For more information, see the <a href=":datetime_do">online documentation for the Datetime Range module</a>.','','none'),('6837','Datetime Range','','none'),('6838','Provides the ability to store end dates.','','11.3.3'),('6839','Date range settings','','none'),('6840','Default start date type','','none'),('6841','Default start date value','','none'),('6842','Default end date type','','none'),('6843','Default end date value','','none'),('6844','Date range default display format settings','','none'),('6845','Date range plain display format settings','','none'),('6846','Date range custom display format settings','','none'),('6847','Date range select list display format settings','','none'),('6848','Date separator','','none'),('6849','The string to separate the start and end dates','','none'),('6850','Separator: %separator','','none'),('6851','Default start date','','none'),('6852','Set a default value for the start date.','','none'),('6853','Set a default value for the end date.','','none'),('6854','The relative start date value entered is invalid.','','none'