INSERT INTO `locales_source` VALUES ('7697','Failed to connect to your database server. The server reports the following message: %error.<ul><li>Is the database server running?</li><li>Does the database exist, and have you entered the correct database name?</li><li>Have you entered the correct username and password?</li><li>Have you entered the correct database hostname and port number?</li></ul>','','none'),('7698','Failed to open or create database file %database. The database engine reports the following message when attempting to create the database: %error.','','none'),('7699','Failed to connect to database. The database engine reports the following message: %error.<ul><li>Does the database file exist?</li><li>Does web server have permission to write to the database file?</li>Does the web server have permission to write to the directory the database file should be created in?</li></ul>','','none'),('7700','The number of suggestions that will be listed. Use <em>0</em> to remove the limit.','','none'),('7701','Autocomplete suggestion list size: @size','','11.3.3'),('7702','Bosnia & Herzegovina','','none'),('7703','St. Barthélemy','','none'),('7704','Ceuta & Melilla','','none'),('7705','South Georgia & South Sandwich Islands','','none'),('7706','Heard & McDonald Islands','','none'),('7707','St. Kitts & Nevis','','none'),('7708','St. Martin','','none'),('7709','North Macedonia','','none'),('7710','Macao SAR China','','none'),('7711','St. Pierre & Miquelon','','none'),('7712','Svalbard & Jan Mayen','','none'),('7713','São Tomé & Príncipe','','none'),('7714','Eswatini','','none'),('7715','Turks & Caicos Islands','','none'),('7716','Trinidad & Tobago','','none'),('7717','St. Vincent & Grenadines','','none'),('7718','Wallis & Futuna','','none'),('7719','The path that this alias belongs to.','','11.3.3'),('7720','The source path has to start with a slash.','','11.3.3'),('7721','An alias used with this path.','','11.3.3'),('7722','The alias path has to start with a slash