INSERT INTO `locales_source` VALUES ('7726','The @label workspace can not be published because it contains 1 item in an unpublished moderation state.The @label workspace can not be published because it contains @count items in an unpublished moderation state.','','none'),('7727','Moderation state sort','','none'),('7728','Moderation state field','','none'),('7729','Full string ID','','none'),('7730','A boolean indicating whether this translation needs to be updated','','none'),('7731','JSON:API allowed operations','','none'),('7732','All (create, read, update, delete)','','none'),('7733','It is recommended to <a href=":configure-url">configure</a> JSON:API to only accept all operations if the site requires it. <a href=":docs">Learn more about securing your site with JSON:API.</a>','','none'),('7734','i18n language','','none'),('7735','i18n mode','','none'),('7736','Add section <span class="visually-hidden">at end of layout</span>','','none'),('7737','Add section <span class="visually-hidden">at start of layout</span>','','none'),('7738','Add section <span class="visually-hidden">between @first and @second</span>','','none'),('7739','@region region in @section','','none'),('7740','Remove @section','','none'),('7741','<span class="layout-builder__section-label" aria-hidden="true">@section</span>','','none'),('7742','Configure @section','','none'),('7743','@section, Region: @region','','none'),('7744','Block label','','none'),('7745','Are you sure you want to remove @section?','','none'),('7746','The view mode that is used by default','','none'),('7747','Media types selectable in the Media Library','','none'),('7748','View modes selectable in the "Edit media" dialog','','none'),('7749','Filters out unpublished media if the current user cannot view it.','','none'),('7750','If none are selected, all will be allowed.','','none'),('7751','View modes selectable in the ''Edit media'' dialog','','none'),('7752','If two or more view modes are selected, users will be able to update the view mode that an embedded media item should be displayed in after it has been embedded.  If less than two view modes are selected, media will be embedded using the default view mode and no view mode options will appear after a media item has been embedded.','','none');
INSERT INTO `locales_source` VALUES ('7753','Grid-style vs. table-style interface','','none'),('7754','Media Library settings','','none'),('7755','Manage Media Library settings.','','none'),('7756','Enable advanced UI','','none'),('7757','A path alias set for a specific language will always be used when displaying this page in that language, and takes precedence over path aliases set as <em>- Not specified -</em>.','','11.3.3'),('7758','No path aliases available. <a href=":link">Add URL alias</a>.','','11.3.3'),('7759','Experimental themes found: %theme_list. Experimental themes are provided for testing purposes only. Use at your own risk.','','none'),('7760','Configuration sync directory','','11.3.3'),('7761','Your %file file must define the %setting setting as a string containing the directory in which configuration files can be found.','','none'),('7762','experimental theme','','none'),('7763','A local file system path where temporary files will be stored. This directory should not be accessible over the web. This must be changed in settings.php.','','none'),('7764','Are you sure you wish to install an experimental theme?','','none'),('7765','The following themes are experimental: @themes','','none'),('7766','Internationalization mode.','','none'),('7767','Language from the taxonomy_vocabulary table.','','none'),('7768','Translation of either the name or the description.','','none'),('7769','Language code from locales_target table','','none'),('7770','Require summary','','11.3.3'),('7771','Always show summary','','none'),('7772','The summary will also be visible when marked as required.','','11.3.3'),('7773','The summary field is required for @name','','none'),('7774','Always show the summary field','','11.3.3'),('7775','Summary field will always be visible','','none'),('7776','Too many password recovery requests from your IP address. It is temporarily blocked. Try again later or contact the site administrator.','','none'),('7777','Limit the available operators','','11.3.3'),('7778','List of available operators','','none'),('7779','Limit the available operators to be shown on the exposed filter.','','11.3.3');
INSERT INTO `locales_source` VALUES ('7780','Restrict operators to','','11.3.3'),('7781','Selecting none will make all of them available.','','11.3.3'),('7782','You selected the "@operator" operator as the default value but is not included in the list of limited operators.','','none'),('7783','Provides an interface to create workflows with transitions between different states (for example publication or user status) provided by other modules.','','11.3.3'),('7784','Indicates the workspace that this revision belongs to.','','none'),('7785','Switch to Live','','none'),('7786','Would you like to switch to the live version of the site?','','none'),('7787','Switch to the live version of the site.','','none'),('7788','You are now viewing the live version of the site.','','none'),('7789','Media Library thumbnail (220×220)','','none'),('7790','Delete {{ name }}','','none'),('7791','Viewing help topics','','none'),('7792','The top-level help topics are listed on the main <a href=":help_page">Help page</a>. Links to other topics, including non-top-level help topics, can be found under the "Related" heading when viewing a topic page.','','none'),('7793','Providing help topics','','none'),('7794','Translating help topics','','none'),('7795','The title and body text of help topics provided by contributed modules and themes are translatable using the <a href=":locale_help">Interface Translation module</a>. Topics provided by custom modules and themes are also translatable if they have been viewed at least once in a non-English language, which triggers putting their translatable text into the translation database.','','none'),('7796','Configuring help search','','11.3.3'),('7797','See the <a href=":help_page">Help page</a> for more topics.','','none'),('7798','Help search','','none'),('7799','Configure the settings of a block that was previously placed in a region of a theme.','','11.3.3'),('7800','Click the name of the theme that contains the block.','','11.3.3'),('7801','Optionally, click <em>Demonstrate block regions</em> to see the regions of the theme.','','11.3.3'),('7802','If you only want to change the region where a block is located, or the ordering of blocks within a region, drag blocks to their desired positions and click <em>Save blocks</em>.','','11.3.3');
INSERT INTO `locales_source` VALUES ('7803','If you want to change additional settings, find the region where the block you want to update is currently located, and click <em>Configure</em> in the line of the block description.','','11.3.3'),('7804','Edit the block''s settings. The available settings vary depending on the module that provides the block, but for all blocks you can change:','','11.3.3'),('7805','<em>Block title</em>: The heading for the block on your site -- for some blocks, you will need to check the <em>Override title</em> checkbox in order to enter a title','','11.3.3'),('7806','<em>Display title</em>: Check the box if you want the title displayed','','11.3.3'),('7807','<em>Visibility</em>: Add conditions for when the block should be displayed','','11.3.3'),('7808','<em>Region</em>: Change the theme region the block is displayed in','','11.3.3'),('7809','Click <em>Save block</em>.','','11.3.3'),('7810','What are blocks?','','11.3.3'),('7811','Blocks are boxes of content rendered into an area, or region, of a web page of your site. Blocks are placed and configured specifically for each theme.','','11.3.3'),('7812','What is the block description?','','11.3.3'),('7813','The block description is an identification name for a block, which is shown in the administrative interface. It is not displayed on the site.','','11.3.3'),('7814','What is the block title?','','11.3.3'),('7815','The block title is the heading that is optionally shown to site visitors when the block is placed in a region.','','11.3.3'),('7816','Click the name of the theme that you want to place the block in.','','11.3.3'),('7817','Find the region where you want the block, and click <em>Place block</em> in that region. A modal dialog will pop up.','','11.3.3'),('7818','Find the block you want to place and click <em>Place block</em>. A <em>Configure block</em> modal dialog will pop up.','','11.3.3'),('7819','Enter a description of your block (to be shown to administrators) and the body text for your block.','','11.3.3'),('7820','Enter a label for this block type (shown in the administrative interface). Optionally, edit the automatically-generated machine name or the description.','','11.3.3');
INSERT INTO `locales_source` VALUES ('7821','Click <em>Save</em>. You will be returned to the <em>Block types</em> page.','','11.3.3'),('7822','Click <em>Manage fields</em> in the row of your new block type, and add the desired fields to your block type.','','11.3.3'),('7823','Use contextual links to access administrative tasks without navigating the administrative menu.','','11.3.3'),('7824','What are contextual links?','','11.3.3'),('7825','Visit a non-administrative page on your site, such as the home page.','','11.3.3'),('7826','Locate a block or another area on the page that you want to edit or configure.','','11.3.3'),('7827','Complete your administrative task and save your settings, or cancel the action. You should be returned to the page you started from.','','11.3.3'),('7828','What are security updates?','','11.3.3'),('7829','Any software occasionally has bugs, and sometimes these bugs have security implications. When security bugs are fixed in the core software, modules, or themes that your site uses, they are released in a <em>security update</em>. You will need to apply security updates in order to keep your site secure.','','11.3.3'),('7830','Security tasks','','11.3.3'),('7831','Overview of accessibility','','11.3.3'),('7832','The core Shortcuts module enhances the toolbar with a configurable list of links to commonly-used tasks.','','11.3.3'),('7833','If you install the core Contextual Links module, non-administrative pages will contain links leading to related administrative tasks.','','11.3.3'),('7834','The core Help module displays help topics, and provides a Help block that can be placed on administrative pages to provide an overview of their functionality.','','11.3.3'),('7835','See the related topics listed below for specific tasks.','','11.3.3'),('7836','Set up your site so that users can search for help.','','11.3.3'),('7837','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Search and metadata</em> &gt; <em>Search pages</em>.','','11.3.3'),('7838','Verify that a Help search page is listed in the <em>Search pages</em> section. If not, add a new page of type <em>Help</em>.','','11.3.3');
INSERT INTO `locales_source` VALUES ('7839','Create, view, and use a set of shortcuts to access administrative pages.','','11.3.3'),('7840','What are shortcuts?','','11.3.3'),('7841','<em>Shortcuts</em> are quick links to administrative pages; they are managed by the core Shortcut module. A site can have one or more <em>shortcut sets</em>, which can be shared by one or more users (by default, there is only one set shared by all users); each set contains a limited number of shortcuts. Users need <em>Use shortcuts</em> permission to view shortcuts; <em>Edit current shortcut set</em> permission to add, delete, or edit the shortcuts in the set assigned to them; and <em>Select any shortcut set</em> permission to select a different shortcut set when editing their user profile. There is also an <em>Administer shortcuts</em> permission, which allows an administrator to do any of these actions, as well as select shortcut sets for other users.','','11.3.3'),('7842','Navigate to an administrative page that you want in your shortcut list.','','11.3.3'),('7843','Repeat until all the desired links have been added to your shortcut set.','','11.3.3'),('7844','Click any link in the shortcut bar to go directly to the administrative page.','','11.3.3'),('7845','Configure the basic settings of your site, including the site name, slogan, main email address, default time zone, default country, and the date formats to use.','','11.3.3'),('7846','Enter the site name, slogan, and main email address for your site.','','11.3.3'),('7847','Select the default country and default time zone for your site.','','11.3.3'),('7848','Set up your site to respond appropriately to site errors, including 403 and 404 page responses.','','11.3.3'),('7849','What are 403 and 404 responses?','','11.3.3'),('7850','What other errors can occur?','','11.3.3'),('7851','If desired, create pages to use for 403 and 404 responses. Note the URLs for these pages.','','11.3.3'),('7852','Configure settings related to how user accounts are created and deleted.','','11.3.3'),('7853','What are the settings related to user account creation and deletion?','','11.3.3');
INSERT INTO `locales_source` VALUES ('7854','You can edit the email messages that are sent to users when their accounts are pending, approved, created, blocked, or canceled, or when they request a password reset.','','11.3.3'),('7855','[site:login-url]: The URL where users can log in to your site.','','11.3.3'),('7856','[user:display-name]: The user''s displayed name.','','11.3.3'),('7857','Verify that the other settings are correct.','','11.3.3'),('7858','Topics can be provided by modules or themes. Top-level help topics on your site:','','none'),('7859','Provides the API allowing to rename URLs.','','none'),('7860','The parent workspace.','','none'),('7861','Merge workspace','','none'),('7862','Only top-level workspaces can be published.','','none'),('7863','Merge into @target_label','','none'),('7864','The %label workspace can not be deleted because it has child workspaces.','','none'),('7865','There are no changes that can be merged from %source_label to %target_label.','','none'),('7866','Would you like to merge the contents of the %source_label workspace into %target_label?','','none'),('7867','Merge workspace contents.','','none'),('7868','The contents of the %source_label workspace have been merged into %target_label.','','none'),('7869','There is @count item that can be merged from %source_label to %target_labelThere are @count items that can be merged from %source_label to %target_label','','none'),('7870','Workspace selection','','none'),('7871','Medium 8:7','','none'),('7872','Responsive 3x2','','none'),('7873','Recursive rendering detected when rendering entity %entity_type: %entity_id, using the %field_name field on the %parent_entity_type:%parent_bundle %parent_entity_id entity. Aborting rendering.','','none'),('7874','Response status','','11.3.3'),('7875','Directory "@temp" has insufficient space. There must be at least @space megabytes free.','','none'),('7876','Width: %width pixels','','none'),('7877','Height: %height pixels','','none'),('7878','Heading type','','none'),('7879','The @drupal installer requires that the %default-file file must not be deleted or modified from the original download.','','none');
INSERT INTO `locales_source` VALUES ('7880','Drupal 9 no longer uses the $settings[''install_profile''] value in settings.php and it should be removed.','','none'),('7881','@low_version_number to @high_version_number','','11.3.3'),('7882','Drupal core security coverage','','11.3.3'),('7883','Visit the <a href=":url">release cycle overview</a> for more information on supported releases.','','11.3.3'),('7884','Manage workspace','','none'),('7885','Other workspaces:','','none'),('7886','View all workspaces','','none'),('7887','Not compatible','','none'),('7888','Requires Drupal core:','','11.3.3'),('7889','Covered until @end_version','','11.3.3'),('7890','Coverage has ended','','none'),('7891','<a href=":update_status_report">Update to @next_minor or higher</a> soon to continue receiving security updates.','','none'),('7892','Covered until @date','','none'),('7893','<a href=":update_status_report">Update to a supported minor</a> as soon as possible to continue receiving security updates.','','none'),('7894','Manages breakpoints and breakpoint groups for responsive designs.','','11.3.3'),('7895','Allows users to comment on content.','','11.3.3'),('7896','Allows users to translate configuration text.','','11.3.3'),('7897','Provides site-wide contact forms and forms to contact individual users.','','11.3.3'),('7898','Allows users to translate content.','','11.3.3'),('7899','Provides contextual links to directly access tasks related to page elements.','','11.3.3'),('7900','Logs system events in the database.','','11.3.3'),('7901','Caches pages, including those with dynamic content, for all users.','','11.3.3'),('7902','Provides a user interface for the Field module.','','11.3.3'),('7903','Defines a field type for image media and provides display configuration tools.','','11.3.3'),('7904','Allows users to configure available languages.','','11.3.3'),('7905','Allows users to create menu links.','','11.3.3'),('7906','Users with sufficient access rights will be able to override these options.','','11.3.3'),('7907','Caches pages for anonymous users and can be used when external page cache is not available.','','11.3.3');
INSERT INTO `locales_source` VALUES ('7908','Allows users to create search pages based on plugins provided by other modules.','','11.3.3'),('7909','PHP APCu caching','','11.3.3'),('7910','Enabled (@size)','','none'),('7911','Depending on your configuration, Drupal can run with a @apcu_size APCu limit. However, a @apcu_default_size APCu limit (the default) or above is recommended, especially if your site uses additional custom or contributed modules.','','none'),('7912','Memory available: @available.','','none'),('7913','PHP APCu caching can improve your site''s performance considerably. It is <strong>highly recommended</strong> to have <a href="https://www.php.net/manual/apcu.installation.php" target="_blank">APCu</a> installed on your server.','','11.3.3'),('7914','The version of Drupal you are trying to update from is too old','','none'),('7915','Unsupported schema version: @module','','none'),('7916','The installed version of the %module module is too old to update. Update to an intermediate version first (last removed version: @last_removed_version, installed version: @installed_version).','','none'),('7917','Provides a user interface for creating and managing views.','','11.3.3'),('7918','<p class="text-align-center">Explore recipes across every type of occasion, ingredient, and skill level.</p>','','none'),('7919','<p class="text-align-center">Explore recipes across every type of occasion, ingredient, and skill level</p>','','none'),('7920','Leave blank for all. Otherwise, the first selected item will be the default instead of "Any".','','none'),('7921','Select %entity_types','','none'),('7922','Select @entity_types','','none'),('7923','MariaDB','','none'),('7924','MySQL, Percona Server, or equivalent','','11.3.3'),('7925','Required by the theme: @theme_namesRequired by the themes: @theme_names','','none'),('7926','@theme','','none'),('7927','@theme (theme) (<span class="admin-disabled">disabled</span>)','','none'),('7928','This theme requires the listed modules to operate correctly.','','none'),('7929','Review the <a href=":url"> suggestions for resolving this incompatibility</a> to repair your installation, and then re-run update.php.','','none');
INSERT INTO `locales_source` VALUES ('7930','Missing updates for: @module','','none'),('7931','Incompatible moduleIncompatible modules','','none'),('7932','Incompatible themeIncompatible themes','','none'),('7933','The following module is installed, but it is incompatible with PHP @version:The following modules are installed, but they are incompatible with PHP @version:','','none'),('7934','The following theme is installed, but it is incompatible with PHP @version:The following themes are installed, but they are incompatible with PHP @version:','','none'),('7935','Missing or invalid moduleMissing or invalid modules','','none'),('7936','Missing or invalid themeMissing or invalid themes','','none'),('7937','@module_name (<span class="admin-missing">missing</span>)','','11.3.3'),('7938','@module_name (<span class="admin-missing">incompatible with</span> this version of Drupal core)','','none'),('7939','@module_name (<span class="admin-missing">incompatible with</span> version @version)','','none'),('7940','@module_name (<span class="admin-disabled">disabled</span>)','','none'),('7941','Unable to install @theme due to missing module dependencies.','','none'),('7942','Empty version','','none'),('7943','Invalid version: @existing_version','','none'),('7944','Stable 9','','none'),('7945','A base theme using Drupal 9.0.0''s core markup and CSS.','','none'),('7946','Ban visitors from one or more IP addresses from accessing and viewing your site.','','none'),('7947','Enter an <em>IP address</em> and click <em>Add</em>.','','none'),('7948','You should see the IP address you entered listed under <em>Banned IP addresses</em>. Repeat the above steps to ban additional IP addresses.','','none'),('7949','What types of data does a site have?','','11.3.3'),('7950','What is a content entity?','','11.3.3'),('7951','What is a field?','','11.3.3'),('7952','What is a reference field?','','11.3.3'),('7953','A <em>reference field</em> is a field that stores a relationship between an entity and one or more other entities, which may belong to the same or different entity type. For example, a <em>Content reference</em> field on a content type stores a relationship between one content item and one or more other content items.','','11.3.3');
INSERT INTO `locales_source` VALUES ('7954','What field types are available?','','11.3.3'),('7955','Comment (provided by the core Comment module): Allows users to add comments to an entity','','11.3.3'),('7956','Date, Timestamp (Datetime module): Stores dates and times','','11.3.3'),('7957','Link (Link module): Stores URLs and link text','','11.3.3'),('7958','Telephone (Telephone module): Stores telephone numbers','','11.3.3'),('7959','What is a formatter?','','11.3.3'),('7960','What is a widget?','','11.3.3'),('7961','Managing content structure overview','','11.3.3'),('7962','Configure your system so that cron will run automatically.','','11.3.3'),('7963','What are cron tasks?','','11.3.3'),('7964','What options are available for running cron?','','11.3.3'),('7965','You can also run cron manually, but this is not the recommended way to make sure it is run periodically.','','11.3.3'),('7966','If you want to run cron right now, click <em>Run cron</em> and wait for cron to finish.','','11.3.3'),('7967','If you are not configuring an outside task, and you have the core Automated Cron module installed, select a schedule for automated cron runs in <em>Cron settings</em> &gt; <em>Run cron every</em>. Click <em>Save configuration</em>.','','11.3.3'),('7968','What is a module?','','11.3.3'),('7969','What is an Experimental module?','','11.3.3'),('7970','An <em>Experimental</em> module is a module that is still in development and is not yet stable. Using Experimental modules on production sites is not recommended.','','11.3.3'),('7971','What are installing and uninstalling?','','11.3.3'),('7972','Extending overview','','11.3.3'),('7973','See the related topics listed below for help performing tasks related to extending the functionality of your site.','','11.3.3'),('7974','Maintaining and troubleshooting overview','','11.3.3'),('7975','Configure your site so that cron runs periodically.','','11.3.3'),('7976','If your site is not behaving as expected, clear the cache before trying to diagnose the problem.','','11.3.3'),('7977','Click <em>Add field</em>.','','11.3.3'),('7978','Click <em>Save and continue</em>.','','11.3.3');
INSERT INTO `locales_source` VALUES ('7979','Use the drag arrows to order the fields in your preferred order.','','11.3.3'),('7980','When you are done making changes, click <em>Save</em>.','','11.3.3'),('7981','What is the cache?','','11.3.3'),('7982','Click <em>Clear all caches</em>. Your site''s cached data will be cleared.','','11.3.3'),('7983','What is maintenance mode?','','11.3.3'),('7984','Click <em>Create new account</em>.','','11.3.3'),('7985','Click <em>Save permissions</em>.','','11.3.3'),('7986','Search by keyword or phrase.','','11.3.3'),('7987','Schema information for module %module was missing from the database. You should manually review the module updates and your database to check if any updates have been skipped up to, and including, %last_update_hook.','','none'),('7988','Add, remove, or rearrange the fields on personal and site-wide contact forms.','','none'),('7989','What are the fields on contact forms?','','none'),('7990','Click <em>Manage form display</em> to change the order or configuration of the fields on the form.','','none'),('7991','Configure personal contact forms for registered users on the website.','','none'),('7992','In the <em>Contact settings</em> section, check/uncheck the box to enable/disable the contact form for new user accounts.','','none'),('7993','Click <em>Save configuration</em>.','','none'),('7994','Click <em>Add contact form</em>.','','none'),('7995','Click <em>Save</em>. You should see your new contact form in the table, along with a link to view it.','','none'),('7996','What are contact forms?','','none'),('7997','There are two different types of contact forms provided by the core Contact module: personal contact forms, which allow users to contact other users on the site, and site-wide contact forms, which allow users to contact site managers or administrators. A site can have more than one site-wide contact form; each has its own fields to fill out, recipients, and URL; you can also change the fields that are shown on personal contact forms.','','none'),('7998','Contact form management tasks','','none'),('7999','See the related topics below for specific tasks.','','none');
INSERT INTO `locales_source` VALUES ('8000','Checked %langcode translation for %project.','','11.3.3'),('8001','Downloaded %langcode translation for %project.','','11.3.3'),('8002','Imported %langcode translation for %project.','','11.3.3'),('8003','Display machine name must contain only lowercase letters, numbers, or underscores.','','none'),('8004','Module %name has an entry in the system.schema key/value storage, but is missing from your site. <a href=":url">More information about this error</a>.','','none'),('8005','Module %name has an entry in the system.schema key/value storage, but is not installed. <a href=":url">More information about this error</a>.','','none'),('8006','Missing required data for configuration: %config','','none'),('8007','Search form (narrow)','','11.3.3'),('8008','Search form (wide)','','11.3.3'),('8009','What are breakpoints?','','11.3.3'),('8010','Breakpoints are the point at which your site''s content will respond to provide the user with the best possible layout to consume the information. A breakpoint separates the height or width of viewports (screens, printers, and other media output types) into steps. For instance, a width breakpoint of 40em creates two steps: one for widths up to 40em and one for widths above 40em. Breakpoints can be used to define when layouts should shift from one form to another, when images should be resized, and other changes that need to respond to changes in viewport height or width.','','11.3.3'),('8011','What are media queries?','','11.3.3'),('8012','What are resolution multipliers?','','11.3.3'),('8013','What is a breakpoint group?','','11.3.3'),('8014','The <em>Breakpoint</em> module allows you to define breakpoints and breakpoint groups in YAML files. Modules and themes can use the API provided by the <em>Breakpoint</em> module to define breakpoints and breakpoint groups, and to assign resolution multipliers to breakpoints.','','11.3.3'),('8015','What is a theme?','','11.3.3'),('8016','What is a base theme?','','11.3.3'),('8017','What is a layout?','','11.3.3'),('8018','Big Pipe module','','11.3.3');
INSERT INTO `locales_source` VALUES ('8019','Online documentation for the Internal Page Cache module','','11.3.3'),('8020','Online documentation for the Internal Dynamic Page Cache module','','11.3.3'),('8021','Online documentation for the BigPipe module','','11.3.3'),('8022','Find the particular sub-type that you want to create a layout for, and click <em>Manage display</em> in the <em>Operations</em> list.','','none'),('8023','Under <em>Layout options</em>, check <em>Use Layout Builder</em>. You can also check the box below to allow each entity item to have its layout individually customized (if it is left unchecked, the site will use the same layout for all items of this entity sub-type).','','none'),('8024','Click <em>Save</em>. You will be returned to the <em>Manage display</em> page, but you will no longer see the table of fields of the classic display manager.','','none'),('8025','Click <em>Manage layout</em> to enter layout management view. A default layout will be set up for you, with a single one-column section containing the fields on your entity sub-type.','','none'),('8026','To remove the default section and start from an empty layout, find and click the <em>Remove</em> button for the default section, which looks like an X. Confirm by clicking <em>Remove</em> in the pop-up dialog.','','none'),('8027','Add new sections, each with one to four columns, to your layout. For instance, you might want a one-column section at the top, a two-column section in the middle, and then a one-column section at the bottom. To add a section, click <em>Add section</em> and click the desired number of columns. For multi-column sections, set the column width percentages and click <em>Add section</em> in the pop-up dialog.','','none'),('8028','In each section, click <em>Add block</em> to add a block. You will see a list of the blocks available on your site, plus a section called <em>Content fields</em> with a block for each field on your content item. Each block can be configured, if desired, with a <em>Title</em>, and for content field blocks, you can also configure the field formatter. Continue to add blocks to your sections until all the desired blocks and fields are displayed.','','none');
INSERT INTO `locales_source` VALUES ('8029','If needed, reorder the blocks by dragging them to new locations. If you hover over a block, a contextual menu will appear that will let you change the configuration of the block, remove the block, or <em>Move</em> blocks within the section using a more compact interface.','','none'),('8030','When you are satisfied with your layout, click <em>Save layout</em>.','','none'),('8031','Creating layout defaults','','none'),('8032','Install a core theme, or a contributed theme that has already been downloaded. Choose the default themes to use for the site and for administrative pages.','','11.3.3'),('8033','Locate the themes that you want to use as the site default theme and for administrative pages.','','11.3.3'),('8034','At the bottom of the page, select the <em>Administration theme</em> that you want to use on administrative pages. Click <em>Save configuration</em> if you selected a new theme.','','11.3.3'),('8035','If you changed the default theme for your site, visit the site home page or another page on the non-administration part of your site and verify that the site is using the new theme. If you changed the administration theme, verify that the new theme is used on administrative pages.','','11.3.3'),('8036','Uninstall a theme that was previously installed, but is no longer being used on the site.','','11.3.3'),('8037','Locate the theme that you want to uninstall, in the <em>Installed themes</em> section.','','11.3.3'),('8038','The form has become outdated. Press the back button, copy any unsaved work in the form, and then reload the page.','','none'),('8039','Configure one or more search pages.','','11.3.3'),('8040','Optionally, disable or delete any search pages that you do not want to have available on the site (disabling is temporary, while deleting is permanent).','','11.3.3'),('8041','If your site uses Chinese, Japanese, or Korean languages, optionally check <em>Simple CJK handling</em> under <em>Default indexing settings</em> to provide some support for these languages.','','11.3.3'),('8042','Users with <em>Use search</em> permission can use the <em>Search form</em> block and <em>Search</em> page; this permission is required for any search configured in the core Search module.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8043','Configuring a previously-placed block','','11.3.3'),('8044','Managing blocks','','11.3.3'),('8045','Placing a block','','11.3.3'),('8046','Managing height, width, and resolution breakpoints','','11.3.3'),('8047','Creating a new contact form','','none'),('8048','Managing contact forms','','none'),('8049','Changing the appearance of your site','','11.3.3'),('8050','Configuring site search','','11.3.3'),('8051','Creating and using shortcut administrative links','','11.3.3'),('8052','Clearing the site cache','','11.3.3'),('8053','Changing basic site settings','','11.3.3'),('8054','Configuring error responses, including 403/404 pages','','11.3.3'),('8055','Enabling and disabling maintenance mode','','11.3.3'),('8056','Installing a module','','11.3.3'),('8057','Uninstalling a module','','11.3.3'),('8058','Installing a theme and setting default themes','','11.3.3'),('8059','Uninstalling an unused theme','','11.3.3'),('8060','Creating a user account','','11.3.3'),('8061','Adding a new role','','11.3.3'),('8062','Managing user accounts and site visitors','','11.3.3'),('8063','Modifying the permissions for a role','','11.3.3'),('8064','Configuring how user accounts are created and deleted','','11.3.3'),('8065','Modifying or deleting a user account','','11.3.3'),('8066','Module Link','','none'),('8067','<em>You haven’t created any frontpage content yet.</em>','','11.3.3'),('8068','Drupal is an open source platform for building amazing digital experiences. It’s made, used, taught, documented, and marketed by the <a href="@drupal_community">Drupal community</a>. Our community is made up of people from around the world with a shared set of <a href="@drupal_values">values</a>, collaborating together in a respectful manner. As we like to say:','','11.3.3'),('8069','Come for the code, stay for the community.','','11.3.3'),('8070','There are a few ways to get started with Drupal:','','11.3.3'),('8071','<a href="@drupal_user_guide">User Guide:</a> Includes installing, administering, site building, and maintaining the content of a Drupal website.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8072','<a href="@create_content">Create Content:</a> Want to get right to work? Start adding content. <strong>Note:</strong> the information on this page will go away once you add content to your site. Read on and bookmark resources of interest.','','11.3.3'),('8073','<a href="@drupal_extend">Extend Drupal:</a> Drupal’s core software can be extended and customized in remarkable ways. Install additional functionality and change the look of your site using addons contributed by our community.','','11.3.3'),('8074','Bookmark these links to our active Drupal community groups and support resources.','','11.3.3'),('8075','<a href="@drupal_events">Upcoming Events:</a> Learn and connect with others at conferences and events held around the world.','','11.3.3'),('8076','<a href="@drupal_community">Community Page:</a> List of key Drupal community groups with their own content.','','11.3.3'),('8077','See <a href="https://www.php.net/manual/datetime.format.php#refsect1-datetime.format-parameters" target="_blank">the documentation for PHP date formats</a>.','','none'),('8078','A user-defined date format. See the <a href="https://www.php.net/manual/datetime.format.php#refsect1-datetime.format-parameters">PHP manual</a> for available options.','','none'),('8079','Manage translations for any entity that the user can edit','','none'),('8080','The Filter module allows administrators to configure text formats. Text formats change how HTML tags and other text will be <em>processed and displayed</em> in the site. They are used to transform text, and also help to defend your website against potentially damaging input from malicious users. Visual text editors can be associated with text formats by using the <a href=":editor_help">Text Editor module</a>. For more information, see the <a href=":filter_do">online documentation for the Filter module</a>.','','none'),('8081','What is a menu?','','11.3.3'),('8082','Enabling web services','','11.3.3'),('8083','What is a web service?','','11.3.3'),('8084','What is serialization?','','11.3.3');
INSERT INTO `locales_source` VALUES ('8085','What is HTTP Basic authentication?','','11.3.3'),('8086','What modules provide web services?','','11.3.3'),('8087','RESTful Web Services module','','11.3.3'),('8088','Connecting text editors to text formats','','11.3.3'),('8089','What is a text editor?','','11.3.3'),('8090','Managing text filters and text formats','','11.3.3'),('8091','Locate the content type you want to configure, and click <em>Edit</em> in the <em>Operations</em> list.','','11.3.3'),('8092','Add a link to a menu. Note that you can also add a link to a menu from the content edit page if menu settings have been configured for the content type.','','11.3.3'),('8093','The core Views module handles the display of views, and the core Views UI module allows you to create, edit, and delete views in the administrative interface. See the related topics listed below for specific tasks (if the Views UI module is installed).','','11.3.3'),('8094','Normal menu link','','none'),('8095','If creating a parent menu link, enter the title of the link.','','none'),('8096','If creating a parent menu link, enter the description of the link.','','none'),('8097','Views cannot create normal menu links for paths with a % in them.','','none'),('8098','A clean, accessible, and flexible Drupal front-end theme.','','11.3.3'),('8099','Wide (1090)','','11.3.3'),('8100','Olivero Medium','','11.3.3'),('8101','For security reasons, your upload has been rejected.','','none'),('8102','Exporting your complete site configuration','','11.3.3'),('8103','Click <em>Export</em> and save the archive file.','','11.3.3'),('8104','Importing your complete site configuration','','11.3.3'),('8105','Browse to find the <em>Configuration archive</em> that you want to import.','','11.3.3'),('8106','Click <em>Import</em>.','','11.3.3'),('8107','Configuration entities are user-defined configuration items grouped by type, such as views, image styles, and content types. Each configuration entity within a type has a similar structure.','','11.3.3'),('8108','Adding an image style','','11.3.3'),('8109','Repeat the previous two steps until all of the effects have been added.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8110','Drag to change the order of the effects. Then click <em>Save</em> to save the new order.','','11.3.3'),('8111','Adding a new media type','','none'),('8112','Overview of Migrating','','none'),('8113','Provides the underlying API for migrating data.','','none'),('8114','Migrating data for an upgrade using the user interface','','none'),('8115','Click <em>Save</em>','','none'),('8116','Human name of the parent node type.','','none'),('8117','Machine name of the parent node type.','','none'),('8118','@title sub-navigation','','none'),('8119','At the bottom of the page, select the new workflow state under <em>Change to:</em> and click <em>Save</em>.','','none'),('8120','Who can configure a workflow?','','none'),('8121','Make a plan for the new workflow:','','none'),('8122','Decide on the settings for each state:','','none'),('8123','Click <em>Add workflow</em>.','','none'),('8124','Click <em>Save</em> to save your workflow.','','none'),('8125','Managing content moderation workflows','','none'),('8126','What is a content moderation workflow?','','none'),('8127','Overview of content moderation workflows','','none'),('8128','On-line documentation about Content Moderation','','none'),('8129','If %identifier is a valid account, an email will be sent with instructions to reset your password.','','none'),('8130','@language translation was not added. To add a translation, you must modify the configuration.','','none'),('8131','No page is specified','','none'),('8132','You may include the following allowed HTML tags with these "Replacement patterns": <code>@tags</code>','','11.3.3'),('8133','There are no @entity_type_plural matching "%value".','','none'),('8134','Many @entity_type_plural are called %value. Specify the one you want by appending the id in parentheses, like "@value (@id)".','','none'),('8135','Multiple @entity_type_plural match this reference; "%multiple". Specify the one you want by appending the id in parentheses, like "@value (@id)".','','none'),('8136','The module ''@module_name'' is providing the database driver ''@driver_name''.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8137','Failed to connect to the server. The server reports the following message: <p class="error">@message</p> For more help adding or updating code on your server, see the <a href=":handbook_url">handbook</a>.','','none'),('8138','HTML tables can be created with table headers and caption/summary elements.','','none'),('8139','Alt text is required by default on images added through CKEditor (note that this can be overridden).','','none'),('8140','Semantic HTML5 figure/figcaption are available to add captions to images.','','none'),('8141','This log is not persistent','','none'),('8142','The Database Logging module logs may be cleared by administrators and automated cron tasks, so they should not be used for <a href=":audit_trail_wiki">forensic logging</a>. For forensic purposes, use the Syslog module.','','none'),('8143','Your upload has been renamed to %filename.','','none'),('8144','Separate extensions with a comma or space. Each extension can contain alphanumeric characters, ''.'', and ''_'', and should start and end with an alphanumeric character.','','11.3.3'),('8145','The list of allowed extensions is not valid. Allowed characters are a-z, 0-9, ''.'', and ''_''. The first and last characters cannot be ''.'' or ''_'', and these two characters cannot appear next to each other. Separate extensions with a comma or space.','','none'),('8146','Add %txt_extension to the list of allowed extensions to securely upload files with a %extension extension. The %txt_extension extension will then be added automatically.','','none'),('8147','Configure the block and click <em>Save block</em>; see @configure_topic for configuration details.','','11.3.3'),('8148','For configuration entities, find the specific entity that you want to translate on the next page, and click <em>Translate</em> under <em>Operations</em>.','','none'),('8149','Click <em>Save configuration</em> when all of your changes are complete.','','none'),('8150','Working with languages and translations','','11.3.3'),('8151','What text can be translated in your site?','','11.3.3');
INSERT INTO `locales_source` VALUES ('8152','There are three types of text that can be translated:','','11.3.3'),('8153','Add a language to your site.','','11.3.3'),('8154','Click <em>Add language</em>.','','11.3.3'),('8155','Configuring language detection and selection','','11.3.3'),('8156','Configure the methods used to decide which language will be used to display text on your site.','','11.3.3'),('8157','What is a language detection method?','','11.3.3'),('8158','What language detection methods are available?','','11.3.3'),('8159','The available detection methods depend on what modules you have installed. Some of the most commonly-used language detection methods are:','','11.3.3'),('8160','Use the language preferences from the user''s browser.','','11.3.3'),('8161','Check the boxes to enable the desired language detection methods, and uncheck boxes for the methods you do not want to use.','','11.3.3'),('8162','Drag the methods to change their order, if desired.','','11.3.3'),('8163','Click <em>Save settings</em>.','','11.3.3'),('8164','Translating user interface text','','11.3.3'),('8165','Enter new translations and click <em>Save translations</em>.','','11.3.3'),('8166','Check the current status of interface translations, and see if there are any updates available.','','11.3.3'),('8167','[user:account-name]: The user''s account name.','','11.3.3'),('8168','If an upgrade has been performed on this site, you will be informed.','','none'),('8169','You need to enter the database credentials of the Drupal site that you want to upgrade. You can also include its files directory in the upgrade. For example local files, /var/www/docroot, or remote files http://www.example.com.','','none'),('8170','If there is existing content on the site that may be overwritten by this upgrade, you will be informed.','','none'),('8171','To import private files from your current Drupal site, enter a local file directory containing your site (e.g. /var/www/docroot). Leave blank to use the same value as Public files directory.','','none'),('8172','Add <a href=":modules">contributed modules</a> to extend your site''s functionality.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8173','Database driver provided by module','','none'),('8174','View user email addresses','','11.3.3'),('8175','Users without this permission will not have access to email addresses on user pages or other places where they might be shown, such as Views and JSON:API responses.','','11.3.3'),('8176','The username or email address is invalid.','','none'),('8177','Password reset form was submitted with an unknown or inactive account: %name.','','none'),('8178','Publish workspace','','none'),('8179','Publish %source_label workspace','','none'),('8180','Would you like to publish the contents of the %label workspace?','','none'),('8181','Publish workspace contents.','','none'),('8182','Successful publication.','','none'),('8183','Publication failed. All errors have been logged.','','none'),('8184','There is @count item that can be published from %source_label to %target_labelThere are @count items that can be published from %source_label to %target_label','','none'),('8185','Publish @count item to @targetPublish @count items to @target','','none'),('8186','Missing help topic %topic','','none'),('8187','Failed to fetch security advisory data:','','none'),('8188','Check <a href=":url">your local system logs</a> for additional error messages.','','none'),('8189','Critical security advisories','','none'),('8190','Only the most highly critical security announcements will be shown. <a href=":advisories-list">View all security announcements</a>.','','none'),('8191','(<a href=":system-help">What are critical security announcements?</a>)','','none'),('8192','Critical security announcements','','none'),('8193','How often to check for security advisories, in hours','','none'),('8194','[user:display-name]\n\nA request to cancel your account has been made at [site:name].\n\nYou may now cancel your account on [site:url-brief] by clicking this link or copying and pasting it into your browser:\n\n[user:cancel-url]\n\nNOTE: The cancellation of your account is not reversible.\n\nThis link expires in one day and nothing will happen if it is not used.\n\n--  [site:name] team','','11.3.3');
INSERT INTO `locales_source` VALUES ('8195','The label of the link.','','none'),('8196','Hero (full width)','','none'),('8197','Move content from %from state to %to state.Move content from %from states to %to state.','','none'),('8198','Your server does not support updating modules and themes from this interface. Instead, update modules and themes by uploading the new versions directly to the server, as documented in <a href=":doc_url">Extending Drupal</a>.','','none'),('8199','Your server does not support adding modules and themes from this interface. Instead, add modules and themes by uploading them directly to the server, as documented in <a href=":doc_url">Extending Drupal</a>.','','none'),('8200','Updating modules and themes requires <strong>@backends access</strong> to your server. See <a href=":doc_url">Extending Drupal</a> for other update methods.Updating modules and themes requires access to your server via one of the following methods: <strong>@backends</strong>. See <a href=":doc_url">Extending Drupal</a> for other update methods.','','none'),('8201','Adding modules and themes requires <strong>@backends access</strong> to your server. See <a href=":doc_url">Extending Drupal</a> for other methods.Adding modules and themes requires access to your server via one of the following methods: <strong>@backends</strong>. See <a href=":doc_url">Extending Drupal</a> for other methods.','','none'),('8202','Configuring comments','','11.3.3'),('8203','Configure a content entity type/subtype to allow commenting, using a comment type that you have configured. See @content_structure_topic for more about content entities and fields, and @comment_type_topic to configure a comment type.','','11.3.3'),('8204','Who can configure comments?','','11.3.3'),('8205','Follow the steps in the related <em>Adding a field to an entity sub-type</em> topic to add a field of type <em>Comments</em> to the desired entity type or sub-type.','','11.3.3'),('8206','On the first field settings page, choose the <em>Comment type</em> to use for this entity type or sub-type. You''ll also notice that the <em>Allowed number of values</em> field cannot be changed for comment fields.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8207','On the next field settings page, enter the desired settings for the comment field:','','11.3.3'),('8208','<em>Show reply form on the same page as comments</em>: whether the comment reply form is displayed on the same page as the comments. If this is not selected, clicking <em>Reply</em> will open a new page with the reply form.','','11.3.3'),('8209','<em>Default value</em>: each individual entity has its own comment settings, but here you can set defaults for the comment settings for this entity type or subtype. The comment settings values are:','','11.3.3'),('8210','<em>Open</em>: comments are allowed.','','11.3.3'),('8211','<em>Closed</em>: past comments remain visible, but no new comments are allowed.','','11.3.3'),('8212','<em>Hidden</em>: past comments are hidden, and no new comments are allowed.','','11.3.3'),('8213','Online documentation for content comment settings','','11.3.3'),('8214','Creating a comment type','','11.3.3'),('8215','Who can create a comment type?','','11.3.3'),('8216','Users with the <em>@comment_permissions_link</em> permission (typically administrators) can create comment types.','','11.3.3'),('8217','Click <em>Add comment type</em>.','','11.3.3'),('8218','In the <em>Target entity type</em> field, select the entity type to be commented on. See @content_structure_topic for more about content entities and fields.','','11.3.3'),('8219','Click <em>Save</em>. The comment type will be created.','','11.3.3'),('8220','Who can disable comments?','','11.3.3'),('8221','You will need the <em>@comment_permissions_link</em> permission in order to disable commenting. You will also need permission to edit the entity that the comments are on.','','11.3.3'),('8222','Under <em>Comment settings</em>, select the desired comment setting:','','11.3.3'),('8223','Save the entity.','','11.3.3'),('8224','Decide which comments are shown on the website.','','11.3.3'),('8225','Who can moderate comments?','','11.3.3'),('8226','Online documentation for moderating comments','','11.3.3'),('8227','Managing comments','','11.3.3');
INSERT INTO `locales_source` VALUES ('8228','What is a comment?','','11.3.3'),('8229','What is a comment type?','','11.3.3'),('8230','Comments are divided into <em>comment types</em>, which are the entity sub-types for the comment entity type. Each comment type has its own fields and its own form and display settings; each type can be used to comment on a single entity type. You can set up different comment types for different commenting purposes on your web site; for example, you might set up a comment type for recipes that has fields "How did it taste?" and "Did the instructions work?", and another comment type for blog entries that has only a generic comment body field.','','11.3.3'),('8231','What is moderation?','','11.3.3'),('8232','Overview of managing comments','','11.3.3'),('8233','Posting comments','','11.3.3'),('8234','Configuring commenting','','11.3.3'),('8235','Moderating comments as discussed above','','11.3.3'),('8236','What is quick editing?','','11.3.3'),('8237','Find the contextual link for the part of the page you want to edit. For example, if you want to edit the settings for a block, the link should be in the top-right corner of the block, or top-left for right-to-left languages.','','11.3.3'),('8238','Make your edits and submit the form.','','11.3.3'),('8239','Enabling inline form errors','','11.3.3'),('8240','What administrative interface components are available?','','11.3.3'),('8241','Accessibility features, to enable all users to perform administrative tasks. See @accessibility_topic for more information.','','11.3.3'),('8242','What are the sections of the administrative menu?','','11.3.3'),('8243','<strong>Configuration:</strong> Configure the settings for various site functionality, including some contributed modules.','','11.3.3'),('8244','Creating a content item','','11.3.3'),('8245','Create and publish a content item. See @content_overview_topic for more about content types and content items.','','11.3.3'),('8246','Who can create content?','','11.3.3'),('8247','In the <em>Manage</em> administrative menu, navigate to <em>@content_link</em>.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8248','Click <em>Add content</em>.','','11.3.3'),('8249','If there is more than one content type defined on your site that you have permission to create, click the name of the type of content you want to create.','','11.3.3'),('8250','Fill in the other fields shown on the edit form for this specific content type.','','11.3.3'),('8251','Creating a content type','','11.3.3'),('8252','Create a new content type. See @content_overview_topic for more about content types.','','11.3.3'),('8253','Who can create a content type?','','11.3.3'),('8254','In the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; <em>@content_types_link</em>.','','11.3.3'),('8255','Click <em>Add content type.</em>','','11.3.3'),('8256','Editing a content item','','11.3.3'),('8257','Who can find and edit content?','','11.3.3'),('8258','Users with the <em>@content_permissions_link</em> permission can use the <em>Content</em> page to find content. Each content type has its own edit permissions. For example, to edit content of type Article, a user would need the <em>Article: Edit own content</em> permission to edit an article they created, or the <em>Article: Edit any content</em> permission to edit an article someone else created. In addition, users with the <em>Bypass content access control</em> or <em>Administer content</em> permission can edit content items of all types. Some contributed modules change the permission structure for editing content.','','11.3.3'),('8259','Optionally, use filters to reduce the list of content items shown:','','11.3.3'),('8260','<em>Content type</em>','','11.3.3'),('8261','<em>Published status</em>','','11.3.3'),('8262','If you enter or select filter values, click <em>Filter</em> to apply the filters.','','11.3.3'),('8263','Optionally, sort the list by clicking a column header. Click again to reverse the order.','','11.3.3'),('8264','To edit the title or other field values for one content item, click <em>Edit</em> in the row of the content item. Update the values and click <em>Save</em>.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8265','A few types of edits can be done in bulk to multiple content items. For example, to publish several unpublished content items, check the boxes in the left column (right column in right-to-left languages) to select the desired content items. For <em>Action</em>, select the <em>Publish content</em> action. Click <em>Apply to selected items</em> to make the change. The other actions under <em>Action</em> work in a similar manner.','','11.3.3'),('8266','What is a content item?','','11.3.3'),('8267','What is a content type?','','11.3.3'),('8268','Content items are divided into <em>content types</em>, which are the entity sub-types for the content item entity type; each content type has its own fields and display settings. For example, you might set up content types for pages, articles, recipes, events, and blog entries on your web site.','','11.3.3'),('8269','The core Node module allows you to define content types, and add and edit content items. The core Field UI module allows you to attach fields to each content type and manage the edit form and display for each content type. See the related topics listed below for specific tasks. Many other core and contributed modules and installation profiles provide pre-defined content types, modify the permission structure for content items, and provide other functionality.','','11.3.3'),('8270','Creating a URL alias for a content item','','11.3.3'),('8271','Give a content item page a human- or SEO-friendly URL alias; you can follow similar steps to create an alias for a taxonomy term page. See @overview_topic for more about aliases.','','11.3.3'),('8272','Who can create URL aliases?','','11.3.3'),('8273','Users with the <em>@path_permissions_link</em> permission can create aliases. To follow the steps in this topic, you will also need permission to edit the content item.','','11.3.3'),('8274','Verify that the page can be visited with the new alias, for example <em>https://example.com/about-us</em>.','','11.3.3'),('8275','Editing a URL alias','','11.3.3');
INSERT INTO `locales_source` VALUES ('8276','Change an existing URL alias, to correct the path or the alias value. See @path_overview_topic for more about aliases.','','11.3.3'),('8277','Click <em>Edit</em> in the dropdown button for the alias that you would like to change.','','11.3.3'),('8278','Note that you can also add new aliases from this page, for any path on your site.','','11.3.3'),('8279','Configuring aliases for URLs','','11.3.3'),('8280','What is a URL?','','11.3.3'),('8281','node/7: Path to a particular content item.','','11.3.3'),('8282','taxonomy/term/6: Path to a taxonomy term page.','','11.3.3'),('8283','What is an alias?','','11.3.3'),('8284','Overview of configuring paths, aliases, and URLs','','11.3.3'),('8285','Configuring taxonomy','','11.3.3'),('8286','Create a taxonomy vocabulary and add a reference field for that vocabulary to a content entity. See @taxonomy_overview_topic for information about taxonomy and @content_structure_topic for more on content entities.','','11.3.3'),('8287','Who can configure a taxonomy vocabulary?','','11.3.3'),('8288','In the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; <em>@taxonomy_admin_link</em>.','','11.3.3'),('8289','Click <em>Add vocabulary</em>.','','11.3.3'),('8290','In the <em>Name</em> field, enter a name for the vocabulary (for example "Ingredients"), which is how it will be shown in the administrative interface. Optionally, add a description.','','11.3.3'),('8291','Click <em>Save</em>. Your vocabulary will be created and you will see the page that lists all the terms in this vocabulary.','','11.3.3'),('8292','Optionally, click <em>Add term</em> to add a term to the new vocabulary. In the <em>Name</em> field, enter the term name (for example "Butter"). Click <em>Save</em>. You will receive a confirmation about the term you created. You may optionally continue to add more terms.','','11.3.3'),('8293','Managing taxonomy','','11.3.3'),('8294','What is taxonomy?','','11.3.3'),('8295','<em>Taxonomy</em> is used to classify website content. One common example of taxonomy is the tags used to classify or categorize posts in a blog website; a cooking website could use an ingredients taxonomy to classify recipes. Individual taxonomy items are known as <em>terms</em> (the blog tags or recipe ingredients in these examples); and a set of terms is known as a <em>vocabulary</em> (the set of all blog post tags, or the set of all recipe ingredients in these examples). Technically, taxonomy terms are an entity type and the entity subtypes are the vocabularies; see @content_structure_topic for more on content entities. Like other entities, taxonomy terms can have fields attached; for instance, you could set up an image field to contain an icon for each term.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8296','An individual vocabulary can organize its terms in a hierarchy, or it could be flat. For example, blog tags normally have a flat structure, while a recipe ingredients vocabulary could be hierarchical (for example, tomatoes could be a sub-term of vegetables, and under tomatoes, you could have green and red tomatoes).','','11.3.3'),('8297','Taxonomy terms are normally attached as reference fields to other content entities, which is how you can use them to classify content. When you set up a taxonomy reference field, you can let users enter terms in two ways:','','11.3.3'),('8298','New terms can be created right on the content editing form.','','11.3.3'),('8299','Fixed list of terms','','11.3.3'),('8300','The list of terms is curated and managed outside the content editing form, and users can only select from the existing list when editing content.','','11.3.3'),('8301','<em>Page settings</em>, <em>Block settings</em>, etc.: settings specific to the display type, such as the URL for a page display. Most display types support an <em>Access</em> setting, where you can choose a Permission or Role that a user must have in order to see the view.','','11.3.3'),('8302','Who can edit views?','','11.3.3'),('8303','In the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; <em>@views</em>. A list of all views is shown.','','11.3.3'),('8304','Verify that the <em>Access</em> settings for the view are at least as restrictive as the permissions necessary to perform the bulk operations. People with permission to see the view, but who don''t have permission to do the bulk operations, will experience problems.','','11.3.3'),('8305','Click <em>Save</em>. The action(s) will be available as bulk operations in the view.','','11.3.3'),('8306','Export a single configuration item to a file. See @config_overview_topic for more information about configuration.','','11.3.3'),('8307','Import the complete configuration of your site from an archive file, such as one that was previously exported (see @export_full_topic). See @config_overview_topic for more information about configuration.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8308','Import a single configuration item in YAML format, such as one that was previously exported (see @export_single_topic). See @config_overview_topic for more information about configuration.','','11.3.3'),('8309','Translate your site configuration to another language. See @language_add_topic if you need to add a new language.','','none'),('8310','Find either the configuration entity type or the simple configuration item that you want to translate in the <em>Label</em> column of the list. Click <em>List</em> under <em>Operations</em> for a configuration entity, or <em>Translate</em> for simple configuration. (See @config_overview_topic to learn more about types of configuration and configuration entities.)','','none'),('8311','The contact form will always have <em>Subject</em> and <em>Message</em> fields. If you want to add more fields, follow the steps in @adding_fields_topic.','','none'),('8312','Create or edit a workflow with various workflow states (for example <em>Concept</em>, <em>Archived</em>, etc.) for moderating content. See @workflows_overview_topic for more information on workflows.','','none'),('8313','Configure language and translation settings for one or more content entity types (see @content_structure_topic for an overview of content entities). To do this, you must have at least two languages configured. Afterwards, you will have a <em>Translate</em> operation available for your content entities, either as a tab or link when you are viewing or editing content, or on content administration pages.','','none'),('8314','Content (blocks, content items, etc.) can be written in English or another language, and can be translated into additional languages. See @content_structure_topic to learn more about content.','','11.3.3'),('8315','Many configuration items also include text that can be translated. Default configuration provided by your site''s software is provided in English; you can also download community-provided translations. See @config_overview_topic to learn more about configuration.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8316','Configure a text format so that when a user is editing text and selects this text format, a text editor installed on your site is shown. Configure the text editor, such as choosing which buttons and functions are available. See @filter_overview_topic for more about text formats.','','11.3.3'),('8317','Follow the steps on @filter_overview_topic to add a new text format or configure an existing text format; when you reach the step about text editors, return to this topic.','','11.3.3'),('8318','Return to @filter_overview_topic to complete the text format configuration, and be sure to save the text format.','','11.3.3'),('8319','Add an entity reference field to an entity sub-type; see @content_structure_topic for more information on entities and reference fields.','','11.3.3'),('8320','Check the indexing status of the Help search page. If it is not fully indexed, see @cron_topic about how to run Cron until indexing is complete.','','11.3.3'),('8321','In the future, you can click <em>Rebuild search index</em> on this page, or @cache_topic, in order to force help topic text to be reindexed for searching. This should be done whenever a module, theme, language, or string translation is updated.','','11.3.3'),('8322','Add a new image style, which can be used to process and display images. See @media_topic for an overview of image styles.','','11.3.3'),('8323','Configure an entity sub-type to have its fields displayed using a layout (see @content_structure_topic for more on entities and fields).','','none'),('8324','A layout consists of one or more <em>sections</em>. Each section can have from one to four <em>columns</em>. You can place blocks, including special blocks for the fields on the entity sub-type, in each column of each section (see @block_overview_topic for more on blocks).','','none'),('8325','Add a new media type that can be referenced in Media reference fields; media types are a content entity type. See @media_topic for an overview of media items and media types, and @content_structure_topic for more information on content entities and fields.','','none');
INSERT INTO `locales_source` VALUES ('8326','Migrate data into a new, empty site, as part of an upgrade from an older version of Drupal. See @migrate_overview_topic for an overview of migrating and upgrading.','','none'),('8327','Configure a responsive image style, which can be used to display images at different sizes on different devices. See @media_topic for an overview of responsive image styles, and @breakpoint_overview_topic for an overview of breakpoints.','','none'),('8328','Select a <em>Fallback image style</em> to use when none of the other styles apply. See @image_style_topic if you need to add a new style.','','none'),('8329','The <em>Content</em> and <em>Help</em> search types provided by the core software pre-index their content and store the results in several database tables that are collectively called the <em>search index</em>. The process of indexing renders the content and breaks it up into words, which can then be matched more efficiently with keyword queries when users perform searches. Search indexing happens during cron runs; see @cron_topic for more information about cron.','','11.3.3'),('8330','Follow the steps in @cron_topic to make sure a cron task has been configured.','','11.3.3'),('8331','In order to configure site search using the core Search module, you will need to configure one or more search pages. You will also need to verify or alter permissions so that the desired user roles can search the site. (See @user_overview_topic for more information about roles and permissions.) For content search, you will also need to make sure that the search index is configured and that the site is fully indexed. Finally, you may wish to place the <em>Search form</em> block on pages of your site, or add the search page to a navigation menu, to give users easy access to search. See the related topics listed below for specific tasks.','','11.3.3'),('8332','Clear the site cache. See @cache_topic for instructions.','','11.3.3'),('8333','Uninstall a module. Your site should be in <em>maintenance mode</em> when you uninstall modules. See @maintenance_topic for details.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8334','Find the section whose settings you want to change, such as <em>Format</em> or <em>Filter criteria</em>. (See @views_overview_topic for more information.)','','11.3.3'),('8335','The core software allows you to configure workflows in which each transition has an associated permission that can be granted to a particular role. See @configuring_workflows_topic for more information.','','none'),('8336','Users with sufficient permissions can change the workflow state of a particular entity. See @changing_states_topic for more information.','','none'),('8337','Remote oEmbed providers database returned invalid or empty list. Using previously stored data. This may contain out of date information.','','none'),('8338','Block type settings','','none'),('8339','@bundle_type is not @bundles or @last','','none'),('8340','@bundle_type is not @bundle','','none'),('8341','Are you sure you want to remove the @entity-type %label from the %region region?','','11.3.3'),('8342','This will remove the block placement. You will need to <a href=":url">place it again</a> in order to undo this action.','','11.3.3'),('8343','The @entity-type %label has been removed from the %region region.','','11.3.3'),('8344','Destination file "%file" exists','','none'),('8345','The file could not be uploaded because the destination "%destination" is invalid.','','none'),('8346','For more information see the <a href=":html-specifications">HTML Living Standard</a> or use your favorite search engine to find other sites that explain HTML.','','none'),('8347','Converts an image to a format (such as JPEG).','','none'),('8348','Determines the content language from the request parameter named ''language_content_entity''.','','none'),('8349','The source field definition for the %type media type is missing.','','none'),('8350','Author/owner name','','none'),('8351','Author/owner URL','','none'),('8352','Media item default name','','none'),('8353','Thumbnail local URI','','none'),('8354','Resource source URL','','none'),('8355','Resource width','','none'),('8356','Resource height','','none');
INSERT INTO `locales_source` VALUES ('8357','Resource HTML representation','','none'),('8358','Defined on the <a href="@appearance">Appearance Settings</a> page.','','none'),('8359','Save and go to list','','11.3.3'),('8360','Automatic updating of Drupal core is not supported. See the <a href=":update-guide">Updating Drupal guide</a> for information on how to update Drupal core manually.','','none'),('8361','Other permissions pages','','none'),('8362','Account %name has been disabled.','','none'),('8363','Delete the account and make its content belong to the %anonymous-name user. This action cannot be undone.','','none'),('8364','Delete the account and its content. This action cannot be undone.','','none'),('8365','To log in to this site, your browser must accept cookies from the domain %domain.','','none'),('8366','Cancellation method','','none'),('8367','This view will be displayed by visiting this path on your site. You may use "%" or named route parameters like "%node" in your URL to represent values that will be used for contextual filters: For example, "node/%node/feed" or "view_path/%". Named route parameters are required when this path matches an existing path. For example, paths such as "taxonomy/term/%taxonomy_term" or "user/%user/custom-view".','','11.3.3'),('8368','This identifier is already used by %label sort handler.','','none'),('8369','Switch to this workspace','','none'),('8370','Workspace changes','','none'),('8371','This workspace has no changes.','','none'),('8372','@entity_type_label: @entity_bundle_label','','none'),('8373','Code Block','','none'),('8374','The CKEditor 5 module provides a highly-accessible, highly-usable visual text editor and adds a toolbar to text fields. Users can use buttons to format content and to create semantically correct and valid HTML. The CKEditor module uses the framework provided by the <a href=":text_editor">Text Editor module</a>. It requires JavaScript to be enabled in the browser. For more information, see the <a href=":doc_url">online documentation for the CKEditor 5 module</a> and the <a href=":cke5_url">CKEditor 5 website</a>.','','none');
INSERT INTO `locales_source` VALUES ('8375','Enabling CKEditor 5 for individual text formats','','none'),('8376','When CKEditor 5 is chosen from the <em>Text editor</em> drop-down menu, its toolbar configuration is displayed. You can add and remove buttons from the <em>Active toolbar</em> by dragging and dropping them. Separators and rows can be added to organize the buttons.','','none'),('8377','Filtering HTML content','','none'),('8378','Unlike other text editors, plugin configuration determines the tags and attributes allowed in text formats using CKEditor 5. If using the <em>Limit allowed HTML tags and correct faulty HTML</em> filter, this filter''s values will be automatically set based on enabled plugins and toolbar items.','','none'),('8379','Developing CKEditor 5 plugins in Drupal','','none'),('8380','See the <a href=":dev_docs_url">online documentation</a> for detailed information on developing CKEditor 5 plugins for use in Drupal.','','none'),('8381','The built in WYSIWYG editor (CKEditor 5) comes with a number of accessibility features. CKEditor 5 comes with built in <a href=":shortcuts">keyboard shortcuts</a>, which can be beneficial for both power users and keyboard only users.','','none'),('8382','To support multilingual page content, CKEditor 5 can be configured to include a language button in the toolbar.','','none'),('8383','With CKEditor 5 this is a\n          read-only field. The allowed HTML tags and attributes are determined\n          by the CKEditor 5 configuration. Manually removing tags would break\n          enabled functionality, and any manually added tags would be removed by\n          CKEditor 5 on render.','','none'),('8384','CKEditor 5','','none'),('8385','Text Format plus Text Editor pair using CKEditor 5','','none'),('8386','CKEditor 5 settings','','none'),('8387','Enabled Headings','','none'),('8388','Source Editing','','none'),('8389','Allowed Tag','','none'),('8390','Button @name has been copied to the active toolbar.','','none'),('8391','Button @name has been removed from the active toolbar.','','none'),('8392','The <em>Source Editing</em> plugin was enabled to support tags and/or attributes that are not explicitly supported by any available CKEditor 5 plugins.','','none');
INSERT INTO `locales_source` VALUES ('8393','These are the headings that will appear in the headings dropdown. If a heading is not chosen here, it does not necessarily mean the corresponding tag is disallowed in the text format.','','none'),('8394','Manually editable HTML tags','','none'),('8395','A list of HTML tags that can be used while editing source. It is only necessary to add tags that are not already supported by other enabled plugins. For example, if "Bold" is enabled, it is not necessary to add the <code>&lt;strong&gt;</code> tag, but it may be necessary to add <code>&lt;dl&gt;&lt;dt&gt;&lt;dd&gt;</code> in a format that does not have a definition list plugin, but requires definition list markup.','','none'),('8396','CKEditor 5 toolbar configuration','','none'),('8397','Press the down arrow key to add to the toolbar.','','none'),('8398','Move this button in the toolbar by pressing the left or right arrow keys. Press the up arrow key to remove from the toolbar.','','none'),('8399','Invalid toolbar value.','','none'),('8400','CKEditor 5 element','Validation','none'),('8401','The following tag is not valid HTML: %provided_element.','','none'),('8402','CKEditor 5 enabled configurable plugins','Validation','none'),('8403','Configuration for the enabled plugin "%plugin_label" (%plugin_id) is missing.','','none'),('8404','CKEditor 5 fundamental text format compatibility','Validation','none'),('8405','CKEditor 5 only works with HTML-based text formats. The "%filter_label" (%filter_plugin_id) filter implies this text format is not HTML anymore.','','none'),('8406','CKEditor 5 needs at least the &lt;p&gt; and &lt;br&gt; tags to be allowed to be able to function. They are not allowed by the "%filter_label" (%filter_plugin_id) filter.','','none'),('8407','The current CKEditor 5 build requires the following elements and attributes: <br><code>@list</code><br>The following elements are not supported: <br><code>@diff</code>','','none'),('8408','The current CKEditor 5 build requires the following elements and attributes: <br><code>@list</code><br>The following elements are missing: <br><code>@diff</code>','','none');
INSERT INTO `locales_source` VALUES ('8409','CKEditor 5 toolbar item conditions must be met','Validation','none'),('8410','The %toolbar_item toolbar item requires image uploads to be enabled.','','none'),('8411','The %toolbar_item toolbar item requires the %filter filter to be enabled.','','none'),('8412','The %toolbar_item toolbar item requires the %plugin plugin to be enabled.','','none'),('8413','The %toolbar_item toolbar item requires the %plugins plugins to be enabled.','','none'),('8414','CKEditor 5 toolbar item','Validation','none'),('8415','CKEditor 5 toolbar item dependency','Validation','none'),('8416','Depends on %toolbar_item, which is not enabled.','','none'),('8417','Move a button into the <em>Active toolbar</em> to enable it, or into the list of <em>Available buttons</em> to disable it. Buttons may be moved with the mouse or keyboard arrow keys.','','none'),('8418','PostgreSQL pg_trgm extension','','none'),('8419','Not created','','none'),('8420','Preview failed','','none'),('8421','Drupal Media toolbar','','none'),('8422','Link media','','none'),('8423','Add %label effect to style %style','','11.3.3'),('8424','Edit %label effect on style %style','','11.3.3'),('8425','Maintenance mode Retry-After header settings','','none'),('8426','Minimum value for Retry-After header in seconds','','none'),('8427','Maximum value for Retry-After header in seconds','','none'),('8428','The MySQL module provides the connection between Drupal and a MySQL, MariaDB or equivalent database. For more information, see the <a href=":mysql">online documentation for the MySQL module</a>.','','none'),('8429','The PostgreSQL module provides the connection between Drupal and a PostgreSQL database. For more information, see the <a href=":pgsql">online documentation for the PostgreSQL module</a>.','','none'),('8430','The SQLite module provides the connection between Drupal and a SQLite database. For more information, see the <a href=":sqlite">online documentation for the SQLite module</a>.','','none'),('8431','Deprecated modules found: %module_list.','','none'),('8432','Deprecated themes found: %theme_list.','','none');
INSERT INTO `locales_source` VALUES ('8433','Database support for JSON','','11.3.3'),('8434','Non-stable modules','','none'),('8435','@lifecycle','','11.3.3'),('8436','View information on the @lifecycle status of the module @module','','11.3.3'),('8437','Help <span class="visually-hidden">for @module</span>','','11.3.3'),('8438','Permissions <span class="visually-hidden">for @module</span>','','11.3.3'),('8439','Configure <span class="visually-hidden">@module</span>','','11.3.3'),('8440','<a href=":url">Deprecated modules</a> are modules that may be removed from the next major release of Drupal core. Use at your own risk.','','none'),('8441','The @name module is deprecated. (more information)','','none'),('8442','about the status of the @name module','','none'),('8443','The following module is experimental: @modules.The following modules are experimental: @modules.','','none'),('8444','Get the actual @label from a @label revision','','none'),('8445','Database connection supports the JSON type.','','none'),('8446','<a href="https://www.drupal.org/docs/system-requirements">Database connection does not support JSON.</a>','','none'),('8447','Media widget','','none'),('8448','Not all functionality may be available because some information could not be retrieved.','','none'),('8449','Allow the user to resize images','','none'),('8450','PostgreSQL has the pg_trgm extension enabled.','','none'),('8451','The <a href=":pg_trgm">pg_trgm</a> PostgreSQL extension is not present. The extension is required by Drupal 10 to improve performance when using PostgreSQL. See <a href=":requirements">Drupal database server requirements</a> for more information.','','none'),('8452','Drupal could not check for the pg_trgm extension: @error.','','none'),('8453','Alternative text override','','none'),('8454','Override media image alternative text','','none'),('8455','Enter media caption','','none'),('8456','Caption media','','none'),('8457','Toggle caption off','','none'),('8458','Toggle caption on','','none'),('8459','Post updating @extension','','none'),('8460','Press the down arrow key to activate','','none');
INSERT INTO `locales_source` VALUES ('8461','Decorative image','','11.3.3'),('8462','Add missing alternative text','','11.3.3'),('8463','Change image alternative text','','11.3.3'),('8464','Source editing should only use otherwise unavailable tags and attributes','Validation','none'),('8465','The following @element_type(s) are already supported by enabled plugins and should not be added to the Source Editing "Manually editable HTML tags" field: %overlapping_tags.','','none'),('8466','The following @element_type(s) are already supported by available plugins and should not be added to the Source Editing "Manually editable HTML tags" field. Instead, enable the following plugins to support these @element_types: %overlapping_tags.','','none'),('8467','There is no staged configuration.','','none'),('8468','The staged configuration is identical to the active configuration.','','none'),('8469','The main way to change the overall appearance of your site is to switch the default theme. The core Layout Builder and Layout Discovery modules allow you to define layouts for your site''s content, and the core Breakpoint module helps themes change appearance for different-sized devices. See the related topics listed below for specific tasks.','','11.3.3'),('8470','Using in-line (quick) settings editing','','11.3.3'),('8471','Edit settings in place.','','11.3.3'),('8472','The core Settings Tray module provides the ability to quickly edit settings inline. It requires the core Contextual Links module in order to expose the links that let you edit in place.','','11.3.3'),('8473','Who can edit settings in place?','','11.3.3'),('8474','In order to follow these steps to edit settings in place, the core Settings Tray module must be installed. Also, either the core Toolbar module or a contributed replacement must be installed. You will need to have <em>Use contextual links</em> permission, as well as permission to edit the particular content or settings.','','11.3.3'),('8475','Find and visit a page on your site that has the settings that you would like to edit.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8476','Click the link to open the contextual links menu, and click <em>Quick edit</em>. An editing form for the settings should appear on the page.','','11.3.3'),('8477','In-place or <em>quick</em> editing. In-place editing of configuration is provided by the core Settings Tray module. See @settings_tray_topic for more information.','','11.3.3'),('8478','Exposes entities and other resources to other applications using a <a href="https://en.wikipedia.org/wiki/Representational_state_transfer">REST</a> implementation. Data is exchanged using a serialization format such as JSON, and transferred using an authentication method such as HTTP Basic Authentication.','','11.3.3'),('8479','Image loading settings','','none'),('8480','Loading attribute','','none'),('8481','Image loading','','11.3.3'),('8482','Image loading attribute','','11.3.3'),('8483','Select the loading attribute for images. <a href=":link">Learn more about the loading attribute for images.</a>','','11.3.3'),('8484','Delays loading the image until that section of the page is visible in the browser. When in doubt, lazy loading is recommended.','','11.3.3'),('8485','Image loading: @attribute','','11.3.3'),('8486','Your PHP installation is too old. Drupal requires at least PHP %version. It is recommended to upgrade to PHP version %recommended or higher for the best ongoing support. See <a href="http://php.net/supported-versions.php">PHP''s version support documentation</a> and the <a href=":php_requirements">Drupal PHP requirements</a> page for more information.','','none'),('8487','It is recommended to upgrade to PHP version %recommended or higher for the best ongoing support.  See <a href="http://php.net/supported-versions.php">PHP''s version support documentation</a> and the <a href=":php_requirements">Drupal PHP requirements</a> page for more information.','','11.3.3'),('8488','View information on the @lifecycle status of the theme @theme','','none'),('8489','Allow reverse list','','none'),('8490','Allow start index','','none'),('8491','Allow the user to reverse an ordered list','','none');
INSERT INTO `locales_source` VALUES ('8492','Allow the user to specify the start index of an ordered list','','none'),('8493','Check <a href=":handbook">this handbook page</a> for details about compatibility issues of contrib modules.','','none'),('8494','Source Editing should never allow self-XSS.','Validation','none'),('8495','The following tag in the Source Editing "Manually editable HTML tags" field is a security risk: %dangerous_tag.','','none'),('8496','Enabled Alignments','','none'),('8497','Alignment type','','none'),('8498','Allow view mode override','','none'),('8499','These are the alignment types that will appear in the alignment dropdown.','','none'),('8500','Allow the user to override the default view mode','','none'),('8501','CKEditor 5 Media plugin in sync with filter settings','Validation','none'),('8502','The CKEditor 5 "%cke5_media_plugin_label" plugin''s "%cke5_allow_view_mode_override_label" setting should be in sync with the "%filter_media_plugin_label" filter''s "%filter_media_allowed_view_modes_label" setting: when checked, two or more view modes must be allowed by the filter.','','none'),('8503','You can choose to send email only if a security update is available, or to be notified about all newer versions. If there are updates available of Drupal core or any of your installed modules and themes, your site will always print a message on the <a href=":status_report">status report</a> page. If there is a security update, an error message will be printed on administration pages for users with <a href=":update_permissions">permission to view update notifications</a>.','','none'),('8504','Congratulations and welcome to the Drupal community.','','11.3.3'),('8505','The %plugin plugin needs another plugin to create <code>@non_creatable_tag</code>, for it to be able to create the following attributes: <code>@attributes_on_tag</code>. Enable a plugin that supports creating this tag. If none exists, you can configure the Source Editing plugin to support it.','','none'),('8506','Olivero Color Scheme Settings','','none'),('8507','These settings adjust the look and feel of the Olivero theme. Changing the color below will change the base hue, saturation, and lightness values the Olivero theme uses to determine its internal colors.','','none');
INSERT INTO `locales_source` VALUES ('8508','Olivero Color Scheme','','none'),('8509','Derivatives will be formed from this color.','','none'),('8510','Base Primary Color','','none'),('8511','@fieldName has changed to @fieldValue','','11.3.3'),('8512','Unable to uninstall the %module module because: @reason.','','none'),('8513','Unable to install the %theme theme since it requires the %required_module module.','','none'),('8514','If the <em>Source</em> button is available in the toolbar, users can click this button to disable the visual editor and edit the HTML source directly. After toggling back, the visual editor uses the HTML tags allowed via plugin configuration (and not explicity disallowed by filters) to format the text. Tags not enabled via plugin configuration will be stripped out of the HTML source when the user toggles back to the text editor.','','none'),('8515','@theme theme','','none'),('8516','Resolve all issues below to continue the installation. For help configuring your database server, see the <a href="https://www.drupal.org/docs/installing-drupal">installation handbook</a>, or contact your hosting provider.','','none'),('8517','Updating to Drupal @current_major is only supported from Drupal version @required_min_version or higher. If you are trying to update from an older version, first update to the latest version of Drupal @previous_major. (<a href=":url">Drupal upgrade guide</a>)','','none'),('8518','Migrating an Existing Text Format to CKEditor 5','','none'),('8519','When switching an existing text format to use CKEditor 5, an automatic process is initiated that helps text formats switching to CKEditor 5 from CKEditor 4 (or no text editor) to do so with minimal effort and zero data loss.','','none'),('8520','This process is designed for there to be no data loss risk in switching to CKEditor 5. However some of your editor''s functionality may not be 100% equivalent to what was available previously. In most cases, these changes are minimal. After the process completes, status and/or warning messages will summarize any changes that occurred, and more detailed information will be available in the site''s logs.','','none');
INSERT INTO `locales_source` VALUES ('8521','CKEditor 5 will attempt to enable plugins that provide equivalent toolbar items to those used prior to switching to CKEditor 5. All core CKEditor 4 plugins and many popular contrib plugins already have CKEditor 5 equivalents. In some cases, functionality that required contrib modules is now built into CKEditor 5. In instances where a plugin does not have an equivalent, no data loss will occur but elements previously provided via the plugin may need to be added manually as HTML via source editing.','','none'),('8522','Additional migration considerations for text formats with restricted HTML','','none'),('8523','The “Allowed HTML tags" field in the “Limit allowed HTML tags and correct Faulty HTML" filter is now read-only','','none'),('8524','This field accurately represents the tags/attributes allowed by a text format, but the allowed tags are based on which plugins are enabled and how they are configured. For example, enabling the Underline plugin adds the &lt;u&gt; tag to “Allowed HTML tags".','','none'),('8525','The &lt;p&gt; and &lt;br &gt; tags will be automatically added to your text format.','','none'),('8526','CKEditor 5 requires the &lt;p&gt; and &lt;br &gt; tags to achieve basic functionality. They will be automatically added to “Allowed HTML tags" on formats that previously did not allow them.','','none'),('8527','Tags/attributes that are not explicitly supported by any plugin are supported by Source Editing','','none'),('8528','When a necessary tag/attribute is not directly supported by an available plugin, the "Source Editing" plugin is enabled. This plugin is typically used for by passing the CKEditor 5 UI and editing contents as HTML source. In the settings for Source Editing, tags/attributes that aren''t available via other plugins are added to Source Editing''s "Manually editable HTML tags" setting so they are supported by the text format.','','none'),('8529','To maintain the capabilities of this text format, <a target="_blank" href=":ck_migration_url">the CKEditor 5 migration</a> did the following:','','none');
INSERT INTO `locales_source` VALUES ('8530','To maintain the capabilities of this text format, the CKEditor 5 migration did the following:','','none'),('8531','Enabled these plugins: (%plugins).','','none'),('8532','Added these tags/attributes to the Source Editing Plugin''s <a target="_blank" href=":source_edit_url">Manually editable HTML tags</a> setting: @tag_list','','none'),('8533','Added these tags/attributes to the Source Editing Plugin''s Manually editable HTML tags setting: @tag_list','','none'),('8534','Additional details are available <a target="_blank" href=":dblog_url">in your logs</a>.','','none'),('8535','Additional details are available in your logs.','','none'),('8536','Updating to CKEditor 5 added support for some previously unsupported tags/attributes.','','none'),('8537','A plugin introduced support for the following:','','none'),('8538','for','Ckeditor 5 tag list','none'),('8539','The @tag tag was added because it is <a target="_blank" href=":fundamental_tag_link">required by CKEditor 5</a>.The @tag tags were added because they are <a target="_blank" href=":fundamental_tag_link">required by CKEditor 5</a>.','','none'),('8540','The @tag tag was added because it is required by CKEditor 5.The @tag tags were added because they are required by CKEditor 5.','','none'),('8541','The tag %tags;The tags %tags;','','none'),('8542','This attribute: %attributes;These attributes: %attributes;','','none'),('8543','The migration of %text_format to CKEditor 5 has been saved.','','none'),('8544','Date range (Datetime range module): Stores time/date periods with a start and an end','','11.3.3'),('8545','Find the view that you would like to edit, and click <em>Edit</em> from the dropdown button. Note that bulk operations work best in a view with a Page display, and a Table format.','','11.3.3'),('8546','Note that anonymous users with this permission are able to edit any content created by any anonymous user.','','11.3.3'),('8547','Note that anonymous users with this permission are able to delete any content created by any anonymous user.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8548','The fallback image style is typically the smallest size image you expect to appear in this space. The fallback image should only appear on a site if an error occurs.','','none'),('8549','The %relationship_name relationship used in %handler_type %handler is not present in the %display_name display.','','none'),('8550','Configure @type @current of @total: @item','','11.3.3'),('8551','Updates failed for the entity type %entity_type, for %entity_ids. Check the logs.','','none'),('8552','Unable to update %entity_type %view due to error @message %function (line %line of %file). <pre>@backtrace_string</pre>','','none'),('8553','Block content entity changed','Validation','none'),('8554','Style label','','none'),('8555','Style tag + classes','','none'),('8556','A list of classes that will be provided in the "Style" dropdown. Enter one or more classes on each line in the format: element.classA.classB|Label. Example: h1.title|Title. Advanced example: h1.fancy.title|Fancy title.<br />These styles should be available in your theme''s CSS file.','','none'),('8557','Line @line-number does not contain a valid value. Enter a valid CSS selector containing one or more classes, followed by a pipe symbol and a label.Lines @line-numbers do not contain a valid value. Enter a valid CSS selector containing one or more classes, followed by a pipe symbol and a label.','','none'),('8558','The following tag is missing the required attribute <code>@required_attribute_name</code>: <code>@provided_element</code>.','','none'),('8559','The following tag does not have the minimum of @min_attribute_value_count allowed values for the required attribute <code>@required_attribute_name</code>: <code>@provided_element</code>.','','none'),('8560','Styles can only be specified for already supported tags.','Validation','none'),('8561','A style can only be specified for an HTML 5 tag. <code>@tag</code> is not an HTML5 tag.','','none'),('8562','A style must only specify classes not supported by other plugins. The <code>@classes</code> classes on <code>@tag</code> are already supported by the enabled %plugin plugin.','','none');
INSERT INTO `locales_source` VALUES ('8563','A style must only specify classes not supported by other plugins. The <code>@classes</code> classes on <code>@tag</code> are supported by the %plugin plugin. Remove this style and enable that plugin instead.','','none'),('8564','Unique label in list','Validation','none'),('8565','The label %label is not unique.','','none'),('8566','The Text Editor module provides a framework that other modules (such as <a href=":ckeditor5">CKEditor5 module</a>) can use to provide toolbars and other functionality that allow users to format text more easily than typing HTML tags directly. For more information, see the <a href=":documentation">online documentation for the Text Editor module</a>.','','none'),('8567','The core Filter, Responsive Image, and Path modules provide settings and display options for entities and fields.','','11.3.3'),('8568','A text editor is software (typically, a JavaScript library) that provides buttons and other command mechanisms to make editing HTML text easier. Some editors are called <em>visual</em> or <em>WYSIWYG (What You See Is What You Get)</em> editors; these editors hide the details of HTML from the user, and instead show formatted output on the screen. The core Text Editor module provides a framework for deploying text editors on your site. The core CKEditor 5 module provides CKEditor 5, which is a widely-used JavaScript text editor that creates clean and valid HTML; the module also enforces the HTML tag restrictions in the associated text format. Various contributed modules provide other editors; to install a new editor, besides installing the module, you may need to download the editor library from a third-party site.','','11.3.3'),('8569','Select <em>CKEditor 5</em> as the <em>Text editor</em>, or another text editor that you have installed. The rest of these steps assume you selected <em>CKEditor 5</em>.','','11.3.3'),('8570','Under <em>Toolbar configuration</em>, drag buttons between <em>Available buttons</em> and <em>Active toolbar</em>; only buttons in <em>Active toolbar</em> will be shown to the user. Focusing or hovering over a button will display a tooltip explaining what the button does.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8571','Drag buttons within <em>Active toolbar</em> to the desired order, and group buttons by dragging them between group identifiers; drag <em>a new group identifier</em> to the toolbar to add additional groups.','','11.3.3'),('8572','If you add buttons that require configuration, the <em>CKEditor 5 plugin settings</em> section will be visible, and provide their respective configuration forms.','','11.3.3'),('8573','Click the link for your administrative theme (such as the core Claro theme), near the top of the page, and verify that there is already a search block for help located in the Help region. If not, follow the steps in the related topic to place the <em>Search form</em> block in the Help region. When configuring the block, choose <em>Help</em> as the search page, and in the <em>Pages</em> tab under <em>Visibility</em>, enter <em>/admin/help</em> to make the search form only visible on the main <em>Help</em> page.','','11.3.3'),('8574','Click the shortcut link to add the page to your shortcut list -- in the core Claro administrative theme, the link looks like a star, and is displayed next to the page title. However, if the page is already in your shortcut set, clicking the shortcut link will remove it from your shortcut set.','','11.3.3'),('8575','Grid - Responsive','','none'),('8576','Maximum number of columns','','none'),('8577','Minimum cell width','','none'),('8578','The maximum number of columns that will be displayed within the grid.','','none'),('8579','Minimum grid cell width','','none'),('8580','The minimum width of the grid cells. If the grid container becomes narrow, the grid cells will reflow onto the next row as needed.','','none'),('8581','Grid gutter spacing','','none'),('8582','The spacing between the grid cells.','','none'),('8583','Failed to download remote thumbnail file due to "%error".','','none'),('8584','CKEditor 5 plugin settings','','none'),('8585','Enter a value like "512" (bytes), "80 KB" (kilobytes) or "50 MB" (megabytes) in order to restrict the allowed file size. If left empty the file sizes could be limited only by PHP''s maximum post and file upload sizes (current limit <strong>%limit</strong>).','','11.3.3');
INSERT INTO `locales_source` VALUES ('8586','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>People</em> &gt; <em>@ban_link</em>','','none'),('8587','In the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; <em>@layout_link</em>.','','11.3.3'),('8588','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Development</em> &gt; <em>Configuration synchronization</em> &gt; <em>@export_link</em>.','','11.3.3'),('8589','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Development</em> &gt; <em>Configuration synchronization</em> &gt; <em>Export</em> &gt; <em>@single_export_link</em>.','','11.3.3'),('8590','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Development</em> &gt; <em>Configuration synchronization</em> &gt; <em>@import_link</em>.','','11.3.3'),('8591','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Development</em> &gt; <em>Configuration synchronization</em> &gt; <em>Import</em> &gt; <em>@single_import_link</em>.','','11.3.3'),('8592','In the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; <em>@contact_link</em>.','','none'),('8593','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>People</em> &gt; <em>@config_link</em>.','','none'),('8594','In the <em>Manage</em> administrative menu, navigate to <em>People</em> &gt; <em>@permission_link</em>.','','none'),('8595','In the <em>Manage</em> administration menu, navigate to <em>Configuration</em> &gt; <em>System</em> &gt; <em>@cron_link</em>. Note the <em>Last run</em> time on the page.','','11.3.3'),('8596','What are security advisories?','','11.3.3'),('8597','A security advisory is a public announcement about a reported security problem in the core software. Contributed projects with a shield icon and "Stable releases for this project are covered by the security advisory policy" on their project page are also covered by Drupal''s security advisory policy. Security advisories are managed by the <a href="https://www.drupal.org/drupal-security-team">Drupal Security Team</a>.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8598','<a href="https://www.drupal.org/drupal-security-team/security-advisory-process-and-permissions-policy">Security advisory process and permissions policy</a>','','11.3.3'),('8599','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Content Authoring</em> &gt; <em>@overview_link</em>. The <em>Text editor</em> column in the table shows the text editor that is currently connected to each text format, if any.','','11.3.3'),('8600','Navigate to the page for managing the entity sub-type you want to add the field to. For example, to add a field to a content type, in the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; <em>@content_types_link</em>.','','11.3.3'),('8601','Navigate to the page for managing the entity type you want to add the field to. For example, to add a field to a content type, in the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; <em>@content_types_link</em>.','','11.3.3'),('8602','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Content Authoring</em> &gt; <em>@overview_link</em>. If you do not have the core Text Editor module installed, the menu link and page title will instead be <em>Text formats</em>.','','11.3.3'),('8603','In the <em>Manage</em> administrative menu, navigate to <em>@help_link</em>. Verify that the search block is visible, and try a search.','','11.3.3'),('8604','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Media</em> &gt; @styles_link.','','11.3.3'),('8605','Navigate to the page for managing the entity type you want to add the field to. For example, to add a field to a content type, in the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; @content_types_link.','','none'),('8606','In the <em>Manage</em> administrative menu, navigate to <em>Reports</em> &gt; <em>@translation_updates_link</em>. This report is only available if the core Update Status module is installed.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8607','In the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; @media_link.','','none'),('8608','In the <em>Manage</em> administrative menu, navigate to <em>Structure</em> &gt; @content_types_link.','','11.3.3'),('8609','In the <em>Manage</em> administration menu, navigate to <em>Structure</em> &gt; @structure_menu_link.','','11.3.3'),('8610','In the <em>Manage</em> administration menu, navigate <em>Structure</em> &gt; @structure_menu_link.','','11.3.3'),('8611','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Development</em> &gt; <em>@migrate_drupal_upgrade_link</em>.','','none'),('8612','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Media</em> &gt; <em>@styles_link</em>.','','none'),('8613','In the <em>Manage</em> administrative menu, navigate to <em>Configuration</em> &gt; <em>Search and Metadata</em> &gt; <em>@search_settings_link</em>.','','11.3.3'),('8614','- User defined -','','none'),('8615','Choose one of the keys from the $databases array or else select "User defined" and enter database credentials.','','none'),('8616','The email address is not made public. It will only be used if you need to be contacted about your account or for opted-in notifications.','','11.3.3'),('8617','Add HTML class','','11.3.3'),('8618','Migration @id did not meet the requirements. @message','','none'),('8619','Check the <a href="https://www.php.net/manual/en/image.installation.php">PHP GD installation documentation</a> if you want to add support.','','none'),('8620','The GD Library for PHP is enabled, but was compiled without support for functions used by the rotate and desaturate effects. It was probably compiled using the official GD libraries from the <a href="https://libgd.github.io/">gdLibrary site</a> instead of the GD library bundled with PHP. You should recompile PHP --with-gd using the bundled GD library. See <a href="https://www.php.net/manual/book.image.php">the PHP manual</a>.','','none'),('8621','Supported image file format: %formats.Supported image file formats: %formats.','','11.3.3');
INSERT INTO `locales_source` VALUES ('8622','Unsupported image file format: %formats.Unsupported image file formats: %formats.','','none'),('8623','No blocks settings to update.','','none'),('8624','<a href=":url">@module</a>','','none'),('8625','<a href=":url">@theme</a>','','none'),('8626','For more information read the <a href=":url">documentation on deprecated modules.</a>','','none'),('8627','For more information read the <a href=":url">documentation on deprecated themes.</a>','','none'),('8628','Removed core moduleRemoved core modules','','none'),('8629','This module is installed on your site but is no longer provided by Core.These modules are installed on your site but are no longer provided by Core.','','none'),('8630','You must add the following contributed theme and reload this page.You must add the following contributed themes and reload this page.','','none'),('8631','Removed core themeRemoved core themes','','none'),('8632','This theme is installed on your site but is no longer provided by Core.These themes are installed on your site but are no longer provided by Core.','','none'),('8633','You do not have permission to view @item_label.','','none'),('8634','Removing media.','','none'),('8635','These settings apply to the %field field everywhere it is used. Some also impact the way that data is stored and cannot be changed once data has been created.','','11.3.3'),('8636','There is @count entity with @delta or more values in this field, so the allowed number of values cannot be set to @allowed.There are @count entities with @delta or more values in this field, so the allowed number of values cannot be set to @allowed.','','none'),('8637','To install it:','','none'),('8638','To remove it:','','none'),('8639','This operation has already been applied.','','none'),('8640','This operation was canceled by another user.','','none'),('8641','The CKEditor 5 migration enabled the following plugins to support tags that are allowed by the %text_format text format: %enabling_message_content. The text format must be saved to make these changes active.','','none');
INSERT INTO `locales_source` VALUES ('8642','The following tags were permitted by the %text_format text format''s filter configuration, but no plugin was available that supports them. To ensure the tags remain supported by this text format, the following were added to the Source Editing plugin''s <em>Manually editable HTML tags</em>: @unsupported_string. The text format must be saved to make these changes active.','','none'),('8643','The CKEditor 5 migration process enabled the following plugins to support specific attributes that are allowed by the %text_format text format: %enabled_for_attributes_message_content.','','none'),('8644','As part of migrating to CKEditor 5, it was found that the %text_format text format''s HTML filters includes plugins that support the following tags, but not some of their attributes. To ensure these attributes remain supported, the following were added to the Source Editing plugin''s <em>Manually editable HTML tags</em>: @missing_attributes. The text format must be saved to make these changes active.','','none'),('8645','C#','','11.3.3'),('8646','C++','','11.3.3'),('8647','TypeScript','','11.3.3'),('8648','Tooltip date format','','none'),('8649','Tooltip custom date format','','none'),('8650','Time difference','','none'),('8651','Show as time difference','','none'),('8652','Time units','','none'),('8653','Display as a time difference (e.g. ''6 months ago'')','','none'),('8654','Refresh every @interval','','none'),('8655','Reference type: @entity_type','','11.3.3'),('8656','The ''@plugin_id'' plugin does not exist.','','none'),('8657','The ''@plugin_id'' plugin must implement or extend @interface.','','none'),('8658','Community announcements','','none'),('8659','No announcements available','','none'),('8660','Allows the creation of content blocks and block types.','','11.3.3'),('8661','Add content block','','11.3.3'),('8662','Access the Content blocks overview page','','11.3.3'),('8663','content blocks','','11.3.3'),('8664','block type