INSERT INTO `locales_source` VALUES ('8668','Text editors','','none'),('8669','Used in: @list','','11.3.3'),('8670','Click the <em>Uninstall</em> link to uninstall the theme. If there is not an <em>Uninstall</em> link, the theme cannot be uninstalled because it is either being used as the site default theme, being used as the <em>Administration theme</em>, or is the base theme for another installed theme.','','11.3.3'),('8671','Taxonomy reference fields can be added to any entity, such as user accounts, content blocks, or regular content items. If you use them to classify regular content items, your site will automatically be set up with taxonomy listing pages for each term; each of these pages lists all of the content items that are classified with that term.','','11.3.3'),('8672','Updated default configuration to %langcode','','11.3.3'),('8673','PHP APCu available caching','','11.3.3'),('8674','Allowed text formats','','11.3.3'),('8675','The selected text format is not allowed.','','none'),('8676','This role will be automatically granted all permissions.','','none'),('8677','Field %field_name exists but is missing a corresponding field definition and may be misconfigured.','','none'),('8678','Enter 0 to show all comments.','','none'),('8679','Using rsync','','none'),('8680','composer.lock not found in @dir.','','none'),('8681','Related recipes','','none'),('8682','Related recipes listing','','none'),('8683','The minimum value must be less than or equal to %max.','','none'),('8684','The email address %mail is not valid. Use the format user@example.com.','','none'),('8685','You cannot use an external URL. Enter a relative path.','','none'),('8686','Comments and the comment form are hidden from view.','','11.3.3'),('8687','An error occurred while saving the field: @error','','none'),('8688','Choose a type of field','','11.3.3'),('8689','Request response code is not: @codesRequest response code is not one of the following: @codes','','none'),('8690','Request response code is: @codesRequest response code is one of the following: @codes','','none'),('8691','More actions','','11.3.3');
