INSERT INTO `locales_source` VALUES ('9112','Pacific/Saipan','','11.3.3'),('9113','Pacific/Tahiti','','11.3.3'),('9114','Pacific/Tarawa','','11.3.3'),('9115','Pacific/Tongatapu','','11.3.3'),('9116','Pacific/Wake','','11.3.3'),('9117','Pacific/Wallis','','11.3.3'),('9118','UTC','','11.3.3'),('9119','When checking for updates, your site automatically sends anonymous information to Drupal.org. See the <a href="@update-status-module-docs" target="_blank">Update Status module documentation</a> for details.','','11.3.3'),('9120','Save comment','','11.3.3'),('9121','Teaser','','11.3.3'),('9122','Make content sticky','','11.3.3'),('9123','l, j F Y - H:i','PHP date format','11.3.3'),('9124','D, j M Y - H:i','PHP date format','11.3.3'),('9125','j M Y - H:i','PHP date format','11.3.3'),('9126','j F Y','PHP date format','11.3.3'),('9127','Content blocks','','11.3.3'),('9128','Find and manage content blocks.','','11.3.3'),('9129','There are no content blocks available.','','11.3.3'),('9130','Create and edit content blocks.','','11.3.3'),('9131','Find and manage comments.','','11.3.3'),('9132','next ›','','11.3.3'),('9133','‹ previous','','11.3.3'),('9134','« first','','11.3.3'),('9135','last »','','11.3.3'),('9136','The approved comments listing.','','11.3.3'),('9137','Comments published','','11.3.3'),('9138','Author Name','','11.3.3'),('9139','The unapproved comments listing.','','11.3.3'),('9140','Comments unapproved','','11.3.3'),('9141','Recent comments','','11.3.3');
