INSERT INTO `locales_source` VALUES ('9952','The unaliased URL.','','11.3.3'),('9953','The specific value of the array.','','11.3.3'),('9954','The list of available tokens that can be used in e-mails is provided below.','','none'),('9955','An array of all the term''s parents, starting with the root.','','11.3.3'),('9956','An array of all the menu link''s parents, starting with the root.','','11.3.3'),('9957','Original @entity','','11.3.3'),('9958','The original @entity data if the @entity is being updated or saved.','','11.3.3'),('9959','The base name of the file.','','11.3.3'),('9960','List of @type values','','11.3.3'),('9961','Tokens for lists of @type values.','','none'),('9962','Browse available tokens.','','11.3.3'),('9963','@type field. Also known as %labels.','','11.3.3'),('9964','Tokens or token types not defined as arrays','','none'),('9965','Tokens or token types missing name property','','none'),('9966','Token types do not have any tokens defined','','none'),('9967','Token types are not defined but have tokens','','none'),('9968','Token or token types are defined by multiple modules','','none'),('9969','Image with image style','','11.3.3'),('9970','The MIME type (image/png, image/bmp, etc.) of the image.','','11.3.3'),('9971','The file size of the image.','','11.3.3'),('9972','The height the image, in pixels.','','11.3.3'),('9973','The width of the image, in pixels.','','11.3.3'),('9974','The URI to the image.','','11.3.3'),('9975','The URL to the image.','','11.3.3'),('9976','@label tokens.','','none'),('9977','@type type with delta @delta','','11.3.3'),('9978','Represents the image in the given image style.','','11.3.3'),('9979','The <a href=":project">Token</a> module provides a user interface for the site token system. It also adds some additional tokens that are used extensively during site development. Tokens are specially formatted chunks of text that serve as placeholders for a dynamically generated value. For more information, covering both the token system and the additional tools provided by the Token module, see the <a href=":online">online documentation</a>.','','none');
INSERT INTO `locales_source` VALUES ('9980','Your website uses a shared token system for exposing and using placeholder tokens and their appropriate replacement values. This allows for any module to provide placeholder tokens for strings without having to reinvent the wheel. It also ensures consistency in the syntax used for tokens, making the system as a whole easier for end users to use.','','none'),('9981','The list of the currently available tokens on this site are shown below.','','none'),('9982','%name is using the following invalid tokens: @invalid-tokens.','','none'),('9983','Computed menu link for the node (only available during node saving).','','none'),('9984','%name must contain at least one token.%name must contain at least @count tokens.','','none'),('9985','%name must contain at most one token.%name must contain at most @count tokens.','','none'),('9986','Tokens related to books.','','none'),('9987','Title of the book.','','none'),('9988','The author of the book.','','none'),('9989','Top level of the book.','','none'),('9990','Parent of the current page.','','none'),('9991','An array of all the node''s parents, starting with the root.','','none'),('9992','This field supports tokens. @browse_tokens_link','','11.3.3'),('9993','Tokens related to random data.','','11.3.3'),('9994','The IP address of the current user.','','11.3.3'),('9995','Conditions','','11.3.3'),('9996','Verbose','','none'),('9997','Display alias changes (except during bulk updates).','','none'),('9998','Replace by separator','','none'),('9999','Maximum alias length','','none'),('10000','Maximum component length','','none'),('10001','Update action','','none'),('10002','Strings to Remove','','none'),('10003','Pathauto','','none'),('10004','Forum','','none'),('10005','Period','','none'),('10006','Asterisk','','none'),('10007','The automatically generated alias %original_alias conflicted with an existing alias. Alias changed to %alias.','','none'),('10008','Delete aliases','','11.3.3'),(