INSERT INTO `locales_source` VALUES ('10214','Provides support to define and manage custom meta tags.','','11.3.3'),('10215','Provides the fifteen <a href="https://dublincore.org/documents/dces/">Dublin Core Metadata Element Set 1.1</a> meta tags from the <a href="https://dublincore.org/">Dublin Core Metadata Institute</a>.','','11.3.3'),('10216','Provides forty additional meta tags from the <a href="https://dublincore.org/">Dublin Core Metadata Institute</a>.','','11.3.3'),('10217','A set of meta tags specially for controlling advanced functionality with Facebook.','','11.3.3'),('10218','Provides support for many different favicons.','','11.3.3'),('10219','Provides support for meta tags used for Google Custom Search Engine.','','11.3.3'),('10220','Provides support for the hreflang meta tag with some extra logic to simplify it.','','11.3.3'),('10221','Provides support for meta tags used to control the mobile browser experience.','','11.3.3'),('10222','Provides support for Open Graph Protocol meta tags.','','11.3.3'),('10223','Provides additional Open Graph Protocol meta tags for describing products.','','11.3.3'),('10224','Provides metatag support for Page Manager variants.','','11.3.3'),('10225','Provides support for Pinterest''s custom meta tags.','','11.3.3'),('10226','Provides support for Twitter''s Card meta tags.','','11.3.3'),('10227','Verifies ownership of a site for search engines and other services.','','11.3.3'),('10228','Provides views integration for metatags.','','11.3.3'),('10229','SEO','','11.3.3'),('10230','SMTP Authentication Support','','11.3.3'),('10231','SMTP Authentication','','none'),('10232','E-mail from name','','none'),('10233','E-mail from address','','none'),('10234','Enable debugging','','none'),('10235','Timeout','','none'),('10236','Use SSL','','none'),('10237','Install options','','none'),('10238','SMTP server settings','','none'),('10239','The address of your outgoing SMTP server.','','none'),('10240','The address of your outgoing SM