INSERT INTO `locales_source` VALUES ('10927','Extent','','none'),('10928','Release date','','none'),('10929','Application name','','none'),('10930','References','','none'),('10931','Canonical URL','','11.3.3'),('10932','Book author','','none'),('10933','Robots','','11.3.3'),('10934','Site verification','','none'),('10935','Bing','','none'),('10936','Date Available','','none'),('10937','Facebook App ID','','none'),('10938','Document status','','none'),('10939','Default shortcut icon','','none'),('10940','Access Rights','','none'),('10941','Android','','none'),('10942','Release Date','','none'),('10943','Rights','','11.3.3'),('10944','Contributor','','none'),('10945','Image alternative text','','11.3.3'),('10946','Open Graph','','none'),('10947','Facebook Application ID','','11.3.3'),('10948','Theme Color','','none'),('10949','404 page not found','','11.3.3'),('10950','Shortlink URL','','11.3.3'),('10951','Add default meta tags','','11.3.3'),('10952','Provides search engines with specific directions for what to do when this page is indexed.','','11.3.3'),('10953','Describes the name and version number of the software or publishing tool used to create the page.','','11.3.3'),('10954','Using defaults','','none'),('10955','Select the type of default meta tags you would like to add.','','11.3.3'),('10956','Viewport','','none');
INSERT INTO `locales_source` VALUES ('10957','Pinterest','','none'),('10958','Set Cookie','','none'),('10959','Dublin Core: Contributor','','none'),('10960','Dublin Core: Creator','','none'),('10961','Dublin Core: Date','','none'),('10962','Dublin Core: Description','','none'),('10963','Dublin Core: Publisher','','none'),('10964','Dublin Core: Title','','none'),('10965','Video type','','none'),('10966','Requires','','none'),('10967','Original source','','11.3.3'),('10968','Mobile Optimized','','none'),('10969','An image associated with this page, for use as a thumbnail in social networks and other services.','','11.3.3'),('10970','Basic tags','','11.3.3'),('10971','The name given to the resource.','','none'),('10972','An entity primarily responsible for making the resource. Examples of a Creator include a person, an organization, or a service. Typically, the name of a Creator should be used to indicate the entity.','','none'),('10973','The topic of the resource. Typically, the subject will be represented using keywords, key phrases, or classification codes. Recommended best practice is to use a controlled vocabulary. To describe the spatial or temporal topic of the resource, use the Coverage element.','','none'),('10974','An account of the resource. Description may include but is not limited to: an abstract, a table of contents, a graphical representation, or a free-text account of the resource.','','none'),('10975','An entity responsible for making the resource available. Examples of a Publisher include a person, an organization, or a service. Typically, the name of a Publisher should be used to indicate the entity.','','none'),('10976','An entity responsible for making contributions to the resource. Examples of a Contributor include a person, an organization, or a service. Typically, the name of a Contributor should be used to indicate the entity.','','none'),('10977','A point or period of time associated with an event in the lifecycle of the resource. Date may be used to express temporal information at any level of granularity.  Recommended best practice is to use an encoding scheme, such as the W3CDTF profile of ISO 8601 [W3CDTF].','','none');
INSERT INTO `locales_source` VALUES ('10978','The nature or genre of the resource. Recommended best practice is to use a controlled vocabulary such as the DCMI Type Vocabulary [DCMITYPE]. To describe the file format, physical medium, or dimensions of the resource, use the Format element.','','none'),('10979','The file format, physical medium, or dimensions of the resource. Examples of dimensions include size and duration. Recommended best practice is to use a controlled vocabulary such as the list of Internet Media Types [MIME].','','none'),('10980','An unambiguous reference to the resource within a given context. Recommended best practice is to identify the resource by means of a string conforming to a formal identification system.','','none'),('10981','A related resource from which the described resource is derived. The described resource may be derived from the related resource in whole or in part. Recommended best practice is to identify the related resource by means of a string conforming to a formal identification system.','','none'),('10982','A language of the resource. Recommended best practice is to use a controlled vocabulary such as RFC 4646 [RFC4646].','','none'),('10983','A related resource. Recommended best practice is to identify the related resource by means of a string conforming to a formal identification system.','','none'),('10984','The spatial or temporal topic of the resource, the spatial applicability of the resource, or the jurisdiction under which the resource is relevant. Spatial topic and spatial applicability may be a named place or a location specified by its geographic coordinates. Temporal topic may be a named period, date, or date range. A jurisdiction may be a named administrative entity or a geographic place to which the resource applies. Recommended best practice is to use a controlled vocabulary such as the Thesaurus of Geographic Names [TGN]. Where appropriate, named places or time periods can be used in preference to numeric identifiers such as sets of coordinates or date ranges.','','none');
INSERT INTO `locales_source` VALUES ('10985','Information about rights held in and over the resource. Typically, rights information includes a statement about various property rights associated with the resource, including intellectual property rights.','','none'),('10986','Facebook Admins','','11.3.3'),('10987','Twitter card type','','11.3.3'),('10988','Site''s Twitter account','','11.3.3'),('10989','The @username for the website, which will be displayed in the Card''s footer; must include the @ symbol.','','11.3.3'),('10990','Creator''s Twitter account','','11.3.3'),('10991','The @username for the content creator / author for this page, including the @ symbol.','','11.3.3'),('10992','A description that concisely summarizes the content of the page, as appropriate for presentation within a Tweet. Do not re-use the title text as the description, or use this field to describe the general services provided by the website. The string will be truncated, by Twitter, at the word to 200 characters.','','11.3.3'),('10993','Media player URL','','11.3.3'),('10994','Media player width','','11.3.3'),('10995','Media player height','','11.3.3'),('10996','MP4 media stream URL','','11.3.3'),('10997','Table Of Contents','','none'),('10998','Site''s Twitter account ID','','11.3.3'),('10999','The numerical Twitter account ID for the website, which will be displayed in the Card''s footer.','','11.3.3'),('11000','Metatag: Dublin Core','','none'),('11001','Metatag: Open Graph','','none'),('11002','Metatag: Twitter Cards','','none'),('11003','No Referrer','','11.3.3'),('11004','Used to indicate the URL that broke the story, and can link to either an internal URL or an external source. If the full URL is not known it is acceptable to use a partial URL or just the domain name.','','11.3.3'),('11005','403 access denied','','11.3.3'),('11006','iPhone app ID','','11.3.3'),('11007','String value, should be the numeric representation of your iPhone app''s ID in the App Store.','','11.3.3'),('11008','iPad app ID','','11.3.3'),('11009','String value, should be the numeric representation of your iPad app''s ID in the App Store.','','11.3.3');
INSERT INTO `locales_source` VALUES ('11010','Google Play app ID','','11.3.3'),('11011','iPhone app''s custom URL scheme','','11.3.3'),('11012','iPad app''s custom URL scheme','','11.3.3'),('11013','If your application is not available in the US App Store, you must set this value to the two-letter country code for the App Store that contains your application.','','11.3.3'),('11014','Should replacement tokens be used from the first row','','none'),('11015','A comma-separated list of Facebook user IDs of people who are considered administrators or moderators of this page.','','11.3.3'),('11016','A comma-separated list of Facebook Platform Application IDs applicable for this site.','','11.3.3'),('11017','Metatag: Facebook','','none'),('11018','Details about intellectual property, such as copyright or trademarks; does not automatically protect the site''s content or intellectual property.','','11.3.3'),('11019','A brief URL, often created by a URL shortening service.','','11.3.3'),('11020','A human-readable name for the site, e.g., <em>IMDb</em>.','','none'),('11021','The type of the content, e.g., <em>movie</em>.','','none'),('11022','The title of the content, e.g., <em>The Rock</em>.','','none'),('11023','The word that appears before the content''s title in a sentence. The default ignores this value, the ''Automatic'' value should be sufficient if this is actually needed.','','none'),('11024','A one to two sentence description of the content.','','none'),('11025','Content modification date & time','','none'),('11026','The height of the above image(s). Note: if both the unsecured and secured images are provided, they should both be the same size.','','none'),('11027','Postal/ZIP code','','none'),('11028','Alternative locales','','none'),('11029','Article author','','none'),('11030','Links an article to an author''s Facebook profile, should be either URLs to the author''s profile page or their Facebook profile IDs.','','none'),('11031','Article publisher','','none'),('11032','Links an article to a publisher''s Facebook page.','','none'),('11033','Article section','','none'),('11034','The primary section of this website the content belongs to.','','none');
INSERT INTO `locales_source` VALUES ('11035','Article tag(s)','','none'),('11036','Appropriate keywords for this content.','','none'),('11037','Article publication date & time','','none'),('11038','Article modification date & time','','none'),('11039','Article expiration date & time','','none'),('11040','Actor(s)','','none'),('11041','iPhone app name','','11.3.3'),('11042','The name of the iPhone app.','','11.3.3'),('11043','iPad app name','','11.3.3'),('11044','The name of the iPad app.','','11.3.3'),('11045','Google Play app name','','11.3.3'),('11046','The name of the app in the Google Play app store.','','11.3.3'),('11047','Google Play app''s custom URL scheme','','11.3.3'),('11048','Referrer policy','','11.3.3'),('11049','Unsafe URL','','11.3.3'),('11050','A alternative version of og:image and has exactly the same requirements; only one needs to be used.','','none'),('11051','Metatag: Verification','','none'),('11052','A location''s formal name.','','11.3.3'),('11053','ICBM','','11.3.3'),('11054','App Links','','none'),('11055','A custom scheme for the Android app.','','none'),('11056','The name of the app (suitable for display)','','none'),('11057','The web URL; defaults to the URL for the content that contains this tag.','','none'),('11058','Dublin Core Additional Tags','','none'),('11059','These tags are not part of the Metadata Element Set but may be useful for certain scenarios.','','none'),('11060','Date of copyright.','','none'),('11061','A PNG image that is 16px wide by 16px high.','','none'),('11062','A PNG image that is 32px wide by 32px high.','','none'),('11063','A PNG image that is 96px wide by 96px high.','','none'),('11064','A PNG image that is 192px wide by 192px high.','','none');
INSERT INTO `locales_source` VALUES ('11065','Meta tags used to control the mobile browser experience. Some of these meta tags have been replaced by newer mobile browsers. These meta tags usually only need to be set globally, rather than per-page.','','none'),('11066','Processed @processed of @total overridden Metatag records.','','none'),('11067','There were no overridden Metatag records.','','none'),('11068','Metatag settings','','none'),('11069','Undefined group ''%group'' on tag ''%tag''','','none'),('11070','Empty formatter','','none'),('11071','This field stores code meta tags.','','11.3.3'),('11072','Advanced meta tags form','','none'),('11073','Meta tags that might not be needed by many sites.','','11.3.3'),('11074','Simple meta tags.','','11.3.3'),('11075','Twitter Cards','','11.3.3'),('11076','A set of meta tags specially for controlling the summaries displayed when content is shared on <a href=''https://twitter.com/''>Twitter</a>.','','11.3.3'),('11077','Image Secure URL','','none'),('11078','Metatag defaults','','11.3.3'),('11079','Deleted @label defaults.','','none'),('11080','Created the %label Metatag defaults.','','11.3.3'),('11081','Saved the %label Metatag defaults.','','11.3.3'),('11082','Are you sure you want to revert %name to its default values?','','none'),('11083','Reverted @label defaults.','','none'),('11084','Alternative language links (hreflang)','','none'),('11085','Default locale (x-default)','','none'),('11086','This should point to the version of the page that is for the main or primary locale, e.g. the original version of an article that is translated into other languages.','','none'),('11087','MSApplication - Config','','none'),('11088','MSApplication - Task','','none'),('11089','The new Metatag: Open Graph module has been enabled.','','none'),('11090','Image SRC','','none'),('11091','Open Graph: Description','','none'),('11092','Open Graph: Image','','none'),('11093','Open Graph: Image secure URL','','none'),('11094','Open Graph: Image URL','','none');
INSERT INTO `locales_source` VALUES ('11095','Open Graph: Site name','','none'),('11096','Open Graph: Title','','none'),('11097','Open Graph: Type','','none'),('11098','Open Graph: URL','','none'),('11099','Shortlink','','none'),('11100','Determiner','','none'),('11101','The type of image referenced above. Should be either ''image/gif'' for a GIF image, ''image/jpeg'' for a JPG/JPEG image, or ''image/png'' for a PNG image. Note: there should be one value for each image, and having more than there are images may cause problems.','','none'),('11102','The locale these tags are marked up in, must be in the format language_TERRITORY. Default is ''en_US''.','','none'),('11103','Other locales this content is available in, must be in the format language_TERRITORY, e.g. ''fr_FR''.','','none'),('11104','URLs to related content','','none'),('11105','Inherits meta tags from: @inherits','','11.3.3'),('11106','[site:url]','','11.3.3'),('11107','[current-page:title] | [site:name]','','11.3.3'),('11108','[node:title] | [site:name]','','11.3.3'),('11109','[node:summary]','','11.3.3'),('11110','[term:name] | [site:name]','','11.3.3'),('11111','[term:description]','','11.3.3'),('11112','[site:name]','','11.3.3'),('11113','App store country','','11.3.3'),('11114','MP4 media stream MIME-type','','11.3.3'),('11115','The page''s title, which should be concise; it will be truncated at 70 characters by Twitter. This field is required unless this the ''type'' field is set to ''photo''.','','11.3.3'),('11116','Summary Card','','11.3.3'),('11117','Summary Card with large image','','11.3.3'),('11118','App Card','','11.3.3'),('11119','Player Card','','11.3.3'),('11120','Open Graph: Country name','','none'),('11121','Open Graph: Determiner','','none'),('11122','Open Graph: Email','','none'),('11123','Open Graph: Fax number','','none'),('11124','Open Graph: Image type','','none');
INSERT INTO `locales_source` VALUES ('11125','Open Graph: Image width','','none'),('11126','Open Graph: Latitude','','none'),('11127','Open Graph: Locale','','none'),('11128','Open Graph: Alternative locale','','none'),('11129','Open Graph: Locality','','none'),('11130','Open Graph: Longitude','','none'),('11131','Open Graph: Phone number','','none'),('11132','Open Graph: Region','','none'),('11133','Open Graph: Street address','','none'),('11134','Open Graph: Updated time','','none'),('11135','Twitter Cards: Google Play app ID','','none'),('11136','Twitter Cards: iPad app ID','','none'),('11137','Twitter Cards: iPhone app ID','','none'),('11138','Twitter Cards: Google Play app name','','none'),('11139','Twitter Cards: iPad app name','','none'),('11140','Twitter Cards: iPhone app name','','none'),('11141','Twitter Cards: App store country','','none'),('11142','Twitter Cards: Google Play app URL schema','','none'),('11143','Twitter Cards: iPad app URL schema','','none'),('11144','Twitter Cards: iPhone app URL schema','','none'),('11145','Twitter Cards: Creator''s Twitter account','','none'),('11146','Twitter Cards: Creator''s Twitter account ID','','none'),('11147','Twitter Cards: Data 1','','none'),('11148','Twitter Cards: Data 2','','none'),('11149','Twitter Cards: Description','','none'),('11150','Twitter Cards: 1st gallery image','','none'),('11151','Twitter Cards: 2nd gallery image','','none'),('11152','Twitter Cards: 3rd gallery image','','none'),('11153','Twitter Cards: 4th gallery image','','none'),('11154','Twitter Cards: Image URL','','none');
INSERT INTO `locales_source` VALUES ('11155','Twitter Cards: Image height','','none'),('11156','Twitter Cards: Image width','','none'),('11157','Twitter Cards: Image alternative text','','none'),('11158','Twitter Cards: Label 1','','none'),('11159','Twitter Cards: Label 2','','none'),('11160','Twitter Cards: Page URL','','none'),('11161','Twitter Cards: Media player URL','','none'),('11162','Twitter Cards: Media player height','','none'),('11163','Twitter Cards: MP4 media stream URL','','none'),('11164','Twitter Cards: MP4 media straem MIME-type','','none'),('11165','Twitter Cards: Media player width','','none'),('11166','Twitter Cards: Site''s Twitter account','','none'),('11167','Twitter Cards: Site''s Twitter account ID','','none'),('11168','Twitter Cards: Title','','none'),('11169','Twitter Cards: Type','','none'),('11170','The alternative text of the image being linked to. Limited to 420 characters.','','11.3.3'),('11171','Metatag: Google Plus','','none'),('11172','Article expiration time','','none'),('11173','Article modified time','','none'),('11174','Article published time','','none'),('11175','Site validation: Alexa','','none'),('11176','Site validation: Baidu','','none'),('11177','Site validation: Bing','','none'),('11178','Site validation: Google','','none'),('11179','Site validation: Norton Safe Web','','none'),('11180','Site validation: Pinterest','','none'),('11181','Site validation: Yahoo','','none'),('11182','Site validation: Yandex','','none'),('11183','These meta tags are used to confirm site ownership for search engines and other services.','','none'),('11184','Baidu','','none');
INSERT INTO `locales_source` VALUES ('11185','Norton Safe Web','','none'),('11186','Facebook Instant Articles claim URL token.','','11.3.3'),('11187','- Select a view -','','none'),('11188','Geographical region','','11.3.3'),('11189','Geographical place name','','11.3.3'),('11190','Geographical position','','11.3.3'),('11191','Open Graph: Image height','','none'),('11192','Open Graph: Postal code','','none'),('11193','Open Graph: See also','','none'),('11194','A location''s two-letter international country code, with an optional two-letter region, e.g. ''US-NH'' for New Hampshire in the USA.','','11.3.3'),('11195','Dublin Core: Coverage','','none'),('11196','Dublin Core: Format','','none'),('11197','Dublin Core: Identifier','','none'),('11198','Dublin Core: Language','','none'),('11199','Dublin Core: Relation','','none'),('11200','Dublin Core: Rights','','none'),('11201','Dublin Core: Source','','none'),('11202','Dublin Core: Subject','','none'),('11203','Dublin Core: Type','','none'),('11204','Facebook Pages','','11.3.3'),('11205','Open Graph: Video URL','','none'),('11206','Open Graph: Video height','','none'),('11207','Open Graph: Video Secure URL','','none'),('11208','Open Graph: Video type','','none'),('11209','Open Graph: Video width','','none'),('11210','The height of the above video(s). Note: if both the unsecured and secured videos are provided, they should both be the same size.','','none'),('11211','Video Secure URL','','none'),('11212','Google Custom Search Engine (CSE)','','none'),('11213','Use a url of a valid image.','','none'),('11214','Department tag.','','none');
INSERT INTO `locales_source` VALUES ('11215','Apple Web App Title','','none'),('11216','This module allows a site to automatically provide structured metadata, aka "meta tags", about the site and individual pages.','','none'),('11217','The module uses <a href=":tokens">"tokens"</a> to automatically fill in values for different meta tags. Specific values may also be filled in.','','none'),('11218','The best way of using Metatag is as follows:','','none'),('11219','Customize the <a href=":defaults">global defaults</a>, fill in the specific values and tokens that every page should have.','','none'),('11220','<a href=":add">Add more default configurations</a> as necessary for different entity types and entity bundles, e.g. for different content types or different vocabularies.','','none'),('11221','To override the meta tags for individual entities, e.g. for individual nodes, add the "Metatag" field via the field settings for that entity or bundle type.','','none'),('11222','If the top-level configuration is not specific enough, additional default meta tag configurations can be added for a specific entity type or entity bundle, e.g. for a specific content type.','','11.3.3'),('11223','Meta tags can be further refined on a per-entity basis, e.g. for individual nodes, by adding the "Metatag" field to that entity type through its normal field settings pages.','','11.3.3'),('11224','Android app name','','none'),('11225','iOS app name','','none'),('11226','Windows app GUID','','none'),('11227','Windows app name','','none'),('11228','Windows app URL scheme','','none'),('11229','Windows Phone app URL scheme','','none'),('11230','Windows Phone app GUID','','none'),('11231','Windows Phone app name','','none'),('11232','Windows Universal app URL scheme','','none'),('11233','Windows Universal app GUID','','none'),('11234','Windows Universal app name','','none'),('11235','The app ID for the app store.','','none'),('11236','A custom scheme for the iOS app. <strong>This attribute is required by the app Links specification.</strong>','','none'),('11237','Windows app ID','','none'),('11238','Windows Phone app ID','','none');
INSERT INTO `locales_source` VALUES ('11239','Windows Universal app ID','','none'),('11240','Configure global meta tag default values below. Meta tags may be left as the default.','','11.3.3'),('11241','Use the following form to override the global default meta tags for a specific entity type or entity bundle. In practical terms, this allows the meta tags to be customized for a specific content type or taxonomy vocabulary, so that its content will have different meta tags <em>default values</em> than others.','','11.3.3'),('11242','As a reminder, if the "Metatag" field is added to the entity type through its normal field settings, the meta tags can be further refined on a per entity basis; this allows each node to have its meta tags  customized on an individual basis.','','11.3.3'),('11243','The URL of an video which should represent the content. For best results use a source that is at least 1200 x 630 pixels in size, but at least 600 x 316 pixels is a recommended minimum. Object types supported include video.episode, video.movie, video.other, and video.tv_show.','','none'),('11244','[current-page:url]','','11.3.3'),('11245','[node:url]','','11.3.3'),('11246','[term:url]','','11.3.3'),('11247','[user:url]','','11.3.3'),('11248','Schema.org Metatag is installed','','none'),('11249','The <a href="@module">Schema.org Metatag</a> module is installed.','','none'),('11250','URL for a version of this page in %langcode','','none'),('11251','Links a book to an author''s Facebook profile, should be either URLs to the author''s profile page or their Facebook profile IDs.','','none'),('11252','The Book''s ISBN','','none'),('11253','The date the book was released.','','none'),('11254','Book tag(s)','','none'),('11255','The URL of an image which should represent the content. The image must be at least 200 x 200 pixels in size; 600 x 316 pixels is a recommended minimum size, and for best results use an image least 1200 x 630 pixels in size. Supports PNG, JPEG and GIF formats. Should not be used if og:image:url is used. Note: if multiple images are added many services (e.g. Facebook) will default to the largest image, not specifically the first one.','','none');
INSERT INTO `locales_source` VALUES ('11256','The URL of media which should represent the content.','','none'),('11257','No hover','','none'),('11258','Do not show hovering Save or Search buttons, generated by the Pinterest browser extensions.','','none'),('11259','Do not pin anything from this page. When selected, this option will take precedence over all options below.','','none'),('11260','No search','','none'),('11261','Do not allow Pinterest visual search to happen from this page.','','none'),('11262','The URL which should represent the content.','','none'),('11263','Configure the Metatag module','','11.3.3'),('11264','A description of what is in the image, not a caption. If the page specifies an og:image it should specify og:image:alt.','','none'),('11265','[user:display-name] | [site:name]','','11.3.3'),('11266','noindex','','11.3.3'),('11267','Revisit After','','11.3.3'),('11268','Cache control','','11.3.3'),('11269','Next page URL','','11.3.3'),('11270','Previous page URL','','11.3.3'),('11271','Pragma','','11.3.3'),('11272','Set cookie','','11.3.3'),('11273','Creator''s Twitter account ID','','11.3.3'),('11274','Meta Tags:','','11.3.3'),('11275','length','','11.3.3'),('11276','Separator used with multiple values','','11.3.3'),('11277','Controls the separator used when a meta tag allows multiple values. Multiple characters can be used together, it does not have to be one single character long. Defaults to ":default".','','11.3.3'),('11278','Entity type / Group Mapping','','11.3.3'),('11279','Identify which metatag groups should be available on which entity type / bundle combination. Unselected groups will not appear on the configuration form for that entity type, reducing the size of the form and increasing performance. If no groups are selected for a type, all groups will appear.','','11.3.3'),('11280','Use Maxlength module to force these limits?','','11.3.3'),('11281','Install the Maxlength module to enable this option.','','11.3.3'),('11282','Trim the Meta Tag after the word on the given value','','11.3.3'),('11283','Trim the Meta Tag on the given value','','11.3.3'),('11284','Trim the Meta Tag before the word on the given value','','11.3.3');
INSERT INTO `locales_source` VALUES ('11285','Trimming options','','11.3.3'),('11286','Characters to trim','','11.3.3'),('11287','A list of characters to trim at the end of all metatags. Provide a single string without any separators, e.g. "|,." (instead of "| , ."). Note that spaces, tabs, new lines, carriage returns and vertical tabs (" \\n\\r\\t\\v") will be trimmed automatically and do not need to be listed in this field. The trimming is applied at the very end after the tag is trimmed for length, and after the trimming option was executed.','','11.3.3'),('11288','Optional suffix to add','','11.3.3'),('11289','If provided this string will be added at the end of all meta tags that are trimmed to length.','','11.3.3'),('11290','Metatag Trimming Options','','11.3.3'),('11291','Many Meta-Tags can be trimmed on a specific length for search engine optimization.<br/>If the value is set to ''0'' or left empty, the whole Metatag will be untrimmed.','','11.3.3'),('11292','eg 500px or 8rem','','11.3.3'),('11293','Scroll maximum height','','11.3.3'),('11294','To enable scrolling please enter a value and its units, e.g. 500px, 8rem, etc. Removing this value will remove the scroll.','','11.3.3'),('11295','Metatag widget options','','11.3.3'),('11296','Various options for the field widget used on entity forms, e.g. on content type forms.','','11.3.3'),('11297','Meta tag patterns are passed down from one level to the next unless they are overridden. To view a summary of the individual meta tags and the pattern for a specific configuration, click on its name below.','','11.3.3'),('11298','Use tokens to avoid redundant meta data and search engine penalization. For example, a ''keyword'' value of "example" will be shown on all content using this configuration, whereas using the [node:field_keywords] automatically inserts the "keywords" values from the current entity (node, term, etc).','','11.3.3'),('11299','Configure the meta tags below.','','11.3.3'),('11300','To use tokens to image fields, the image field on that entity bundle (content type, term, etc) must have the "Token" display settings enabled, the image field must not be hidden, and it must be set to output as an image, e.g. using the "Thumbnail" field formatter. It is also recommended to use an appropriate image style that resizes the image rather than output the original image; see individual meta tag descriptions for size recommendations.','','11.3.3');
INSERT INTO `locales_source` VALUES ('11301','Set to %none to disable inheritance of the parent value and prevent the output of this metatag entirely.','','11.3.3'),('11302','The text to display in the title bar of a visitor''s web browser when they view this page. This meta tag may also be used as the title of the page when a visitor bookmarks or favorites this page, or as the page title in a search engine result. It is common to append ''[site:name]'' to the end of this, so the site''s name is automatically added. It is recommended that the title is no greater than 55 - 65 characters long, including spaces.','','11.3.3'),('11303','A brief and concise summary of the page''s content that is a maximum of 160 characters in length. The description meta tag may be used by search engines to display a snippet about the page in search results.','','11.3.3'),('11304','A brief and concise summary of the page''s content, preferably 150 characters or less. Where as the description meta tag may be used by search engines to display a snippet about the page in search results, the abstract tag may be used to archive a summary about the page. This meta tag is <em>no longer</em> supported by major search engines.','','11.3.3'),('11305','A comma-separated list of keywords about the page. This meta tag is <em>no longer</em> supported by most search engines.','','11.3.3'),('11306','Geo-spatial information in ''latitude; longitude'' format, e.g. ''50.167958; -97.133185''; <a href=''https://en.wikipedia.org/wiki/Geographic_coordinate_system'' aria-label=''see Wikipedia for details on the geographic coordinate system''>see Wikipedia for details</a>.','','11.3.3'),('11307','Geo-spatial information in ''latitude, longitude'' format, e.g. ''50.167958, -97.133185''; <a href=''https://en.wikipedia.org/wiki/ICBM_address'' aria-label=''see Wikipedia for details on ICBM addresses''>see Wikipedia for details</a>.','','11.3.3'),('11308','A link to the preferred page location or URL of the content of this page, to help eliminate duplicate content penalties from search engines.','','11.3.3');
INSERT INTO `locales_source` VALUES ('11309','Used for paginated content by providing URL with rel=''next'' link.','','11.3.3'),('11310','Used for paginated content by providing URL with rel=''prev'' link.','','11.3.3'),('11311','Define the author of a page.','','11.3.3'),('11312','This will be able to extract the URL from an image field if the field is configured properly.','','11.3.3'),('11313','Used to rate content for audience appropriateness. This tag has little known influence on search engine rankings, but can be used by browsers, browser extensions, and apps. The <a href=''https://www.metatags.org/meta_name_rating''>most common options</a> are general, mature, restricted, 14 years, safe for kids. If you follow the <a href=''https://www.rtalabel.org/index.php?content=howto''>RTA Documentation</a> you should enter RTA-5042-1996-1400-1577-RTA','','11.3.3'),('11314','<a href=''https://www.metatags.org/meta_http_equiv_set_cookie''>Sets a cookie</a> on the visitor''s browser. Can be in either NAME=VALUE format, or a more verbose format including the path and expiration date; see the link for full details on the syntax.','','11.3.3'),('11315','The number of seconds to wait before refreshing the page. May also force redirect to another page using the format ''5; url=https://example.com/'', which would be triggered after five seconds.','','11.3.3'),('11316','This meta tag communicates with Google. There are currently two directives supported: ''nositelinkssearchbox'' to not to show the sitelinks search box, and ''notranslate'' to ask Google not to offer a translation of the page. Both options may be added, just separate them with a comma. See <a href=''https://support.google.com/webmasters/answer/79812?hl=en''>meta tags that Google understands</a> for further details.','','11.3.3'),('11317','Tell search engines when to index the page again. Very few search engines support this tag, it is more useful to use an <a href=''https://www.drupal.org/project/xmlsitemap''>XML Sitemap</a> file.','','11.3.3'),('11318','Used to control whether a browser caches a specific page locally. Not commonly used. Should be used in conjunction with the Pragma meta tag.','','11.3.3');
INSERT INTO `locales_source` VALUES ('11319','Control when the browser''s internal cache of the current page should expire. The date must to be an <a href=''https://www.csgnetwork.com/timerfc1123calc.html''>RFC-1123</a>-compliant date string that is represented in Greenwich Mean Time (GMT), e.g. ''Thu, 01 Sep 2016 00:12:56 GMT''. Set to ''0'' to stop the page being cached entirely.','','11.3.3'),('11320','Used to control whether a browser caches a specific page locally. Not commonly used. Should be used in conjunction with the Cache-Control meta tag.','','11.3.3'),('11321','The numerical Twitter account ID for the content creator / author for this page.','','11.3.3'),('11322','The URL to a unique image representing the content of the page. Do not use a generic image such as your website logo, author photo, or other image that spans multiple pages. Images larger than 120x120px will be resized and cropped square based on longest dimension. Images smaller than 60x60px will not be shown. If the ''type'' is set to Photo then the image must be at least 280x150px.','','11.3.3'),('11323','The iPhone app''s custom URL scheme (must include "://" after the scheme name).','','11.3.3'),('11324','The iPad app''s custom URL scheme (must include "://" after the scheme name).','','11.3.3'),('11325','Your app ID in the Google Play Store (i.e. "com.android.app").','','11.3.3'),('11326','The Google Play app''s custom URL scheme (must include "://" after the scheme name).','','11.3.3'),('11327','The full URL for loading a media player, specifically an iframe for an embedded video rather than the URL to a page that contains a player. Required when using the Player Card type.','','11.3.3'),('11328','The width of the media player iframe, in pixels. Required when using the Player Card type.','','11.3.3'),('11329','The height of the media player iframe, in pixels. Required when using the Player Card type.','','11.3.3'),('11330','The full URL for an MP4 video (h.264) or audio (AAC) stream, takes precedence over the other media player field.','','11.3.3'),('11331','The MIME type for the media contained in the stream URL, as defined by <a href='':url''>RFC 4337</a>.','','11.3.3');
INSERT INTO `locales_source` VALUES ('11332','index - Allow search engines to index this page (assumed).','','11.3.3'),('11333','follow - Allow search engines to follow links on this page (assumed).','','11.3.3'),('11334','noindex - Prevents search engines from indexing this page.','','11.3.3'),('11335','nofollow - Prevents search engines from following links on this page.','','11.3.3'),('11336','noarchive - Prevents cached copies of this page from appearing in search results.','','11.3.3'),('11337','nosnippet - Prevents descriptions from appearing in search results, and prevents page caching.','','11.3.3'),('11338','noimageindex - Prevent search engines from indexing images on this page.','','11.3.3'),('11339','notranslate - Prevent search engines from offering to translate this page in search results.','','11.3.3'),('11340','Max Snippet','','11.3.3'),('11341','Use a number character as a textual snippet for this search result. "0" equals "nosnippet". "-1" will let the search engine decide the most effective length.','','11.3.3'),('11342','Max Video Preview','','11.3.3'),('11343','Use a maximum of number seconds as a video snippet for videos on this page in search results. "0" will use a static a image. "-1" means there is no limit.','','11.3.3'),('11344','None - no image preview is to be shown.','','11.3.3'),('11345','Standard - a default image preview may be shown.','','11.3.3'),('11346','Large - a larger image preview, up to the width of the viewport, may be shown.','','11.3.3'),('11347','Max Image Preview','','11.3.3'),('11348','Set the maximum size of an image preview for this page in a search results.','','11.3.3'),('11349','Unavailable after date','','11.3.3'),('11350','Do not show this page in search results after the specified date','','11.3.3'),('11351','No Referrer When Downgrade','','11.3.3'),('11352','Origin When Cross-Origin','','11.3.3'),('11353','Same Origin','','11.3.3'),('11354','Strict Origin','','11.3.3'),('11355','Strict Origin When Cross-Origin','','11.3.3'),('11356','Indicate to search engines and other page scrapers whether or not links should be followed. See <a href=''https://w3c.github.io/webappsec/specs/referrer-policy/''>the W3C specifications</a> for further details. Note: this serves the same purpose as the HTTP header by the same name.','','11.3.3');
INSERT INTO `locales_source` VALUES ('11357','A set of meta tags specially for controlling advanced functionality with <a href='':fb''>Facebook</a>.<br><br>The Facebook <a href=''https://developers.facebook.com/tools/debug/''>Sharing Debugger</a> lets you preview how your content will look when it''s shared to Facebook and debug any issues with your Open Graph tags.','','11.3.3'),('11358','Notes:<ul><li>no other fields are required for a Summary card</li><li>Media player card requires the ''title'', ''description'', ''media player URL'', ''media player width'', ''media player height'' and ''image'' fields,</li><li>Summary Card with Large Image card requires the ''Summary'' field and the ''image'' field,</li><li>App Card requires the ''iPhone app ID'' field, the ''iPad app ID'' field and the ''Google Play app ID'' field,</li></ul>','','11.3.3'),('11359','Warning: disabling the Global default metatag will prevent any metatags from being used.','','11.3.3'),('11360','Edit default meta tags for @path','','11.3.3'),('11361','The current date in ''short'' format. (%date)','','11.3.3'),('11362','The current date in ''long'' format. (%date)','','11.3.3'),('11363','The current date in ''medium'' format. (%date)','','11.3.3'),('11364','The current date in a custom format. See <a href="https://www.php.net/manual/datetime.format.php#refsect1-datetime.format-parameters">the PHP documentation</a> for details.','','11.3.3'),('11365','The current date in UNIX timestamp format (%date)','','11.3.3'),('11366','The current date in ''time-since'' format. (%date)','','11.3.3'),('11367','Tokens related to site language.','','11.3.3'),('11368','Whether the language is written left-to-right (ltr) or right-to-left (rtl).','','11.3.3'),('11369','The domain name to use for the language.','','11.3.3'),('11370','The language name.','','11.3.3'),('11371','Path prefix for URLs in the language.','','11.3.3'),('11372','The base path of the site, currently: @base_path','','11.3.3'),('11373','The URL of the site''s front page with the language prefix, if it exists.','','11.3.3'),('11374','The base URL of the site, currently: @base_url','','11.3.3');
INSERT INTO `locales_source` VALUES ('11375','The language of the @entity.','','11.3.3'),('11376','The UUID of the user account.','','11.3.3'),('11377','The publication status of the node ("Published" or "Unpublished").','','11.3.3'),('11378','The UUID of the content item, or "node".','','11.3.3'),('11379','The source term for this current term''s translation set.','','11.3.3'),('11380','The UUID of the taxonomy term.','','11.3.3'),('11381','The UUID of the uploaded file.','','11.3.3'),('11382','The active user interface language.','','11.3.3'),('11383','The active content language.','','11.3.3'),('11384','Metatag values for the current page.','','11.3.3'),('11385','Llave secreta','','11.3.3'),('11386','Ingrese su llave secreta para conectar a la api.','','11.3.3'),('11387','Administer meta tags','','11.3.3'),('11388','Control the Metatag settings pages. Does not control access to the Metatag field on content forms, etc, use the Field Permissions module or hook_form_alter().','','11.3.3'),('11389','The image is too small. The minimum dimensions are %dimensions pixels and the image size is %widthx%height pixels.','','11.3.3'),('11390','Required if you want to change the <em>Email address</em> or the <em>Password</em> field below. <a href=":request_new_url" title="Send password reset instructions via email.">Reset your password</a>.','','11.3.3'),('11391','Ideal for longer texts, like body or description','','11.3.3'),('11392','Supports long text without specifying a maximum length','','11.3.3'),('11393','May use more storage and be slower for searching and sorting','','11.3.3'),('11394','Ideal for titles and names','','11.3.3'),('11395','Efficient storage for short text','','11.3.3'),('11396','Requires specifying a maximum length','','11.3.3'),('11397','Good for fields with known or predictable length','','11.3.3'),('11398','image','','11.3.3'),('11399','Barra lateral de filtros','','11.3.3'),('11400','Label element HTML classes','','11.3.3'),('11401','Id: @id','','11.3.3'),('11402','Element: @element','','11.3.3'),('11403','Attributes: @attributes','','11.3.3'),('11404','Fallback format','','11.3.3');
INSERT INTO `locales_source` VALUES ('11405','Format to use if AVIF is not available.','','11.3.3'),('11406','Converts an image to AVIF, with a fallback if AVIF is not supported.','','11.3.3'),('11407','Provide markup for the area with minimal filtering.','','11.3.3'),('11408','Include tokens from the first row','','11.3.3'),('11409','Enable this to use tokens from fields in the first result row, if present. Global tokens (e.g., site name) and contextual argument tokens are always available.','','11.3.3'),('11410','You may enter data from this view as per the "Available global token replacements" above. You may include the following allowed HTML tags: <code>@tags</code>','','11.3.3'),('11411','cron','','none'),('11412','Schedule','','11.3.3'),('11413','Frequency','','none'),('11414','Note','','11.3.3'),('11415','Backups','','none'),('11416','Backup','','11.3.3'),('11417','Destination','','11.3.3'),('11418','Sources','','none'),('11419','Keep','','none'),('11420','Schedules','','11.3.3'),('11421','Next cron run','','none'),('11422','Restore','','11.3.3'),('11423','Last Run','','none'),('11424','Profile Name','','none'),('11425','Backup and Migrate','','11.3.3'),('11426','Saved Backups','','11.3.3'),('11427','Compression','','none'),('11428','Upload a Backup File','','none'),('11429','Add Schedule','','none'),('11430','Edit source','','none'),('11431','MySQL Database','','none'),('11432','Default Database','','none'),('11433','Backup Source','','11.3.3'),('11434','Destinations','','none');
INSERT INTO `locales_source` VALUES ('11435','destination','','none'),('11436','Take site offline','','none'),('11437','Take the site offline during backup and show a maintenance message. Site will be taken back online once the backup is complete.','','none'),('11438','schedules','','none'),('11439','Schedule Name','','none'),('11440','Settings Profile','','11.3.3'),('11441','restore feature','','none'),('11442','settings profiles','','none'),('11443','Restore Tab','','none'),('11444','manual backups','','none'),('11445','Quick Backup','','11.3.3'),('11446','Backup now','','11.3.3'),('11447','Backup Destination','','11.3.3'),('11448','Advanced Backup','','11.3.3'),('11449','Restore now','','none'),('11450','Perform a backup','','none'),('11451','Access backup files','','none'),('11452','Access and download the previously created backup files.','','none'),('11453','Restore the site','','none'),('11454','Restore the site''s database from a backup file.','','none'),('11455','Edit Backup and Migrate profiles, schedules and destinations.','','none'),('11456','Run every','','none'),('11457','Administer Backup and Migrate','','none'),('11458','Add a note to the backup','','11.3.3'),('11459','Upload a backup file created by Backup and Migrate. For other database or file backups please use another tool for import. Max file size: %size','','none'),('11460','Backup the Drupal database and files or migrate them to another environment.','','11.3.3'),('11461','Settings Profiles','','none'),('11462','File Directory','','none'),('11463','content @type: deleted @label.','','none'),('11464','Schedule enabled','','none');
INSERT INTO `locales_source` VALUES ('11465','Private Files Directory','','11.3.3'),('11466','Daily Schedule','','11.3.3'),('11467','Default Drupal Database','','11.3.3'),('11468','Entire Site (do not use)','','11.3.3'),('11469','Public Files Directory','','11.3.3'),('11470','Create or import backups of your project database or files','','11.3.3'),('11471','','','11.3.3'),('11472','It is recommended to not use the "Entire site" backup as it has a tendency of failing on anything but the tiniest of sites. Hopefully this will be fixed in a future release.','','11.3.3'),('11473','In order to encrypt backup files, please install the Defuse PHP-encryption library via Composer with the following command: <code>composer require defuse/php-encryption</code>. See the <a href="@docs">Defuse PHP Encryption Documentation Page</a> for more information.','','11.3.3'),('11474','Add one item per line.','','11.3.3'),('11475','The resized image is too small. The minimum dimensions are %dimensions pixels and after resizing, the image size will be %widthx%height pixels.','','11.3.3'),('11476','Enter some keywords.','','11.3.3'),('11477','This block is broken or missing. You may be missing content or you might need to install the original module.','','11.3.3'),('11478','If checked, multiple values for this field will be shown in the same row. If not checked, each value in this field will create a new row. If using group by, make sure to group by "Entity ID" for this setting to have any effect.','','11.3.3'),('11479','mymobile','','11.3.3'),('11480','<pre>Array\n(\n    [id] =&gt; 35\n    [order_number] =&gt; MM-2026-00035\n    [nombre] =&gt; pedro el escamoso\n    [celular] =&gt; 573113121889\n    [total] =&gt; 67890\n    [payload] =&gt; {"nombre":"pedro el escamoso","celular":"573113121889","items":[@"id":"88","sku":"45678","name":"Producto 2","price":67890,"quantity":1]}\n    [ip_address] =&gt; 127.0.0.1\n    [created] =&gt; 1775770013\n    [status] =&gt; pending\n)\n</pre>','','11.3.3'),('11481','page not found','','11.3.3'),('11482','<pre>Array\n(\n    [nombre] =&gt; pedro el escamoso\n    [celular] =&gt; 573113121889\n    [items] =&gt; Array\n        (\n            [0] =&gt; Array\n                (\n                    [id] =&gt; 88\n                    [sku] =&gt; 45678\n                    [name] =&gt; Producto 2\n                    [price] =&gt; 67890\n                    [quantity] =&gt; 1\n                    [image] =&gt; http://education.test/sites/default/files/2026-04/product-2-1.jpg\n                )\n\n        )\n\n)\n</pre>','','11.3.3');
INSERT INTO `locales_source` VALUES ('11483','Current node ''changed'' time','','11.3.3'),('11484','Current node ''created'' time','','11.3.3'),('11485','Specify validation criteria','','11.3.3'),('11486','Default: @plugin_title','','11.3.3'),('11487','debug','','11.3.3'),('11488','PLUGIN: views_block:productos_en_tendencia-block_6','','11.3.3'),('11489','Logs how many times content is viewed.','','11.3.3'),('11490','Statistics','','11.3.3'),('11491','Configure the logging of content statistics.','','11.3.3'),('11492','How many content items to display in "day" list.','','none'),('11493','Number of day''s top views to display','','none'),('11494','Number of all time views to display','','none'),('11495','Number of most recent views to display','','none'),('11496','Number of views','','11.3.3'),('11497','1 view@count views','','11.3.3'),('11498','Total views','','11.3.3'),('11499','The total number of times the node has been viewed.','','11.3.3'),('11500','Views today','','11.3.3'),('11501','The total number of times the node has been viewed today.','','11.3.3'),('11502','Most recent view','','11.3.3'),('11503','The most recent time the node has been viewed.','','11.3.3'),('11504','Content viewing counter settings','','11.3.3'),('11505','Count content views','','11.3.3'),('11506','Increment a counter each time content is viewed.','','11.3.3'),('11507','Popular content','','11.3.3'),('11508','How many content items to display in "all time" list.','','none'),('11509','How many content items to display in "recently viewed" list.','','none'),('11510','Today''s:','','none'),('11511','All time:','','none'),('11512','Last viewed:','','none');
INSERT INTO `locales_source` VALUES ('11513','Content statistics','','11.3.3'),('11514','The number of visitors who have read the node.','','none'),('11515','The number of visitors who have read the node today.','','none'),('11516','Last view','','11.3.3'),('11517','The date on which a visitor last read the node.','','none'),('11518','Displaying popular content','','none'),('11519','Page view counter','','none'),('11520','Administer statistics','','none'),('11521','View content hits','','none'),('11522','The node ID.','','none'),('11523','Settings for the statistical information that Drupal will keep about the site.','','11.3.3'),('11524','Statistics settings','','none'),('11525','Popular content block settings','','none'),('11526','Number of day\\s top views to display','','none'),('11527','The Statistics module shows you how often content is viewed. This is useful in determining which pages of your site are most popular. For more information, see the <a href=":statistics_do">online documentation for the Statistics module</a>.','','none'),('11528','The module includes a <em>Popular content</em> block that displays the most viewed pages today and for all time, and the last content viewed. To use the block, enable <em>Count content views</em> on the <a href=":statistics-settings">Statistics page</a>, and then you can enable and configure the block on the <a href=":blocks">Block layout page</a>.','','none'),('11529','The Statistics module includes a counter for each page that increases whenever the page is viewed. To use the counter, enable <em>Count content views</em> on the <a href=":statistics-settings">Statistics page</a>, and set the necessary <a href=":permissions">permissions</a> (<em>View content hits</em>) so that the counter is visible to the users.','','none'),('11530','How long any statistics may be cached, i.e. the refresh interval','','none'),('11531','Numeric values from the statistics module','','none'),('11532','The most recent time the node has been viewed','','none'),('11533','The ID of the node to which these statistics apply.','','none'),('11534','Check <em>Count content views</em> and click <em>Save configuration</em>.','','11.3.3');
INSERT INTO `locales_source` VALUES ('11535','Tracking and displaying popular content','','11.3.3'),('11536','Enable content viewing statistics and view the popular content block.','','11.3.3'),('11537','What are content viewing statistics?','','11.3.3'),('11538','The Statistics module can count how many times each piece of content on your site is viewed.\n    It also provides a <em>Popular\n      content</em> block that you can enable to display the most-viewed content.','','11.3.3'),('11539','Enable counting','','11.3.3'),('11540','In the <em>Manage</em> administrative menu, navigate to\n          <em>Configuration</em> &gt;\n          <em>System</em> &gt;\n          <em>@statistics_settings_link</em>.','','11.3.3'),('11541','Allow display of counts to users','','11.3.3'),('11542','In the <em>Manage</em> administrative menu, navigate to\n          <em>People</em> &gt;\n          <em>@permissions_link</em>.','','11.3.3'),('11543','Check <em>View content hits</em>\n          under the Statistics menu for the desired roles,\n          and click <em>Save permissions</em>.','','11.3.3'),('11544','The Popular Content block will not be available if this is not checked.','','11.3.3'),('11545','Enable the block','','11.3.3'),('11546','In the <em>Manage</em> administrative menu, navigate to\n          <em>Structure</em> &gt;\n          <em>@block_layout_link</em>.','','11.3.3'),('11547','Click <em>Place block</em>\n          in the region where you want the block to appear (for example, <em>Sidebar second</em>).','','11.3.3'),('11548','In the pop-up window, click <em>Place block</em> in the row of <em>Popular\n          content</em>.','','11.3.3'),('11549','In the <em>Configure block</em> pop-up, click <em>Save block</em>.','','11.3.3'),('11550','Verify that the block is now listed in the correct region. When you visit the site, you should see the block, with a list of the content pages that are most popular.','','11.3.3'),('11551','Changes made in this table will not be saved until the form is submitted.','','11.3.3'),('11552','The submitted value %choice in the %name element is not allowed.','','11.3.3');
