INSERT INTO `locales_target` VALUES ('3852','Sobrescribir las traducciones personalizadas existentes','es','0'),('3853','No hay ningún idioma disponible. La exportación sólo contendrá los textos de origen.','es','0'),('3854','Solo textos originales, sin traducciones','es','0'),('3855','Incluir las traducciones no personalizadas','es','0'),('3856','Incluir las traducciones personalizadas','es','0'),('3857','Incluir texto sin traducir','es','0'),('3858','@count textos HTML prohibidos en los archivos: @files.','es','0'),('3859','Tipo de traducción','es','0'),('3860','Traducción no personalizada','es','0'),('3861','Traducción personalizada','es','0'),('3862','Los textos se han guardado.','es','0'),('3863','En contexto','es','0'),('3864','Primera forma plural@count. formas plurales','es','0'),('3865','Traducción de la interfaz','es','0'),('3866','@translated/@total (@ratio%)','es','0'),('3867','no aplicable','es','0'),('3868','Habilitar la interfaz de traducción al Inglés','es','0'),('3869','Directorio de interfaz de traducciones','es','0'),('3870','Eliminado el archivo de traducción JavaScript para el idioma %language, porque actualmente no existen traducciones para ese idioma.','es','0'),('3871','Traducción de la interfaz de usuario','es','0'),('3872','Importación del texto "%string" se omitió debido a HTML no permitido o mal formado.','es','0'),('3873','sólo para usuarios registrados','es','0'),('3874','Idioma preferido del autor','es','0'),('3875','%type está siendo usado por 1 elemento de contenido en su sitio web. Usted no puede borrar este tipo de contenido hasta que haya eliminado todos los contenidos de tipo %type.%type está siendo usado por @count elementos de contenido en su sitio web. Usted no puede borrar este tipo de contenido hasta que haya eliminado todos los contenidos de tipo %type.','es','0'),('3876','El código de idioma del idioma del nodo se escribe dentro.','es','0'),('3877','Describa brevemente los cambios que ha realizado.','es','0'),('3878','Us