INSERT INTO `node_revision__body` VALUES ('article','0','101','338','es','0','<p>iPhone 17 256 GB. Diseño elegante y resistente, creado para ofrecer rendimiento, durabilidad y una experiencia excepcional en cada uso.</p><p><strong>Estado:</strong> Nuevo</p><p><strong>Chip A19. </strong>Potencia y eficiencia para disfrutar de tus aplicaciones, juegos, fotografías y multitarea con un rendimiento rápido y fluido.</p><p><strong>Pantalla Super Retina XDR.</strong> Colores vibrantes, gran nivel de detalle y un brillo impresionante para disfrutar de contenido con una calidad visual extraordinaria.</p><p><strong>Sistema avanzado de cámaras.</strong> Captura fotografías y videos increíbles con gran nitidez, colores realistas y excelente rendimiento en diferentes condiciones de iluminación.</p><p><strong>Ceramic Shield.</strong> Protección avanzada diseñada para brindar una mayor resistencia y durabilidad en el uso diario.</p><p><strong>Batería de larga duración. </strong>Disfruta de más tiempo para navegar, reproducir contenido, trabajar y mantenerte conectado durante todo el día.</p><p><strong>Botón de Acción.</strong> Personaliza accesos rápidos a tus funciones favoritas para acceder a ellas de forma inmediata y cómoda.</p><p><strong>Control de Cámara.</strong> Captura fotos y videos con mayor facilidad gracias al acceso rápido a las principales funciones de la cámara.</p><p><strong>Capacidad de 256 GB.</strong> Amplio espacio para almacenar fotos, videos, aplicaciones, juegos y documentos sin preocuparte por el almacenamiento.</p><p><strong>Conectividad 5G.</strong> Descarga, transmite y comparte contenido a velocidades ultrarrápidas.</p><p><strong>Experiencia Apple.</strong> Disfruta de la integración perfecta entre hardware y software, junto con las últimas funciones de iOS para productividad, entretenimiento y comunicación.</p>','','basic_html'),('article','0','101','341','es','0','<p>iPhone 17 256 GB. Diseño elegante y resistente, creado para ofrecer rendimiento, durabilidad y una experiencia excepcional en cada uso.</p><p><strong>Estado:</strong> Nuevo</p><p><strong>Chip A19. </strong>Potencia y eficiencia para disfrutar de tus aplicaciones, juegos, fotografías y multitarea con un rendimiento rápido y fluido.</p><p><strong>Pantalla Super Retina XDR.</strong> Colores vibrantes, gran nivel de detalle y un brillo impresionante para disfrutar de contenido con una calidad visual extraordinaria.</p><p><strong>Sistema avanzado de cámaras.</strong> Captura fotografías y videos increíbles con gran nitidez, colores realistas y excelente rendimiento en diferentes condiciones de iluminación.</p><p><strong>Ceramic Shield.</strong> Protección avanzada diseñada para brindar una mayor resistencia y durabilidad en el uso diario.</p><p><strong>Batería de larga duración. </strong>Disfruta de más tiempo para navegar, reproducir contenido, trabajar y mantenerte conectado durante todo el día.</p><p><strong>Botón de Acción.</strong> Personaliza accesos rápidos a tus funciones favoritas para acceder a ellas de forma inmediata y cómoda.</p><p><strong>Control de Cámara.</strong> Captura fotos y videos con mayor facilidad gracias al acceso rápido a las principales funciones de la cámara.</p><p><strong>Capacidad de 256 GB.</strong> Amplio espacio para almacenar fotos, videos, aplicaciones, juegos y documentos sin preocuparte por el almacenamiento.</p><p><strong>Conectividad 5G.</strong> Descarga, transmite y comparte contenido a velocidades ultrarrápidas.</p><p><strong>Experiencia Apple.</strong> Disfruta de la integración perfecta entre hardware y software, junto con las últimas funciones de iOS para productividad, entretenimiento y comunicación.</p>','','basic_html');
